'use strict';
(function () {
  const E = LANG === 'en', Q = [{"id":82912,"giver":"【工人】乔治","to":"【工人】乔治","type":"kill","target":"☆吸血仙子","count":20,"sc":"寂静林地","lv":67,"rw":{"gold":102,"items":[]},"tr":["Kan Ver!","Ne zaman Sessiz Koru'ya odun kesmeye gitsem şu ☆Kan Emici Periler kanımı emiyor. Kanım o kadar mı lezzetli? Şimdi kan vermenin tadına onlar baksın!","Kabul","Sen de kan verdin mi?","Hah hah, sonunda kanın bedelini ödediler!"],"en":["Give Blood!","Whenever I go logging in the Silent Woodland those ☆Bloodsucking Fairies drain my blood. Is it really that tasty? Now let them have a taste of giving blood!","Accept","Have you given blood too?","Ha ha, they finally paid the price in blood!"]},{"id":82913,"giver":"【美女炼金师】爱丽丝","to":"【美女炼金师】爱丽丝","type":"kill","target":"暗影巨魔","count":20,"sc":"寂静林地","lv":67,"rw":{"gold":153,"items":[["30024",1]]},"tr":["Trollerin Misillemesi","George Gölge Trollerini defalarca rahatsız etti; öfkelendiler ve misillemeye hazırlanıyorlar. Onlar saldırmadan planlarını bozmanı istiyorum. Birkaç trol öldür ki akılları başlarına gelsin.","Kabul","Tam bir baş belası.","Harika, planlarını durdurdun."],"en":["The Trolls Strike Back","George kept harassing the Shadow Trolls until they got angry, and now they are preparing to strike back. Ruin their plan before they do. Kill some trolls so they learn to behave.","Accept","What a troublemaker.","Wonderful, you stopped their plan."]},{"id":82914,"giver":"【美女炼金师】爱丽丝","to":"【工人】乔治","type":"talk","req":82913,"rw":{"gold":91,"items":[["30419",10],["30484",10]]},"tr":["George'u Uyar","George'a söyle, bir daha trollere bulaşmasın. Yoksa generale söylerim, ömrünün sonuna kadar trollerle yaşar.","Kabul","Ona ilet lütfen.","Ah, işin bu kadar büyüyeceğini düşünmemiştim. Uyarın için sağ ol."],"en":["A Warning for George","Tell George to stop provoking the trolls, or I will tell the General and he can live with the trolls for the rest of his life.","Accept","Pass it on to him.","Oh, I never thought it would get this serious. Thanks for the warning."],"lv":67},{"id":82915,"giver":"【兽医】詹姆斯","to":"【兽医】詹姆斯","type":"collect","target":"林地夜行者","count":10,"sc":"寂静林地","lv":67,"chance":0.5,"rw":{"gold":109,"items":[["37529",1],["30024",1]]},"tr":["Gece Avcısı Zehri","Son günlerde art arda zehirlenmeler oluyor. Koru Gece Avcılarının ısırdığından şüpheleniyorum. Panzehir yapabilmem için bana onların zehrinden topla.","Kabul","Sakın ısırılma.","Harika, hemen panzehiri hazırlamalıyım.","Gece Avcısı Zehri"],"en":["Nightstalker Venom","There has been a string of poisonings lately. I suspect bites from Woodland Nightstalkers. Collect some of their venom so I can make an antidote.","Accept","Do not get bitten.","Great, I must prepare the antidote at once.","Nightstalker Venom"]},{"id":82916,"giver":"【蠢蛋将军】米斯特","to":"【蠢蛋将军】米斯特","type":"kill","target":"☆恐惧卫士","count":20,"sc":"地下庙宇","lv":50,"rw":{"gold":102,"items":[["30419",10],["30484",10]]},"tr":["Korku Muhafızları","Tarikat Üssü'ndeki ☆Korku Muhafızlarına dikkat et; aklını bulandırır, soydaşları birbirine kırdırırlar. İnancını sağlam tutarsan onları yenersin.","Kabul","Sakın beynini yıkamalarına izin verme.","☆Korku Muhafızlarını yendin."],"en":["Fear Guards","Beware the ☆Fear Guards of the Cult Base. They cloud your mind and turn kin against kin. Keep your faith firm and you will defeat them.","Accept","Do not let them brainwash you.","You defeated the ☆Fear Guards."]},{"id":82917,"giver":"森林警卫官","to":"森林警卫官","type":"kill","target":"织网毒蜘蛛","count":30,"sc":"罗网林地","lv":69,"rw":{"gold":115,"items":[["30024",1]]},"tr":["Örümcek Ailesi (1)","Ağlı Koru'da büyük bir tehdit var: kraliçeleri ordu topluyor. İlk işimiz bu toplanmayı engellemek. Güç peşindeki Ağ Ören Zehirli Örümcekler kraliçeye katılıyor; sayılarını azaltmalısın.","Kabul","Örümceklerin ailesi kalabalıktır.","İyi iş çıkardın. Sıradaki adıma geçelim."],"en":["The Spider Family (1)","A great threat lurks in the Webbed Woodland: their queen is gathering an army. Our first task is to stop it. The Webspinner Venom Spiders are joining her in search of power, so thin their numbers.","Accept","Spiders have very large families.","Well done. On to the next step."]},{"id":82918,"giver":"森林警卫官","to":"森林警卫官","type":"kill","target":"剑蜘蛛","count":30,"sc":"罗网林地","lv":69,"req":82917,"rw":{"gold":132,"items":[["30024",1]]},"tr":["Örümcek Ailesi (2)","Ağlı Koru'daki Kılıç Örümceği ordusu kraliçenin öncü birliği. Onları yok edersek kraliçenin yuvasını ele geçirebiliriz. Bu zorlu görevi başarabilir misin?","Kabul","Kılıç Örümceklerinin kılıcına dikkat et.","İyi iş çıkardın. Kraliçenin savunma hattını yardık."],"en":["The Spider Family (2)","The Sword Spider army of the Webbed Woodland is the queen's vanguard. Wipe them out and we can take her nest. Can you handle this hard task?","Accept","Watch out for the Sword Spiders' blades.","Well done. We have broken through the queen's defenses."]},{"id":82919,"giver":"森林警卫官","to":"森林警卫官","type":"kill","target":"☆蜘蛛护卫","count":10,"sc":"罗网林地","lv":69,"req":82918,"rw":{"gold":80,"items":[["30419",10],["30484",10]]},"tr":["Örümcek Ailesi (3)","Lanet olsun, şu ☆Örümcek Muhafızlar da nereden çıktı? Bu son savunma hattı olmalı; kraliçeyle yüzleşmek üzereyiz. Bu hattı ancak sen yarabilirsin.","Kabul","Tehdit bitmek üzere.","Sonunda kraliçeyle yüzleşeceğiz."],"en":["The Spider Family (3)","Damn it, where did those ☆Spider Guards come from? This must be the last line of defense. We are about to face the queen, and only you can break through.","Accept","The threat is almost gone.","At last we will face the queen."]},{"id":82920,"giver":"森林警卫官","to":"森林警卫官","type":"kill","target":"☆【欺诈女王】科琳娜","count":1,"sc":"罗网林地","lv":69,"req":82919,"rw":{"gold":30,"items":[]},"tr":["Örümcek Ailesi (4)","Sonuna geldik. Hilekâr Kraliçe ile son savaşı yapacağız. Hazır mısın?","Kabul","Korktun mu?","Sonunda kraliçeyi yendik."],"en":["The Spider Family (4)","We have reached the end. It is time for the final battle with the Deceiver Queen. Are you ready?","Accept","Are you scared?","We have finally defeated the queen."]},{"id":82922,"giver":"【美女炼金师】爱丽丝","to":"【美女炼金师】爱丽丝","type":"kill","target":"堕落学者","count":15,"sc":"迷途林地","lv":71,"rw":{"gold":122,"items":[]},"tr":["Yozlaşmış Bilginler","Yozlaşmış Bilginler büyüleriyle bütün Kayıp Koru'yu bozdu: bitkiler çürüyor, hayvanlar değişiyor. Bana yardım et, o bilginleri öldür; canlılar daha fazla yozlaşmasın.","Kabul","Sakın orada sen de yozlaşma.","Harika, onları kurtardın."],"en":["Fallen Scholars","The Fallen Scholars have corrupted the whole Lost Woodland with their sorcery. Plants are rotting and animals are mutating. Help me: kill those scholars before more creatures fall.","Accept","Do not fall there yourself.","Wonderful, you saved them."]},{"id":82923,"giver":"【兽医】詹姆斯","to":"【兽医】詹姆斯","type":"collect","target":"堕落学者","count":10,"sc":"迷途林地","lv":71,"chance":0.5,"rw":{"gold":107,"items":[["39503",1],["30024",1]]},"tr":["Bilgin Cübbesi","Derler ki Kayıp Koru'daki Yozlaşmış Bilginlere hiçbir zehir işlemezmiş. Sırları ne? İpucunu cübbelerinde arayacağım. Bana birkaç tane getirebilir misin?","Kabul","Hekimliğim çok iyidir.","Bana biraz zaman ver, incelemeye başlıyorum.","Bilgin Cübbesi"],"en":["Scholar's Coat","They say no poison can harm the Fallen Scholars of the Lost Woodland. What is their secret? I want to look for clues in their coats. Can you bring me a few?","Accept","I am a very skilled healer.","Give me some time, I will start my research.","Scholar's Coat"]},{"id":82924,"giver":"森林警卫官","to":"森林警卫官","type":"kill","target":"灵魂收割者","count":10,"sc":"鲜血庙宇","lv":60,"rw":{"gold":140,"items":[["30024",1]]},"tr":["Ruhları Koru","Tarikat Üssü'nde Ruh Biçiciler insan ruhlarını acımasızca yok ediyor. Ruhları korumalıyız; bunun en iyi yolu Ruh Biçicileri yok etmek. Onlarla yüzleşecek yüreğin var mı?","Kabul","Ruhuna dikkat et.","Yardımın sayesinde ruhları koruduk."],"en":["Guard the Souls","In the Cult Base the Soul Reapers are mercilessly erasing human souls. We must guard the souls, and the best way is to destroy the reapers. Do you dare to face them?","Accept","Mind your soul.","Thanks to you, we kept the souls safe."]},{"id":82925,"giver":"【工人】乔治","to":"【工人】乔治","type":"kill","target":"无脑僵尸","count":20,"sc":"迷途林地","lv":71,"rw":{"gold":99,"items":[["30419",10],["30484",10]]},"tr":["Beyinsiz Zombiler","Heh heh, şu zombilerle oynamaya bayılırım; başsız sinekler gibi oraya buraya koşarlar. Beyinleri yok, hepsi ahmak. Artık bu bölgeden yok olmalarını istiyorum. Ne yapacağını biliyorsun, değil mi?","Kabul","Zombilere de ki: gelin biraz oynayalım.","Hah hah, gerçekten beyinleri yokmuş."],"en":["Brainless Zombies","Heh heh, I love playing with those zombies. They run around like headless flies. No brains, all idiots. Now I want them gone from this area. You know what to do, right?","Accept","Tell the zombies: come and play for a while.","Ha ha, they really have no brains."]},{"id":82926,"giver":"【兽医】詹姆斯","to":"【兽医】詹姆斯","type":"collect","target":"☆仙子邪术师","count":10,"sc":"迷途林地","lv":71,"chance":0.5,"rw":{"gold":82,"items":[]},"tr":["Büyü Tozu","Her derde deva bir ilaç malzemesi buldum: Kayıp Koru'daki perilerin üstünde. Onlardan biraz toz getirebilirsen George'un bel ağrısını iyileştirebilirim.","Kabul","Her derde deva bir iksir yapacağım.","Evet, işte bu toz.","Büyü Tozu"],"en":["Sorcery Dust","I have found an ingredient that cures everything, and the fairies of the Lost Woodland carry it. Bring me some of their dust and I can cure George's back pain.","Accept","I am going to make a cure-all potion.","Yes, this is the dust.","Sorcery Dust"]},{"id":82927,"giver":"【兽医】詹姆斯","to":"【工人】乔治","type":"talk","req":82926,"rw":{"gold":53,"items":[["30024",1]]},"tr":["İksiri Dene","Hah hah, başardım! Şimdi bu iksiri George'a götür, tadına baksın. İçtiği an bel ağrısı geçecek.","Kabul","Çabuk, içsin şunu.","(George iksiri bir dikişte içti) Aman tanrım, bu zehir mi? Ne kadar da kötü!"],"en":["Taste Test","Ha ha, it worked! Take this potion to George and let him taste it. The moment he drinks it, his back pain will be gone.","Accept","Hurry, make him drink it.","(George gulps the potion down) Good grief, is this poison? It tastes awful!"],"lv":67},{"id":82928,"giver":"【工人】乔治","to":"【兽医】詹姆斯","type":"talk","req":82927,"rw":{"gold":48,"items":[]},"tr":["Bana Eziyet Etmeyin!","Yalvarırım bana eziyet etmeyi bırakın! Çok acı çekiyorum! Beni susturmak mı istiyorsunuz? Aaaah! (George epey acı çekiyor gibi görünüyor.)","Kabul","Bırak beni! Öleyim daha iyi!","Hah hah hah, yine olmadı…"],"en":["Stop Tormenting Me!","I beg you, stop tormenting me! It hurts so much! Are you trying to silence me for good? Aaargh! (George looks like he is in real pain.)","Accept","Leave me alone! Just let me die!","Ha ha ha, failed again…"],"lv":67},{"id":82929,"giver":"【美女炼金师】爱丽丝","to":"【美女炼金师】爱丽丝","type":"collect","target":"污染者","count":10,"sc":"堕落林地","lv":70,"chance":0.5,"rw":{"gold":85,"items":[["30024",1]]},"tr":["Kirletici Cübbesi","Pis Kirleticiler! Ormanı bile bile yok ediyor, canlıları zehirliyorlar. Onları öldürmeme yardım eder misin? Yapabilirsen giydikleri cübbeleri getir, gücünü kanıtla.","Kabul","Sakın sana da bulaşmasınlar.","Harika, ne kadar çirkin olduklarını onlara göstereceğim.","Kirletici Cübbesi"],"en":["Defiler's Robe","Filthy Defilers! They ruin the forest on purpose and poison every living thing. Will you help me kill them? If you can, bring back the robes they wear to prove your strength.","Accept","Do not let them taint you.","Wonderful, I will show them how ugly they are.","Defiler's Robe"]},{"id":82930,"giver":"森林警卫官","to":"森林警卫官","type":"kill","target":"污染者","count":10,"sc":"堕落林地","lv":70,"rw":{"gold":72,"items":[["30419",10],["30484",10]]},"tr":["Kirliliği Önle","Yozlaşmış Koru'nun kirlenmesini önle! Kirleticileri durdur! Öldür!","Kabul","Sağ bırakma!","İyi iş çıkardın, orayı kurtarmalıyız."],"en":["Stop the Pollution","Stop the pollution of the Fallen Woodland! Stop the Defilers! Kill!","Accept","Leave none alive!","Well done, we must save that place."]},{"id":82931,"giver":"【工人】乔治","to":"森林警卫官","type":"talk","rw":{"gold":75,"items":[["30024",1]]},"tr":["Asıl Katil Kim","Kardeşim Paul öldürüldü. Orman Muhafız Subayı'na sorar mısın, katil kim? Kardeşimi öldürmeye kim cüret eder!","Kabul","Katili bulacağım!","Ne? George'un kardeşi mi öldürülmüş?"],"en":["Who Is the Killer","My brother Paul has been killed. Could you ask the Forest Guard Officer who did it? Who would dare to kill my brother!","Accept","I will find the killer!","What? George's brother was killed?"],"lv":67},{"id":82932,"giver":"森林警卫官","to":"【工人】乔治","type":"collect","target":"☆剧毒撕裂者","count":1,"sc":"堕落林地","lv":70,"chance":1,"req":82931,"rw":{"gold":132,"items":[["30024",1]]},"tr":["Katili Ara","Yılların tecrübesiyle söylüyorum, ☆Zehirli Parçalayıcılardan şüpheleniyorum. Çok gizli hareket ederler; görüş alanlarına girersen sonun gelmiş demektir. Kayıp Koru'dalar. Bir ipucu bulursan doğrudan George'a söyle.","Kabul","O yaratıklara dikkat et.","Aaah, Paul'un intikamını alacağım!","Paul'un Hatırası"],"en":["Find the Killer","From my years of experience, I suspect the ☆Venomous Rippers. They move in secret, and if they see you, your end has come. They are in the Lost Woodland. If you find a clue, tell George directly.","Accept","Be careful around those creatures.","Aaah, I will avenge Paul!","Paul's Keepsake"]},{"id":82933,"giver":"【工人】乔治","to":"【工人】乔治","type":"kill","target":"☆剧毒撕裂者","count":20,"sc":"堕落林地","lv":70,"req":82932,"rw":{"gold":107,"items":[["30419",10],["30484",10]]},"tr":["Kardeşimin İntikamı","Canım kardeşim, nasıl da feci öldün, hüüü… İntikamını alacağım. Dostum, sen olmasan kardeşimin ölümünün gerçeğini asla öğrenemezdim. Bir kez daha yardım et, o ☆Zehirli Parçalayıcıların hepsini öldür!","Kabul","Hüüü hüüü…","Sağ ol, hüüü hüüü…"],"en":["Revenge for My Brother","My dear brother, what a terrible death, boo-hoo… I will avenge you. Friend, without you I would never have learned the truth. Help me once more: kill every one of those ☆Venomous Rippers!","Accept","Boo-hoo…","Thank you, boo-hoo…"]},{"id":82934,"giver":"【蠢蛋将军】米斯特","to":"【兽医】詹姆斯","type":"talk","rw":{"gold":64,"items":[["30024",1]]},"tr":["Troller Don mu Giyer?","Çok tuhaf, buradaki troller don giyiyor?! James'e sorar mısın, bunun sebebi ne?","Kabul","Çirkin troller don giyiyor.","Benden ne istiyorsun?"],"en":["Do Trolls Wear Underpants?","How strange, the trolls here wear underpants?! Could you ask James what the reason is?","Accept","Ugly trolls in underpants.","What do you want from me?"],"lv":50},{"id":82935,"giver":"【兽医】詹姆斯","to":"【兽医】詹姆斯","type":"collect","target":"☆鬼巨魔","count":1,"sc":"堕落林地","lv":70,"chance":1,"req":82934,"rw":{"gold":58,"items":[["30024",1]]},"tr":["Don Topla","Onlardan birinin donunu bana getir, incelemek istiyorum. Yozlaşmış Koru'da yaşıyorlar.","Kabul","Ne tuhaf.","(Don mide bulandırıcı bir koku yayıyor) Bu da ne böyle.","Trol Donu"],"en":["Collect Underpants","Bring me the underpants of one of them, I want to study them. They live in the Fallen Woodland.","Accept","How odd.","(The underpants give off a sickening smell) What on earth is this.","Troll Underpants"]},{"id":82936,"giver":"【兽医】詹姆斯","to":"【蠢蛋将军】米斯特","type":"talk","req":82935,"rw":{"gold":58,"items":[["30024",1]]},"tr":["Gaz Bombası!!","Bu donu generale götür de trolleri inceleme sevdasından vazgeçsin. Bu resmen delilik.","Kabul","(James yere kustu) İğrenç.","Ah, çok pis kokuyor! Bu resmen gaz bombası!"],"en":["Stink Bomb!!","Take these underpants to the General so he gives up his idea of studying trolls. This is pure madness.","Accept","(James throws up on the floor) Disgusting.","Argh, it stinks! This is a real stink bomb!"],"lv":67},{"id":82937,"giver":"【蠢蛋将军】米斯特","to":"【蠢蛋将军】米斯特","type":"kill","target":"☆鬼巨魔","count":20,"sc":"堕落林地","lv":70,"req":82936,"rw":{"gold":55,"items":[["30419",10],["30484",10]]},"tr":["Belanızı Aradınız!!","Beni kızdırdılar, bu resmen belayı aramak! Şu ☆Hayalet Trollerin canı cehenneme!","Kabul","(General yere kustu) Bu gerçekten iğrenç.","Hah hah, iyi iş genç!"],"en":["Asking for Death!!","They made me angry, and that is asking for death! To hell with those ☆Ghost Trolls!","Accept","(The General throws up on the floor) This is truly disgusting.","Ha ha, well done, youngster!"]},{"id":81767,"giver":"森林警卫官","to":"森林警卫官","type":"kill","target":"凶恶蝙蝠","count":10,"sc":"传送回廊","lv":50,"rw":{"gold":200,"items":[["30024",1]]},"tr":["Vebalı Yarasalar","Sıkı savunmamız sayesinde ☆tarikatçılar buraya sızıp ortalığı karıştıramadı. Ama geceleri yeşil yarasalar ortaya çıkıyor. Belki de trollere hastalığı bulaştırıp onları değiştiren bu yarasalardır. Onları öldürürsek işler düzelebilir.","Kabul","Tarikat sandığımız kadar basit değilmiş.","Yarasalar temizlendi; troller artık kudurmayacak."],"en":["Plague Bats","Thanks to our tight defense the ☆cultists have never slipped out to cause trouble. But at night some green bats appear. Perhaps these bats infected the trolls and made them mutate. Kill the bats and things may take a turn for the better.","Accept","The cult is not as simple as we thought.","With the bats cleansed, the trolls will no longer go berserk."]},{"id":80476,"giver":"警卫卡鲁","to":"警卫卡鲁","type":"collect","target":"森林巨魔","count":10,"sc":"巨魔森林","lv":28,"chance":0.5,"rw":{"gold":113,"items":[["30033",5]]},"tr":["Anlaşılmaz Bir Merak","Şehir Beyi'nin tuhaf merakından şikâyet edecek değilim; bütün vaktim ormandaki şu canavarlarla, trollerle uğraşmakla geçiyor. Evet, bedenleri taş gibi olan bu yaratıklara karşı elimden pek bir şey gelmiyor. Onlarla aptalca güç yarıştırmak istemem. Bu işi denemek ister misin?","Kabul","Bu ormanın her yanı tuhaflık dolu.","Sakın bana fıkra anlatıp birbirlerinin boynuzlarını söktürdüğünü söyleme.","Trol Boynuzu"],"en":["A Peculiar Hobby","I will not complain about the Lord's odd hobby, because all my time goes to dealing with the monsters of this forest: the trolls. Yes, these rock-hard brutes leave me almost helpless, and I am not fool enough to match strength with them. Want to try this challenge?","Accept","Everything about this forest is strange.","Do not tell me you got them to pull out each other's horns by telling jokes.","Troll Horn"]},{"id":80474,"giver":"警卫卡鲁","to":"奔马城城主","type":"talk","req":80476,"rw":{"gold":60,"items":[["30033",5]]},"tr":["Uzun Yol","Elimden gelse seninle dönerdim ama görevim bununla bitmiyor. Geldiğin yoldan dön ve bunları Şehir Beyi'ne ver. Bu işi hâlâ hatırlıyor mu, onu da bilmiyorum.","Kabul","Burada fazla uzun kaldım.","Trol boynuzu mu? Bunlarla ne yapmak istediğimi hatırlamam biraz zaman alacak."],"en":["The Long Journey","If I could, I would go back with you, but my duties do not end here. Follow the road you came by and hand these to the Lord. I wonder if he even remembers this matter.","Accept","I have been here far too long.","Troll horns? I will need some time to remember what I wanted them for."],"lv":28},{"id":81741,"giver":"警卫卡鲁","to":"警卫卡鲁","type":"collect","target":"☆饥饿的巨魔","count":10,"sc":"巨魔森林","lv":28,"chance":0.5,"rw":{"gold":102,"items":[]},"tr":["Daha Çok Boynuz","Belki de dikkatimizi şu yeşil trollere vermeliyiz. Orman Trollerinden açıkça farklı gördüğüm tek şey bu. Git, bir dene.","Kabul","Orman Trollerinden daha saldırgan görünüyorlar.","Bunlarla Şehir Beyi memnun kalır sanırım.","Yeşil Boynuz"],"en":["More Horns","Perhaps we should turn our attention to those green trolls. That is the one clear difference from the Forest Trolls that I can see. Go and give it a try.","Accept","They seem more aggressive than the Forest Trolls.","With these, I think the Lord will be satisfied.","Green Horn"]},{"id":81742,"giver":"警卫卡鲁","to":"警卫卡鲁","type":"kill","target":"☆巨魔摧毁者","count":10,"sc":"巨魔森林","lv":28,"req":81741,"rw":{"gold":108,"items":[["30024",1]]},"tr":["Lanet Pusucular","Bu iri kıyım ahmakların pusu kurabileceği hiç aklıma gelmezdi; büyük bir keşif bu. Burada yıllardır yaşamanın verdiği çeviklik olmasa şimdi ardımdan ancak dua edebilirdin. Şu Yıkıcılara günlerini göstermeliyim.","Kabul","Onlarla baş etmek için kafa yorman gerek.","Yumruklarından nasıl kaçtın?"],"en":["Damned Ambushers","I never imagined these big oafs could set an ambush. What a discovery. Without the quick wits I gained from living here so long, you would now only be able to pray for me. I must teach those Destroyers a lesson.","Accept","You will need to use your head to deal with them.","How did you dodge their fists?"]},{"id":81743,"giver":"警卫卡鲁","to":"奔马城城主","type":"talk","req":81742,"rw":{"gold":70,"items":[["11242",1]]},"tr":["Dolgun Ücret","Altını sevmeyen yoktur; sana verdiğim iş kadar kolayı da yok. Biraz yorulman yeter, dolgun bir ücret alırsın. Daha ne düşünüyorsun, bu paketi Şehir Beyi'ne götür.","Kabul","Bu lanet yerden nefret ediyorum.","Vay, her gelişinde beni şaşırtıyorsun."],"en":["A Handsome Fee","Nobody dislikes gold, and no job is as easy as the one I am giving you. Just spend a little effort and you earn a handsome fee. Why hesitate? Take this package to the Lord.","Accept","I hate this damned place.","Wow, you surprise me every time you come."],"lv":28},{"id":82555,"giver":"民兵队长","to":"民兵队长","type":"kill","target":"野猪","count":5,"sc":"阳光森林","lv":7,"req":80004,"rw":{"gold":112,"items":[["30024",1]]},"tr":["Yaban Domuzu Derdi","Güneşli Orman'daki domuzlar gitgide çoğalıyor ve gündelik hayatımızı fena hâlde aksatıyor. Bu yaban domuzları çok saldırgandır. Bize biraz yaşam alanı açmalısın.","Kabul","Hâlâ burada ne arıyorsun?","İyi iş çıkardın genç."],"en":["Boar Trouble","The boars of the Sunny Forest keep multiplying and are seriously disrupting our daily life. These wild boars are very aggressive. I think you should clear some living space for us.","Accept","What are you still doing here?","Well done, youngster."]},{"id":81704,"giver":"民兵队长","to":"民兵队长","type":"kill","target":"毒蛇帮路匪","count":10,"sc":"阳光森林","lv":7,"req":82555,"rw":{"gold":139,"items":[["30024",1]]},"tr":["Engerek Çetesi","Guanlin Kasabası öteden beri oduncuklukla geçinir. Güçlerine güvenen bazı tembeller odun kesip dönen kasabalıları soymaya başladı! Son günlerde iş iyice azıttı; gelip geçen tüccarlar da zarar görüyor, kasabanın adı lekeleniyor. Git ve onları adalete teslim et.","Kabul","Lanet Engerek Çetesi, başlarına gelecek var!","Harika, görünen o ki elinden iş geliyor!"],"en":["The Viper Gang","Guanlin Town has always lived off logging. Some idlers who rely on their strength have begun robbing townsfolk on their way back from cutting wood! Lately it has gotten worse; passing merchants suffer too, and the town's reputation is ruined. Go and bring them to justice.","Accept","Damned Viper Gang, they have it coming!","Excellent, it seems you do have some skill!"]},{"id":81705,"giver":"民兵队长","to":"观林镇镇长","type":"talk","req":81704,"rw":{"gold":85,"items":[["30024",1]]},"tr":["Muhtara Müjde","Seni küçümsemişim. Kim bilir, belki bir gün benim gibi büyük bir milis komutanı olursun! Tecrübeme göre artık başarılarını muhtara anlatabilirsin.","Kabul","Gelecek vaat eden bir çocuk.","Bu harika! Tam da adama ihtiyacımız vardı!"],"en":["Report to the Mayor","It seems I underestimated you. Who knows, one day you might become a great militia captain like me! In my experience, it is time to report your great deeds to the Mayor.","Accept","A promising kid.","This is wonderful! We are short of hands!"],"lv":7},{"id":81706,"giver":"观林镇镇长","to":"观林镇镇长","type":"collect","target":"蜘蛛","count":5,"sc":"阳光森林北","lv":10,"chance":0.5,"req":81705,"rw":{"gold":168,"items":[["30024",1]]},"tr":["Aklını Kullan","Engerek Çetesi laftan anlamıyor; onlara acıyı tattırmalıyız! Güneşli Orman Kuzey'e git, birkaç örümcek öldür ve bana örümcek salgısı getir. Ne işe yarayacağını biz biliriz. (Muhtar tuhaf bir kahkaha attı.)","Kabul","Şu haydut Engerek Çetesi! Onlara gününü göstermezsem beni kolay lokma sanarlar!","Bu, planımızın ilk adımı.","Örümcek Salgısı"],"en":["Use Your Wits","The Viper Gang will not listen to reason, so we must make them suffer! Go to Sunny Forest North, kill some spiders and bring me spider slime. We have our uses for it. (The Mayor lets out a strange laugh.)","Accept","Those Viper Gang bandits! If I do not teach them a lesson, they will think I am a pushover!","This is the first step of our plan.","Spider Slime"]},{"id":81707,"giver":"观林镇镇长","to":"民兵队长","type":"kill","target":"毒蛇帮精英","count":10,"sc":"阳光森林南","lv":13,"rw":{"gold":121,"items":[["30024",1]]},"tr":["Engerek Çetesine Ceza","Tamam, zehri silahına sürdüm. Git, Engerek Çetesi Seçkinlerini kes; acı içinde ölsünler! Bitirince Milis Komutanı ile konuş. Adamlarım ceza yöntemlerime hayran kalsın!","Kabul","Ceza yöntemlerim hep pek ustacadır, öyle değil mi?","Muhtar böyle mi oldu…"],"en":["Punish the Viper Gang","Good, I have smeared the venom on your weapon. Go and cut down the Viper Gang Elites, and let them die in agony! When you are done, talk to the Militia Captain. I want my men to admire my methods of punishment!","Accept","My methods of punishment are always so clever, are they not?","So the Mayor has become like this…"]},{"id":81708,"giver":"观林镇镇长","to":"民兵队长","type":"kill","target":"恶作剧仙子","count":10,"sc":"阳光森林南","lv":13,"rw":{"gold":158,"items":[["30024",1]]},"tr":["Lanet Sinekler","Güneşli Orman Güney'de sinek kadar iğrenç Yaramaz Periler var; insanın sinirini bozuyorlar! Silahınla onlara beni kızdırmanın sonunu göster! Bitirince Milis Komutanı ile konuş. Adamlarım ceza yöntemlerime hayran kalsın!","Kabul","O iğrenç sinekler gücümü tatsın!","Ne kadar acımasızca!"],"en":["Hateful Flies","In Sunny Forest South there are Prankster Fairies as disgusting as flies, and they get on my nerves! Show them with your weapon what happens to those who anger me! When you are done, talk to the Militia Captain. I want my men to admire my methods of punishment!","Accept","Let those disgusting flies taste my power!","How cruel!"]},{"id":81643,"giver":"护民官","to":"护民官","type":"kill","target":"☆毒蛇帮虐杀者","count":8,"sc":"阳光森林东","lv":18,"rw":{"gold":169,"items":[]},"tr":["Engerek Çetesini Temizle","Engerek Çetesi artık Guanlin Kasabası'na zarar veremiyor. Bu fırsatı kaçırmayalım, hepsini Güneşli Orman'dan sürelim. Başaracağına inanıyorum! Geriye yalnızca ☆Engerek Çetesi Kasapları kaldı.","Kabul","Buraya bir daha adım atmasınlar.","Guanlin Kasabası'na huzurunu geri verdin, teşekkürler."],"en":["Clear Out the Viper Gang","The Viper Gang can no longer harm Guanlin Town, so let us seize this chance and drive them all out of the Sunny Forest. I believe you can do it! Only the ☆Viper Gang Butchers are left.","Accept","Do not let them set foot here again.","You have brought peace back to Guanlin Town. Thank you."]},{"id":81632,"giver":"护林游侠","to":"护林游侠","type":"kill","target":"☆精英护卫","count":5,"sc":"阳光森林东","lv":18,"rw":{"gold":130,"items":[["30024",1]]},"tr":["Seçkin Muhafızlar","Bu görev çok zorlu. Üstesinden gelip gelemeyeceğini en iyi sen bilirsin; ama gözlerinden kendine güvendiğini okuyorum, o yüzden sana inanıyorum. ☆Seçkin Muhafızlar Güneşli Orman Doğu'nun derinliklerinde.","Kabul","Umarım sağ salim dönersin.","Sandığımdan çok daha güçlüymüşsün!"],"en":["Elite Guards","This task is very hard. Only you know whether you can handle it, but I can see in your eyes that you are full of confidence, so I believe in you. The ☆Elite Guards are deep in Sunny Forest East.","Accept","I hope you come back safely.","You are much stronger than I imagined!"]},{"id":81626,"giver":"杰西","to":"护林游侠","type":"talk","rw":{"gold":102,"items":[["30016",5],["30019",5],["30024",1]]},"tr":["Kayıt","Hey, oradaki genç! Bu günlerde Guanlin Kasabası'nda çok eğlenceli bir etkinlik var. Seni Orman Korucusu'na önerdim bile; hemen git, kaydını yaptır.","Kabul","","Oo! Gerçekten güçlü görünüyorsun."],"en":["Sign Up","Hey, you there, youngster! Guanlin Town is holding a very interesting event these days. I have already recommended you to the Forest Ranger, so hurry and sign up with him.","Accept","","Oh! You really do look strong."],"lv":18},{"id":81627,"giver":"护林游侠","to":"护林游侠","type":"kill","target":"森林蝰蛇","count":10,"sc":"阳光森林南","lv":13,"req":81626,"rw":{"gold":112,"items":[["30016",5],["30019",5],["30024",1]]},"tr":["Büyük Yılan Avı","Bu etkinlikte Güneşli Orman'ın güneyindeki engerekler yok edilecek. Bu yaratıklar artık biz insanlardan korkmuyor. Git ve onlara insan gücünün ne kadar büyük olduğunu göster!","Kabul","Senden çok şey bekliyorum.","Evet! Beni hayal kırıklığına uğratmadın!"],"en":["The Great Snake Hunt","The goal of this event is to wipe out the vipers in the south of the Sunny Forest. These creatures no longer fear us humans. Go and show them how mighty human strength is!","Accept","I expect great things from you.","Yes! You did not disappoint me!"]},{"id":81628,"giver":"护林游侠","to":"杰西","type":"talk","req":81627,"rw":{"gold":72,"items":[["30016",5],["30019",5],["30024",1]]},"tr":["Jessie'ye Haber Ver","Bu etkinlikte çok başarılıydın ve büyük takdir topladın. Git, bunu Jessie'ye anlat. Seninle gurur duyacaktır.","Kabul","","Harikasın! Beklediğimin çok üstünde!"],"en":["Tell Jessie","You performed brilliantly in this event and earned high praise. Go and tell Jessie about it. She will surely be proud of you.","Accept","","You are amazing! Far beyond what I expected!"],"lv":18},{"id":80035,"giver":"疯子","to":"疯子","type":"kill","target":"森林蝰蛇","count":10,"sc":"阳光森林南","lv":13,"rw":{"gold":88,"items":[["30033",5],["30024",1]]},"tr":["Periler ve Yılanlar","Aaah, Güneşli Orman Güney'de neden bu kadar çok sinir bozucu yaratık var? Orada bir türlü rahat uyuyamıyorum. Sen, evet sen, başkasına bakma, sana diyorum: git, onların işini bitir.","Kabul","Hâlâ burada ne dikiliyorsun?","Oley! İyi iş!"],"en":["Fairies and Snakes","Aaah, why are there so many annoying creatures in Sunny Forest South? They never let me sleep in peace there. You, yes you, do not look at anyone else, I mean you: go and get rid of them for me.","Accept","Why are you still standing here?","Oh yeah! Nicely done!"]},{"id":81620,"giver":"护林游侠","to":"护林游侠","type":"collect","target":"☆毒蛇帮虐杀者","count":10,"sc":"阳光森林东","lv":18,"chance":0.5,"rw":{"gold":125,"items":[]},"tr":["Kasapların Zırhı","Guanlin milislerini güçlendirmek için onlara sağlam zırh yaptırmam gerek. Duyduğuma göre ☆Engerek Çetesi Kasaplarının giydiği zırh bu iş için çok iyiymiş. Haydi genç, bana birkaç tane getir.","Kabul","Bu zırhlar milisleri güçlendirmenin en önemli şartı.","Güzel, beni hayal kırıklığına uğratmadın.","Kasap Zırhı"],"en":["The Butchers' Armor","To strengthen the Guanlin militia I need to forge sturdy armor for them. I hear the armor worn by the ☆Viper Gang Butchers is an excellent choice. Go on, youngster, bring me some.","Accept","This armor is the key to making the militia stronger.","Good, you did not disappoint me.","Butcher Armor"]},{"id":81644,"giver":"民兵队长","to":"民兵队长","type":"collect","target":"☆精英护卫","count":5,"sc":"阳光森林东","lv":18,"chance":0.5,"rw":{"gold":98,"items":[]},"tr":["Seçkin Zırh","Güneşli Orman Doğu'daki ☆Seçkin Muhafızlar gitgide çoğalıyor. Oraya gidip zırhlarını toplamanı istiyorum; ne kadar çok olursa o kadar iyi. Vakit dar, çabuk git gel.","Kabul","Buradaki milisleri güçlü kılacağım.","Teşekkürler, bu kadarı yeter. Şimdi zırhları dövmeye başlayacağım.","Seçkin Zırh Parçası"],"en":["Elite Armor","The ☆Elite Guards in Sunny Forest East keep growing in number. I need you to go there and collect their armor, the more the better. Time is short, so be quick.","Accept","I will make the militia here strong.","Thank you, this is enough. Now I will start forging the armor.","Elite Armor Plate"]},{"id":81621,"giver":"护林游侠","to":"民兵队长","type":"talk","req":80039,"rw":{"gold":59,"items":[]},"tr":["Durumu Bildir","Milis Komutanı'na Kasapların püskürtüldüğünü söylemeni istiyorum. Umarım bundan sonraki işleri o düzenler.","Kabul","","Haber verdiğin için sağ ol. Posta güverciniyle üstlerime danışmam gerek."],"en":["Report In","Please tell the Militia Captain that the Butchers have been driven back. I hope he can arrange what comes next.","Accept","","Thank you for letting me know. I need to send a carrier pigeon and consult my superiors."],"lv":18},{"id":81622,"giver":"民兵队长","to":"护林游侠","type":"talk","req":81621,"rw":{"gold":71,"items":[]},"tr":["Yeni Görev","Bence şimdi gevşemenin sırası değil; en azından Engerek Çetesi meselesi tam çözülmedi. Sıradaki yeni görevin bu.","Kabul","","Hmm… Mesele gerçekten de tam çözülmüş değil."],"en":["A New Task","I do not think this is the time to relax. At the very least, the Viper Gang problem is not fully solved. That is your next task.","Accept","","Hmm… The matter really is not fully settled."],"lv":7},{"id":81648,"giver":"民兵队长","to":"护民官","type":"talk","rw":{"gold":119,"items":[]},"tr":["Guanlin'in Umudu","Kasaba huzursuz; hain Sadinman intikam planını hazırlamaya başladı. Guanlin Kasabası yok mu olacak? Bunu mutlaka engellemelisin. Çabuk, Halk Koruyucusu'na git ve bu işi görüş.","Kabul","","Genç, durum ciddi. Guanlin Kasabası'nı mutlaka kurtarmalısın."],"en":["The Hope of Guanlin","The town is in turmoil, and the traitor Sadinman has begun preparing his revenge. Is Guanlin Town about to be destroyed? You must stop this from happening. Quickly, go and discuss it with the Tribune.","Accept","","Youngster, the situation is grave. You must save Guanlin Town."],"lv":7},{"id":81649,"giver":"护民官","to":"民兵队长","type":"talk","req":81648,"rw":{"gold":118,"items":[["30024",1]]},"tr":["Guanlin'in Kurtarıcısı","Artık çok güçlendin; herkes seni Guanlin Kasabası'nın kurtarıcısı olarak görüyor. Burayı mutlaka kurtarmalısın, sana güveniyoruz. Milis Komutanı'na söyle, sana destek olsun; Sadinman mutlaka yok edilmeli.","Kabul","","Cesur genç, git ve bir mucize yarat."],"en":["The Savior of Guanlin","You have grown very strong, and everyone sees you as the savior of Guanlin Town. You must save this place, we are counting on you. Tell the Militia Captain to support you. Sadinman must be destroyed.","Accept","","Brave youth, go and work a miracle."],"lv":18},{"id":81650,"giver":"民兵队长","to":"民兵队长","type":"kill","target":"☆☆【叛徒】萨丁曼","count":1,"sc":"阳光森林东","lv":18,"req":81649,"rw":{"gold":16,"items":[]},"tr":["Sadinman'a Meydan Oku","Git, Sadinman'a meydan oku. Mutlaka sağ dön!","Kabul","Silahını al ve savaş!","Sadinman yenildi mi? Bu bir mucize! Sen kasabayı kurtaran kahramansın!"],"en":["Challenge Sadinman","Go and challenge Sadinman. Make sure you come back alive!","Accept","Take your weapon and fight!","Sadinman has been defeated? It is a miracle! You are the hero who saved the town!"]},{"id":81651,"giver":"民兵队长","to":"观林镇镇长","type":"talk","req":81650,"rw":{"gold":41,"items":[["10588",1]]},"tr":["Guanlin'in Kahramanı","Harika, sen bizim kahramanımızsın; Sadinman bir daha buraya saldırmaya cesaret edemez. Muhtara git, hak ettiğin ödülü verecek.","Kabul","","Vay! Demek herkesi kurtaran sensin; kahramanlar genç yaşta çıkarmış. Bu hak ettiğin ödül, al."],"en":["The Hero of Guanlin","Wonderful, you are our hero, and Sadinman will never dare attack this place again. Go to the Mayor, he will give you the reward you deserve.","Accept","","Well! So you are the one who saved everyone. Heroes truly do emerge young. This is the reward you deserve, take it."],"lv":7},{"id":80143,"giver":"神眼队长","to":"神眼队长","type":"kill","target":"变异黑寡妇","count":10,"sc":"噩梦平原东","req":80144,"rw":{"gold":139,"items":[["30126",1]]},"lv":24,"tr":["Etkin Savunma (3)","Buradaki görevimiz gözlem ama içeri girip hepimizi ısırıp öldürmek isteyen haddini bilmez yaratıklar hep olur. Genelde çözümümüz şudur: birkaçını öldürüp ders vermek. Ama ne yazık ki bu hayvanlar çok aptal… Son zamanlarda Mutant Karadullar iyice azıttı; git, onlara bir ders ver.","Kabul","Dikkat et; o kadar aptalca davranırsan hayvanlar bizi kolay lokma sanar, başımız belaya girer.","Güzel, ders verme tarzın sert ve doğrudan; memnunum."],"en":["Active Defense (3)","Our job here is to watch, but there are always ignorant creatures that want to get in and bite us all to death. Our usual solution: kill some of them to teach them a lesson. Unfortunately, these beasts are very stupid… Lately the Mutant Black Widows have grown bolder; go and give them a lesson.","Accept","Mind yourself; if you act so foolishly that the beasts think we're easy prey, we'll be in big trouble.","Good, your teaching style is strict and direct; I'm pleased."]},{"id":80144,"giver":"神眼队长","to":"神眼队长","type":"kill","target":"鸡蛇","count":10,"sc":"噩梦平原中部","req":80145,"rw":{"gold":82,"items":[["30126",1],["10050",1],["10068",1],["10907",1]]},"lv":23,"tr":["Etkin Savunma (2)","Kokatris çok tehlikeli bir yaratıktır; insan yemez ama bir ısırığı bile sıradan birini zehirleyip öldürür. Sen sıradan biri değilsin, değil mi? Git, işlerini bitir.","Kabul","Zehirlendin mi? Yoksa zehirlenmekten mi korkuyorsun?","Artık dışarı çıkınca yaprak yığınına saklanmış bir kokatrise basmaktan pek korkmam."],"en":["Active Defense (2)","The cockatrice is a very dangerous creature; it doesn't eat people, but a single bite will poison an ordinary person to death. You're no ordinary person, right? Go and deal with them.","Accept","Are you poisoned? Or just afraid of being poisoned?","Now I needn't worry so much about stepping on a cockatrice hiding in the leaves."]},{"id":80145,"giver":"神眼队长","to":"神眼队长","type":"kill","target":"影狼","count":10,"sc":"噩梦平原中部","req":80553,"rw":{"gold":116,"items":[["30033",5],["30030",5],["30126",1]]},"lv":23,"tr":["Etkin Savunma (1)","Birçok gölge kurt başkalarının evinde dolaşmaya bayılır. Bazıları… bizi ısırıp öldürür. Bu kurtlar sürekli kampımıza sızmaya çalışıyor, önlemek imkânsız. Git, kampa fazla yaklaşanların icabına bak.","Kabul","Az önce bir gölge kurdu kendim öldürdüm; işin bitmemiş.","Fena değil; kurt pisliği olmayan kamp çok daha temiz."],"en":["Active Defense (1)","Many shadow wolves love to roam other people's homes. Some of them… bite us to death. These wolves keep trying to slip into our camp, and it's impossible to stop them all. Go and deal with the ones that come too close.","Accept","I just killed a shadow wolf myself; your job isn't done.","Looks good; a camp without wolf droppings is much cleaner."]},{"id":80146,"giver":"夜精灵望气士","to":"特派武官","type":"talk","req":80554,"rw":{"gold":108,"items":[["30033",10]]},"lv0":19,"tr":["Ucube Avı","Bu sislerde yoğun bir hayvan kokusu var. Kampın yakınında tehlikeli ve güçlü mutant yaratıklar türediğinden şüpheleniyorum. Neyse ki tapınak bize yardım için Savaşçılar Loncası'ndan bir Özel Ataşe gönderdi; git, onunla konuş, seni o yönlendirecek.","Kabul","Özel Ataşe ile konuş.","Güzel!"],"en":["Hunting the Beasts","There's a heavy scent of beasts in this mist. I suspect dangerous, powerful mutant creatures have appeared near the camp. Luckily the temple sent us a Military Attaché from the Warrior Guild; go and talk to him, he'll direct you.","Accept","Talk to the Military Attaché.","Good!"],"lv":24},{"id":80147,"giver":"特派武官","to":"特派武官","type":"collect","target":"放养肉蜘蛛","count":10,"sc":"噩梦平原西","chance":0.5,"req":80146,"rw":{"gold":115,"items":[["30126",1]]},"lv":29,"tr":["Zehirli Diş","Birkaç Besi Örümceği kampa yakın bir yerde yuva yapıyor… Bir sürü yavru doğurmalarını bekleyip sonra temizlik yapmak istemem. Git, onları öldür ve zehirli dişlerini sök.","Kabul","Ne bekliyorsun? Örümcekler gittikçe çoğalacak.","Ne güzel iki zehirli diş… ha ha.","Zehirli Örümcek Dişi"],"en":["Venom Fangs","Some Ranch Spiders are nesting not far from camp… I don't want to wait for a swarm of spiderlings before cleaning up. Go, kill them and pull out their venom fangs.","Accept","What are you waiting for? There will only be more spiders.","What lovely venom fangs… ha ha.","Venomous Spider Fang"]},{"id":80149,"giver":"特派武官","to":"特派武官","type":"collect","target":"☆☆羽翼蝙蝠","count":1,"sc":"噩梦平原南","chance":1,"req":80147,"rw":{"gold":95,"items":[["30126",1]]},"lv":27,"tr":["Gece Gölgesi Pençesi","Kötü bir haber: Kâbus Ovası'nda dolaşan dev ☆☆Kanatlı Yarasa kampımızı tehdit etmeye başladı; sayısız yolcu onun pençesinde can verdi. Onu öldürüp pençesini getirmeni istiyorum.","Kabul","☆☆Kanatlı Yarasa bir kez öfkelenirse her şey için çok geç olur; hızlı davranmalısın.","Bu dev pençeye bakınca sağken nasıl olduğunu hayal edebiliyorum… Yardımın için teşekkürler.","Gece Gölgesi Pençesi"],"en":["Nightshade Claw","Bad news: the giant ☆☆Winged Bat roaming the Nightmare Plain has begun threatening our camp; countless travelers have died in its claws. I want you to kill it and bring back its claw.","Accept","Once the ☆☆Winged Bat is enraged it'll be too late for everything; you must act fast.","Looking at this huge claw I can picture what it was like alive… Thank you for your help.","Nightshade Claw"]},{"id":80150,"giver":"特派武官","to":"特派武官","type":"collect","target":"钻地蠕虫","count":5,"sc":"噩梦平原南","chance":0.6,"req":80149,"rw":{"gold":157,"items":[["30126",1]]},"lv":27,"tr":["Solucan Gözü","Adamlarımdan biri bir solucan tarafından ısırıldı; ona saldıranın Toprak Delen Solucan olduğunu söylüyor. Hekimin ilaçları işe yaramıyor; adamımı kurtarmak için o solucanları bulup gözlerini oymalısın… Bu riske girer misin?","Kabul","Lütfen, o kadar dayanamaz.","Ne kinli bir göz… Bunları hemen hekime götürüyorum. Bu da adamımı kurtardığın için küçük bir hediyem.","Solucan Gözü"],"en":["Worm Eyes","One of my men was bitten by a worm; he says it was a Burrowing Worm. The healer's medicine isn't working; you must find those worms and dig out their eyes to save him… Will you take the risk?","Accept","Please, he can't hold out that long.","What a spiteful eye… I'll take these to the healer at once. And this is a small token of thanks for saving my man.","Burrowing Worm Eye"]},{"id":80152,"giver":"特派武官","to":"特派武官","type":"talk","req":80150,"rw":{"gold":68,"items":[]},"lv0":19,"tr":["Uğursuz Tılsım","(Topladığın garip rünlü küçük sütunda yoğun bir kara büyü kalıntısı var. Belki yaban hayvanlarını huzursuz eden karanlık güçle ilgilidir? O tılsımı ataşeye bir daha sormalısın.)","Kabul","Ataşeye tılsımı sor.","Peki…"],"en":["The Ominous Talisman","(The small pillar with strange runes you picked up carries heavy traces of dark magic. Maybe it's related to the dark force disturbing the beasts of the wilds? You should ask the attaché about it again.)","Accept","Ask the attaché about the talisman.","Well…"],"lv":29},{"id":80153,"giver":"特派武官","to":"神谕先知","type":"talk","req":80152,"rw":{"gold":85,"items":[["30126",1]]},"lv0":19,"tr":["Tek Başına Araştırma","(Ataşenin yüzü tuhaflaştı; bir şey sakladığı belli. Bunu Kehanet Kâhini'ne anlatmalısın.)","Kabul","Kehanet Kâhini'ne anlat.","Peki."],"en":["Investigating Alone","(The attaché's expression turned odd; he's clearly hiding something. You should tell the Oracle Prophet.)","Accept","Tell the Oracle Prophet.","Very well."],"lv":29},{"id":80155,"giver":"特派武官","to":"神谕先知","type":"talk","req":80153,"rw":{"gold":144,"items":[["30126",1]]},"lv0":19,"tr":["Kendi İrade, Kendi Kader","Son zamanlarda epey itibar görüyorsun galiba. Duydum ki… o sözde tarikat hakkında daha fazla kanıt bulmuşsun? (İç çeker) Bazı şeyleri ne kadar düşünürsen o kadar anlamazsın; ne kadar peşine düşersen sonunda o kadar eli boş kalırsın… Ama herkesin kendi yolunu, kendi amacını seçme hakkı var. Bu mektubu Kâhin hazretlerine ver… Yıllarca bana yol gösterdiği için ona teşekkür borçluyum. Sana gelince, merak etme, yakında görüşeceğiz.","Kabul","Sessiz! Sessiz!","(Kâhin ataşenin mektubunu okudu) Hep çevremdekilerin kader çizgilerini izledim; bu, kıtanın kaderinden bile zor tahmin edilir. Belki ataşenin kaderi böyle trajik olmaya yazgılıydı… Gel çocuğum, kaderin seni bekliyor."],"en":["Own Will, Own Fate","You seem to be highly valued lately. I hear… you've found more evidence of that so-called cult? (Sighs) Some things, the more you think about them, the less you understand; the more you chase them, the less you end up with… But everyone has the right to choose their own path and their own goal. Give this letter to the Prophet… I owe her thanks for her guidance over the years. As for you, don't worry; we'll meet again soon.","Accept","Silence! Silence!","(The Prophet finished reading the attaché's letter) I've always watched the fates of those around me, and that is harder to foresee than the fate of the continent. Perhaps the attaché was destined for such a tragic fate… Come, child, your destiny awaits you."],"lv":29},{"id":80157,"giver":"神眼队长","to":"神谕先知","type":"talk","req":80201,"rw":{"gold":284,"items":[["30126",1]]},"lv0":19,"tr":["Büyücünün Ölümü","\"Bu mektubu okuduğunuzda sanırım beni çoktan öldürmüş olacaksın. Pişman değilim; kadim kahramanların ruhları beni çağırdı, onlar için savaşıp ölmekten mutluyum. Bir isteğim var, yiğit: cesedimi Kehanet Kâhini'ne teslim eder misin, beni tapınağın mezarlığına gömsün? Burası batmaya mahkûm; geleceği görebileceğim bir yerde yatmak istiyorum… Kadim ruhlar yolunu gözetsin, yiğit.\" Bu mektubu hainin üstünde buldum… Ne olursa olsun çok iyi dosttuk. Git, bu mektubu ve naaşını Kâhin'e teslim et. (İlahi Göz Yüzbaşı büyücünün naaşını ve vasiyetini sana verdi.)","Kabul","Naaşı ve mektubu Kehanet Kâhini'ne götür.","Teşekkür ederim."],"en":["The Mage's Death","\"When you read this letter, I suppose you'll have already killed me. I have no regrets; the souls of ancient heroes called to me, and I'm content to die fighting for them. I have one request, hero: will you take my body to the Oracle Prophet and let her bury me in the temple graveyard? This place is doomed to fall; I want to lie where I can see the future… May the ancient spirits watch over your path, hero.\" I found this letter on the traitor… Whatever happened, we were good friends. Go, take this letter and his remains to the Prophet. (The Godeye Captain hands you the mage's remains and last letter.)","Accept","Take the remains and the letter to the Oracle Prophet.","Thank you."],"lv":24},{"id":80201,"giver":"神眼队长","to":"神眼队长","type":"talk","req":80556,"rw":{"gold":103,"items":[["30126",1],["30033",10]]},"lv0":19,"tr":["Hainin Ölümü","Sen tarikat ordusuyla savaşırken kötü bir haber aldım: büyücü bize ihanet etti. Hainlere tahammülümüz yok… Sırlarımızın çoğunu biliyor; düşman safında kalmasına izin veremeyiz. Onu öldür, sonra bana rapor ver.","Kabul","Gideceğim.","Tamam."],"en":["Death of a Traitor","While you fought the cult army I got bad news: the mage has betrayed us. We can't tolerate traitors… He knows too many of our secrets; we can't let him stay in the enemy's camp. Kill him, then report to me.","Accept","I'll go.","Done."],"lv":24},{"id":80553,"giver":"夜精灵望气士","to":"神眼队长","type":"talk","rw":{"gold":102,"items":[["30033",5],["30030",5],["30126",1]]},"req":80141,"lv0":19,"tr":["Kampın Güvenliği","Buranın güvenliğinden İlahi Göz Yüzbaşı sorumlu. Keskin gözlü biridir ama en keskin göz bile karanlığın her köşesini göremez. Git, ona yardım et dostum; kâbuslarla çevrili bu yer dikkatle yönetilmeli.","Kabul","İlahi Göz Yüzbaşı ile konuş.","Yardım mı edeceksin? Güzel."],"en":["The Camp's Safety","The Godeye Captain is in charge of our safety here. He has sharp eyes, but even the sharpest eyes can't see every corner of the dark. Go and help him, my friend; this nightmare-ringed place must be run with care.","Accept","Talk to the Godeye Captain.","You'll help? Good."],"lv":24},{"id":80554,"giver":"神眼队长","to":"夜精灵望气士","type":"talk","req":80143,"rw":{"gold":50,"items":[["30126",1]]},"lv0":19,"tr":["Komplo","Son zamanlarda kampın yakınında şüpheli gölgeler görüldüğüne dair haberler aldım; bunda bir iş var. Git, Aura Gözcüsü ile konuş, bir şey biliyor mu bak.","Kabul","Anlaşıldı.","Öyle mi?"],"en":["A Conspiracy","I've received reports of suspicious figures near the camp lately; something is wrong. Go and talk to the Aura Watcher and see if he knows anything.","Accept","Understood.","Is that so?"],"lv":24},{"id":80556,"giver":"神眼队长","to":"神眼队长","type":"kill","target":"安魂歌手","count":10,"sc":"漫雾低地","req":80555,"rw":{"gold":80,"items":[["30126",1]]},"lv":30,"tr":["Kukla Ustası","Sisli Ova'da dolaşan şarkıcıları fark etmişsindir. Şimdi büyüleme sihrini kötüye kullandıklarına dair kanıtım var: onları yok et, hiç tereddüt etme.","Kabul","Kılıcını oynatıcının bedenine sapladığında kuklaları da acı çeker…","Artık Tarikat Üssü'ndeki düşmanlarla gönül rahatlığıyla uğraşabiliriz…"],"en":["The Puppeteer","I think you've noticed the singers active in the Misty Lowland. Now I have proof they're abusing charm magic: destroy them, without hesitation.","Accept","When your blade pierces the puppeteer, her puppets feel the pain too…","Now we can deal with the enemies in the Cult Base with peace of mind…"]},{"id":82018,"giver":"夜精灵望气士","to":"生命熔炉法师（夜精灵）","type":"talk","rw":{"gold":165,"items":[]},"lv0":19,"tr":["Hayat Ocağı","Güneşgören Şehri, Güneşgören Şehri! Onun refahı bizim topladığımız bu ruh enerjisine dayanıyor. Şimdi bu yarasa özünü Hayat Ocağı Büyücüsü'ne götür; ocakta işlenen öz bütün Gözcü Kampı'nı doldursun.","Kabul","Yarasa özünü Hayat Ocağı Büyücüsü'ne götür.","Getirdin mi? Güzel."],"en":["The Life Forge","Sunwatch City, Sunwatch City! Its prosperity rests on the spirit essence we gather. Now take this bat essence to the Life Forge Mage; let the forged essence fill the whole Watcher Camp.","Accept","Take the bat essence to the Life Forge Mage.","You brought it? Good."],"lv":24},{"id":82019,"giver":"生命熔炉法师（夜精灵）","to":"夜精灵望气士","type":"talk","req":82018,"rw":{"gold":197,"items":[["30126",1]]},"lv0":19,"tr":["Sırrı Koru","Yarasa özünü Hayat Ocağı'na kattım; ocak özümüzü Gözcü Kampı'ndaki her elfe aşılayacak. Ama bu Güneşgören Şehri'nin yasalarına aykırı; kibirli bir elf olarak bu riski göze alıyorum. Yine de Aura Gözcüsü'ne sırrı korumasını bir kez daha hatırlat.","Kabul","Aura Gözcüsü'ne sırrı hatırlat.","Elbette, ağzım sıkıdır."],"en":["Keep the Secret","I've infused the bat essence into the Life Forge; it will imbue every elf in the Watcher Camp. But this violates Sunwatch City's laws; as a proud elf, I'll take the risk. Still, remind the Aura Watcher once more to keep the secret.","Accept","Remind the Aura Watcher about the secret.","Of course, my lips are sealed."],"lv":24},{"id":82020,"giver":"夜羽","to":"夜羽","type":"collect","target":"蝙蝠","count":1,"sc":"怒焰路口","chance":1,"rw":{"gold":196,"items":[["30126",1]]},"lv":19,"tr":["Haraç","Bazı cüce kaçakçıların yarasa kan dişlerini fahiş fiyatlara sattığını görmüştüm. Belki Öfkealevi Kavşağı'ndaki yarasalarda vardır; git, öldür, bulabilirsen hemen bana getir, işime yarayacak.","Kabul","Kan dişi gerçekten değerli bir şey.","Pek sıradan görünüyor; gerçekten o kadar değerli mi?","Kan Dişi"],"en":["Tribute","I once saw gnome smugglers selling bat blood fangs at outrageous prices. Maybe the bats at Furyflame Crossing have them; go kill them, and if you get any, bring them straight to me; I have a use for them.","Accept","Blood fangs really are a fine thing.","It looks rather ordinary; is it really that valuable?","Blood Fang"]},{"id":82021,"giver":"夜羽","to":"医生工会志愿者","type":"talk","req":82020,"rw":{"gold":218,"items":[]},"lv0":19,"tr":["Dişin Etkisi","Şimdi kan dişini Gözcü Kampı'ndaki Hekimler Loncası Gönüllüsü'ne ver, o da lonca başkanına iletsin; böylece belki bu berbat Kâbus Ovası'ndan tayinim çıkar. Sakın gönüllüye bunun değerli bir kan dişi olduğunu söyleme; sadece ilaç de.","Kabul","Kan dişini Hekimler Loncası Gönüllüsü'ne ver.","İlaç mı? Teşekkürler, başkana iletirim."],"en":["The Fang's Effect","Now give the blood fang to the Healers' Guild Volunteer at the Watcher Camp so he passes it to the guild master; then maybe I'll get transferred out of this wretched Nightmare Plain. Don't tell the volunteer it's a valuable blood fang; just say it's medicine.","Accept","Give the blood fang to the Healers' Guild Volunteer.","Medicine? Thanks, I'll pass it on to the master."],"lv":19},{"id":82022,"giver":"达尔","to":"神眼队长","type":"talk","rw":{"gold":116,"items":[]},"lv0":19,"tr":["Trol Toplantısı","Yakınlarda gittikçe daha çok trol toplandığını fark ettim; bu beyinsizler ne çeviriyor? Bunda bir iş var; yoksa özümüzü mü yağmalamak istiyorlar! İlahi Göz Yüzbaşı'na bildir! Hemen!","Kabul","İlahi Göz Yüzbaşı'na bildir.","Troller mi? Anlaşıldı."],"en":["Troll Meeting","I've noticed more and more trolls gathering nearby; what are those brainless brutes up to? Something's off; maybe they want to plunder our essence! Report to the Godeye Captain! Right away!","Accept","Report to the Godeye Captain.","Trolls? Understood."],"lv":23},{"id":82023,"giver":"神眼队长","to":"神眼队长","type":"kill","target":"巨魔","count":10,"sc":"怒焰路口","req":82022,"rw":{"gold":91,"items":[["30126",1]]},"lv":19,"tr":["Trol Savaşı","Önce davranan kazanır! Ne konuşuyorlarsa konuşsunlar, hedefleri Gözcü Kampı. Şimdi onları temizleyecek yiğit ve soylu bir elfe ihtiyacımız var; bence en uygunu sensin.","Kabul","Git, soylu elf.","Güzel, planları beşikte ölsün."],"en":["Troll War","Strike first! Whatever they're discussing, they're coming for the Watcher Camp. We need a brave, noble elf to clear them out, and I think you're the best choice.","Accept","Go, noble elf.","Good, let their plan die in the cradle."]},{"id":82024,"giver":"【飞毛腿】多多","to":"【飞毛腿】多多","type":"collect","target":"巨魔","count":5,"sc":"怒焰路口","chance":0.6,"rw":{"gold":137,"items":[["30126",1]]},"lv":19,"tr":["Trol Boyası","Bir ulak olarak hep tehlikeli mektuplar taşırım; geçen gün az kalsın bir grup trol beni kaynatıp yiyecekti! O kırmızı yaratıklar ne korkunç! Kıpkırmızı! Bu renkten başka hayvanlar da korkar herhalde? Hm, aklıma iyi bir fikir geldi; git, derilerini getir, işime yarayacak.","Kabul","Dünyanın en hızlı koşanı benim!","İşte bu korkutucu kırmızı.","Trol Derisi"],"en":["Troll Dye","As a courier I always carry dangerous letters; the other day a band of trolls nearly boiled and ate me! Those red creatures are terrifying! Blood red! Other beasts must fear that color too, right? Hm, I've got a good idea; go get me their hides, I have a use for them.","Accept","I'm the fastest runner in the world!","That's the terrifying red.","Troll Hide"]},{"id":82025,"giver":"【飞毛腿】多多","to":"特派武官","type":"talk","req":82024,"rw":{"gold":82,"items":[]},"lv0":19,"tr":["Silahı Boya","Hançerimi ve kırmızı derileri al, Özel Ataşe'ye ver. Hançerimi kırmızıya boyasın; böylece yabanda silahımı çekince hayvanlar altlarına edecek!","Kabul","Hançeri ve derileri Özel Ataşe'ye götür.","Hançer boyamak mı? Peki."],"en":["Paint the Weapon","Take my dagger and the red hides to the Military Attaché. Have him paint my dagger red; then out in the wilds the beasts will wet themselves the moment I draw it!","Accept","Take the dagger and hides to the Military Attaché.","Paint a dagger? Fine."],"lv":19},{"id":82028,"giver":"特派武官","to":"【飞毛腿】多多","type":"talk","req":82025,"rw":{"gold":97,"items":[["30126",1]]},"lv0":19,"tr":["Raf Ömrü","Boyadım; Dodo malzeme bulmakta ustaymış. Ama bu derinin rengi pek uzun sürmeyecek gibi… Üstüne trol kanı dökülmezse kısa sürede solar. Dodo'ya söyle de boş yere ölmesin.","Kabul","Dodo'ya rengin solacağını söyle.","Ne?! Solacak mı?"],"en":["Shelf Life","It's painted; Dodo sure knows his materials. But the hide's color won't last long… unless troll blood is poured on it, it'll fade quickly. Tell Dodo, so he doesn't get himself killed.","Accept","Tell Dodo the color will fade.","What?! It'll fade?"],"lv":29},{"id":82029,"giver":"【飞毛腿】多多","to":"【飞毛腿】多多","type":"kill","target":"红斑蜘蛛","count":10,"sc":"怒焰路口","rw":{"gold":147,"items":[]},"lv":19,"tr":["Örümcek İzleri","Ben bir ulağım, en hızlı ulak; Labilia'nın en dikkatli, en tedbirli adımlı ulağı. Ama son günlerde bir yaratık sessizce üstümden geçti ve fark etmedim! Benden daha dikkatli adım atana tahammülüm yok! Öfkealevi Kavşağı'na git, şu Kızıl Benekli Örümceklerin hepsini öldür!","Kabul","Dünyanın en hızlı koşanı benim!","Harika!"],"en":["Spider Tracks","I'm a courier, the fastest courier, the most careful and cautious courier in Labilia. But lately some creature crept right over me and I didn't notice! No one may tread more carefully than me! Go to Furyflame Crossing and kill all those Red-Spotted Spiders!","Accept","I'm the fastest runner in the world!","Excellent!"]},{"id":82030,"giver":"医生工会志愿者","to":"医生工会志愿者","type":"collect","target":"红斑蜘蛛","count":5,"sc":"怒焰路口","chance":0.6,"rw":{"gold":138,"items":[]},"lv":19,"tr":["Kızıl Benekli İpek","Savaşçılar Loncası'nın yardımcı subayı yaralanmış! Bu büyük fırsat! Ona en kaliteli sargıyı yapıp göndereceğim! Esnek, sağlam, dayanıklı!… Örümcek ipeği, evet, Kızıl Benekli Örümceklerin ipeği; sadece 5 tanesiyle koca bir rulo sargı yapabilirim.","Kabul","Kızıl benekli ipekten sargı; bunu ancak ben düşünebilirdim.","Gerçekten çok sağlam.","Kızıl Benekli İpek"],"en":["Red-Spotted Silk","The Warrior Guild's adjutant is wounded! What an opportunity! I'll make him the finest bandages! Flexible, strong, durable!… Spider silk, yes, the silk of Red-Spotted Spiders; with just 5 I can make a big roll of bandages.","Accept","Red-spotted silk bandages; only I could think of that.","Truly very strong.","Red-Spotted Silk"]},{"id":82031,"giver":"达尔","to":"达尔","type":"kill","target":"影狼","count":10,"sc":"噩梦平原中部","rw":{"gold":85,"items":[["10047",1],["10065",1],["10906",1]]},"lv":23,"tr":["Gölge Taklitçisi","Gölge kurt çoğu zaman karanlıkta ve gölgelerde dolaşan bir yaratıktır; bir elfin gölgesine bile girip fırsat kollayabilir. Şimdi ilan ediyorum: bu türün nesli tükenebilir.","Kabul","Gölge kurt gerçekten çok tehlikeli bir yaratık.","Gözcü Kampı'nın güvenliğini sağladım."],"en":["Shadow Mimic","The shadow wolf is a creature that mostly moves in darkness and shadow; it can even slip into an elf's shadow and wait to strike. I hereby declare this species may go extinct.","Accept","Shadow wolves really are very dangerous creatures.","I've protected the Watcher Camp."]},{"id":82032,"giver":"夜羽","to":"夜羽","type":"kill","target":"☆吸血黑寡妇","count":10,"sc":"噩梦平原东","rw":{"gold":177,"items":[]},"lv":24,"tr":["Cüce Yolu","Kâbus Ovası Doğu'da korkunç örümcekler türedi; çok zehirliler ve yüzlerinden aylardır Gözcü Kampı'na hiç cüce kervanı gelmedi. Bu ☆Kan Emici Karadulları temizle, cüce yolumuzu aç.","Kabul","Cüce yolunu koru.","Bu ☆Kan Emici Karadulların canı cehenneme."],"en":["The Gnome Road","Terrible spiders have appeared in Nightmare Plain East; they're highly venomous, and because of them no gnome caravan has reached the Watcher Camp in months. Clear out these ☆Bloodsucking Black Widows and open our gnome road.","Accept","Protect the gnome road.","To hell with these ☆Bloodsucking Black Widows."]},{"id":82033,"giver":"达尔","to":"达尔","type":"kill","target":"☆致死仙子","count":10,"sc":"噩梦平原东","rw":{"gold":127,"items":[["30126",1]]},"lv":24,"tr":["Süper Dişler","Geçen gün korkunç bir canavar bana saldırdı! O kocaman dişlerini hâlâ unutamıyorum! Diş uçlarından kan damlıyordu, iğrenç kan kokusu burnumun dibindeydi… Ühü ühü… O, Kâbus Ovası Doğu'daki ☆Ölümcül Peri; git, öldür onları!","Kabul","……","Ha? Onların dişi yok mu?"],"en":["Super Teeth","The other day a horrible monster attacked me! I still can't forget its huge teeth! Blood dripped from their tips, the stench of blood right under my nose… boo hoo… It was the ☆Deadly Fairy of Nightmare Plain East; go and kill them!","Accept","……","Huh? They don't have teeth?"]},{"id":82034,"giver":"达尔","to":"达尔","type":"kill","target":"鸡蛇","count":10,"sc":"噩梦平原中部","req":82033,"rw":{"gold":100,"items":[["10132",1],["10061",1],["10905",1]]},"lv":23,"tr":["Kokatris Dişi","O zaman bana saldıran kesin Kâbus Ovası Orta'daki kokatristi! Hemen git, dişlerini sök! Yoksa bu kâbus peşimi hiç bırakmayacak.","Kabul","……","Ha? Kokatrislerin de mi dişi yok?"],"en":["Cockatrice Teeth","Then it must have been the cockatrices of Nightmare Plain Center that attacked me! Go and pull out all their teeth! Otherwise this nightmare will haunt me forever.","Accept","……","Huh? Cockatrices don't have teeth either?"]},{"id":82035,"giver":"达尔","to":"医生工会志愿者","type":"talk","req":82034,"rw":{"gold":78,"items":[["30126",1]]},"lv0":19,"tr":["Vazgeçmeyen Dal","Kesin dişleri var! Nasıl olmaz… Neden… (Dal durmadan söyleniyor, aklı pek yerinde görünmüyor; en iyisi hekime sormak.)","Kabul","Hekimler Loncası Gönüllüsü'ne sor.","Dal yine sana kelebeklerin dişini söktürmeye mi çalıştı?"],"en":["Dal Won't Let Go","They must have teeth! How could they not… Why… (Dal keeps babbling and doesn't seem in his right mind; better ask the healer.)","Accept","Ask the Healers' Guild Volunteer.","Did Dal send you to pull out butterflies' teeth again?"],"lv":23},{"id":82036,"giver":"医生工会志愿者","to":"医生工会志愿者","type":"talk","req":82035,"rw":{"gold":142,"items":[]},"lv0":19,"tr":["Dal'ın Tedavisi","Bu talihsiz adam geçenlerde bir korku yaşadı, aklı biraz karıştı… Lütfen alınma, seninle dalga geçmek istemedi. Ama sen kokatris öldürebiliyor musun?! Belki gerçekten Dal'a yardım edebilirsin. Ister misin? Tehlikeli olacak, bir düşün.","Kabul","Hekimle konuş.","Yardım edecek misin? Teşekkürler."],"en":["Dal's Treatment","This unlucky fellow got a fright recently and his mind is a bit muddled… Please don't mind him; he didn't mean to mock you. But you can kill cockatrices?! Maybe you really can help Dal. Will you? It'll be dangerous; think it over.","Accept","Talk to the healer.","You'll help? Thank you."],"lv":19},{"id":82037,"giver":"医生工会志愿者","to":"医生工会志愿者","type":"collect","target":"放养肉蜘蛛","count":10,"sc":"噩梦平原西","chance":0.5,"req":82036,"rw":{"gold":182,"items":[]},"lv":29,"tr":["Örümcek Zehri","Dal'ı iyice muayene ettim; yarası yok. Böyle olmasının sebebi bir sinir zehri olabilir. Buna göre Kâbus Ovası Batı'daki Besi Örümcekleri en şüpheli. Bana biraz örümcek zehri toplar mısın?","Kabul","……","Teşekkürler; bunlarla bir panzehir hazırlayabilirim.","Besi Örümceği Zehri"],"en":["Spider Venom","I examined Dal carefully and found no wounds; this may be the work of some nerve toxin. If so, the Ranch Spiders of Nightmare Plain West are the most suspicious. Could you collect some spider venom for me?","Accept","……","Thank you; with this I can develop an antidote.","Ranch Spider Venom"]},{"id":82038,"giver":"医生工会志愿者","to":"达尔","type":"talk","count":1,"req":82037,"rw":{"gold":69,"items":[["30126",1]]},"lv0":19,"tr":["Dal'ın Panzehiri","Panzehir hazır; Dal'a götür.","Kabul","Panzehiri Dal'a götür.","Bu güzel bal şarabı mı?","Dal'ın Panzehiri"],"en":["Dal's Antidote","The antidote is ready; take it to Dal.","Accept","Take the antidote to Dal.","Is this tasty honey wine?","Dal's Antidote"],"lv":19},{"id":82039,"giver":"达尔","to":"医生工会志愿者","type":"talk","req":82038,"rw":{"gold":80,"items":[["30126",1]]},"lv0":19,"tr":["Beklenmedik Durum","Dal iksiri bir dikişte içti. Sana bakıp ciddi bir yüzle \"Hepsinin dişini sökeceğim\" dedi. Aman Tanrım! Daha da kötüleşmiş gibi; hemen hekime söyle!","Kabul","Hekime haber ver.","Hiç düzelmedi mi?"],"en":["A Sudden Turn","Dal downed the potion in one gulp. He looked at you and said gravely, \"I'll pull out all their teeth.\" Good heavens! He seems even worse; tell the healer at once!","Accept","Tell the healer.","He didn't get any better?"],"lv":23},{"id":82040,"giver":"医生工会志愿者","to":"医生工会志愿者","type":"collect","target":"钻地蠕虫","count":10,"sc":"噩梦平原南","chance":0.5,"req":82039,"rw":{"gold":245,"items":[]},"lv":27,"tr":["Daha Güçlü Zehir","Yoksa yanlış yönde mi düşündüm? Yoksa örümcek zehri yeterince güçlü değil miydi? Kâbus Ovası Güney'de bakışıyla insan öldüren Toprak Delen Solucanlar varmış. İçlerinde çok güçlü bir sinir zehri olmalı, yoksa böyle bir söylenti neden çıksın? Bana biraz solucan zehri toplar mısın? Zehri zehirle yenersek belki Dal düzelir.","Kabul","……","Teşekkürler. Hemen güçlü bir iksir hazırlayacağım.","Solucan Zehri"],"en":["A Stronger Poison","Was I thinking in the wrong direction? Or was the spider venom not strong enough? I hear Nightmare Plain South has Burrowing Worms whose gaze can kill. They must carry a deadly nerve toxin, or why would such rumors exist? Could you collect some worm venom for me? Fighting poison with poison might cure Dal.","Accept","……","Thank you. I'll prepare a powerful potion right away.","Burrowing Worm Venom"]},{"id":82041,"giver":"医生工会志愿者","to":"达尔","type":"talk","count":1,"req":82040,"rw":{"gold":64,"items":[["30126",1]]},"lv0":19,"tr":["Daha Güçlü Panzehir","Lütfen bu iksiri Dal'a götür. Dikkatli ol, bu çok zehirli. Ağır hastalığa ağır ilaç; başka çarem yok.","Kabul","İksiri Dal'a götür.","Bu da ne güzel bir içecek?","Zehirli İksir"],"en":["A Stronger Antidote","Please take this potion to Dal. Be careful, it's extremely toxic. Severe illness calls for strong medicine; I have no other choice.","Accept","Take the potion to Dal.","And what tasty drink is this?","Toxic Potion"],"lv":19},{"id":82042,"giver":"达尔","to":"医生工会志愿者","type":"talk","req":82041,"rw":{"gold":96,"items":[]},"lv0":19,"tr":["Kara Akbaba mı?","Dal'ın gözleri dondu, taş kesilmiş gibi. Ağzından zorlukla iki kelime döküldü: \"Kara akbaba…\" Hemen hekime söyle.","Kabul","Hekime haber ver.","Ne dedin?! Dal kara akbaba mı görmüş?"],"en":["Black Vulture?","Dal's eyes glazed over, as if turned to stone. With great effort he muttered: \"Black vulture…\" Go tell the healer.","Accept","Tell the healer.","What did you say?! Dal saw a black vulture?"],"lv":23},{"id":82043,"giver":"医生工会志愿者","to":"医生工会志愿者","type":"kill","target":"黑秃鹫","count":5,"sc":"噩梦平原南","req":82042,"rw":{"gold":186,"items":[["11240",1]]},"lv":27,"tr":["Kara Akbaba!","Neler olduğunu aşağı yukarı anladım. Kara akbabalar çok tehlikelidir; kanat çırpışlarıyla birkaç metre ötedeki bir elfi zehirleyebildikleri söylenir! Dal'ın hâlâ yaşaması mucize. Daha fazla kişi zarar görmesin diye o kara akbabaları öldürmelisin! Her yeni hastada saçlarım biraz daha ağarıyor…","Kabul","……","Çok teşekkür ederim!"],"en":["Black Vulture!","I think I understand now. Black vultures are extremely dangerous; they say one flap of their wings can poison an elf several meters away! It's a miracle Dal is still alive. To keep more people from harm, you must kill those black vultures! Every new patient turns more of my hair gray…","Accept","……","Thank you so much!"]},{"id":82044,"giver":"守望者","to":"守望者","type":"kill","target":"☆凶残的食腐豺","count":10,"sc":"噩梦平原中部","rw":{"gold":139,"items":[]},"lv":23,"tr":["Vahşi Çakallar","Çakallar son zamanlarda Gözcü Kampı halkını çılgınca öldürüyor; bu kadar azmalarına izin veremeyiz. Bu aşağılık yaratıklara varlık sebeplerinin Güneşgören Şehri'ne öz sağlamak olduğunu göster.","Kabul","Haydi git!","Zavallı halkımız."],"en":["Savage Jackals","Jackals have been killing the people of the Watcher Camp like mad lately; we can't let them run wild. Show these lowly creatures that they exist only to supply Sunwatch City with essence.","Accept","Go on!","Our poor people."]},{"id":82045,"giver":"守望者","to":"医生工会志愿者","type":"talk","req":82044,"rw":{"gold":80,"items":[["30126",1]]},"lv0":19,"tr":["Taziye","Hekimler Loncası Gönüllüsü'nün karısı öldürüldü; Gözcüler adına ona başsağlığı dile.","Kabul","Hekimler Loncası Gönüllüsü'ne başsağlığı dile.","Teşekkür ederim…"],"en":["Condolences","The Healers' Guild Volunteer's wife was killed; offer him condolences on behalf of the Watchers.","Accept","Offer condolences to the Healers' Guild Volunteer.","Thank you…"],"lv":23},{"id":82046,"giver":"医生工会志愿者","to":"神眼队长","type":"talk","req":82045,"rw":{"gold":73,"items":[["10054",1],["10070",1],["10908",1]]},"lv0":19,"tr":["Yüzbaşıya Bildir","Ben kibirli bir elfim; karımın ölümü umurumda değil. Lütfen İlahi Göz Yüzbaşı'na ne kadar kibirli, ne kadar cesur olduğumu bildir…","Kabul","İlahi Göz Yüzbaşı'na bildir.","Anlıyorum…"],"en":["Report to the Captain","I'm a proud elf; I don't care about my wife's death. Please tell the Godeye Captain how proud and how brave I am…","Accept","Report to the Godeye Captain.","I see…"],"lv":19},{"id":82047,"giver":"夜精灵望气士","to":"夜精灵望气士","type":"kill","target":"☆致死仙子","count":10,"sc":"噩梦平原东","rw":{"gold":108,"items":[]},"lv":24,"tr":["Ölümcül Darbe","\"☆Ölümcül Peri\" denen küçük arılar var; ne kadar küstahlar! ☆Ölümcül Peri mi? O zaman şimdi git, dileklerini gerçekleştir; bu perilere ölümcül bir darbe vur!","Kabul","Ne gülünç.","Öldüler mi? Harika!"],"en":["Deadly Strike","There are little bees called \"☆Deadly Fairies\"; how arrogant they are! ☆Deadly Fairy, eh? Then go now and grant their wish; deal these fairies a deadly blow!","Accept","How ridiculous.","Are they dead? Wonderful!"]},{"id":82048,"giver":"夜精灵望气士","to":"神眼队长","type":"talk","req":82047,"rw":{"gold":128,"items":[["10657",1]]},"lv0":19,"tr":["Moral Yükseldi","Ha ha! Onları öldürmek içimi rahatlattı! Ölürken attıkları çığlıkları hatırlıyor musun? Ne hoş; herkes duymalıydı, Gözcü Kampı'nın morali kesin yükselirdi! Eminim İlahi Göz Yüzbaşı da benimle aynı fikirde!","Kabul","İlahi Göz Yüzbaşı ile konuş.","Hmm… aynı fikirde miyim, bilemem."],"en":["Morale Boost","Ha ha! Killing them felt so good! Remember their screams as they died? So sweet; everyone should hear them, it would surely lift the Watcher Camp's morale! I'm sure the Godeye Captain thinks the same!","Accept","Talk to the Godeye Captain.","Hmm… whether I agree, I can't say."],"lv":24},{"id":82049,"giver":"夜羽","to":"夜羽","type":"kill","target":"变异黑寡妇","count":10,"sc":"噩梦平原东","rw":{"gold":114,"items":[]},"lv":24,"tr":["İğrenç Örümcekler","İğrenç örümcekler geri döndü. Karadul mu? Mutant mı? Bu iğrenç eklembacaklılar Güneşgören Şehri'ni beslemez; onların özünü de istemem. Çöp temizleme zamanı geldi.","Kabul","Çöpü temizle!","Ne kadar varsa yok et!"],"en":["Disgusting Spiders","The disgusting spiders are back. Black widows? Mutants? These vile arthropods won't nourish Sunwatch City, and I don't want their essence either. Time to take out the trash.","Accept","Take out the trash!","Wipe out as many as there are!"]},{"id":82050,"giver":"医生工会志愿者","to":"炼金术工会代表","type":"talk","rw":{"gold":134,"items":[["30126",1]]},"lv0":19,"tr":["Simyacı Zehri","Güneşgören Şehri'nin Simya Loncası Temsilcisi en yeni zehrine panzehir hazırlamamı istiyor ama şu an başımı kaşıyacak vaktim yok. Git, ona biraz beklemesini söyle.","Kabul","Simya Loncası Temsilcisi ile konuş.","Beklemem mi gerekiyor? Peki…"],"en":["Alchemist's Poison","Sunwatch City's Alchemy Guild Representative keeps asking me for an antidote to his newest poison, but I'm swamped right now. Go and tell him to wait a while.","Accept","Talk to the Alchemy Guild Representative.","I have to wait? Fine…"],"lv":19},{"id":82057,"giver":"特派武官","to":"特派武官","type":"kill","target":"黑斑野猪","count":10,"sc":"噩梦平原东","rw":{"gold":111,"items":[]},"lv":24,"tr":["Av Talimi","Elf! Av talimi zamanı; her elf usta bir avcıdır. Kâbus Ovası Doğu'da benekli yaban domuzları var; git, birkaçını avla ve boş bir çuval olmadığını kanıtla.","Kabul","Avlan, genç elf.","Güzel, tam görmek istediğim yetenek."],"en":["Hunting Practice","Elf! Time for hunting practice; every elf is a skilled hunter. There are spotted boars in Nightmare Plain East; go hunt some and prove you're not a good-for-nothing.","Accept","Hunt, young elf.","Good, that's exactly the skill I wanted to see."]},{"id":82058,"giver":"【飞毛腿】多多","to":"【飞毛腿】多多","type":"collect","target":"软泥史莱姆","count":10,"sc":"烂泥荒野","chance":0.5,"rw":{"gold":147,"items":[]},"lv":25,"tr":["Balçık Kılığı","Balçık gibi görünmek istiyorum; böylece mektup taşırken hayvanlar beni görünce midesi bulanır! Her tehlikeye soğukkanlılıkla göğüs gerebilirim! Çamurlu Yaban'daki Balçık Slime'lardan bana biraz pis kokulu balçık getir.","Kabul","Dünyanın en hızlı koşanı benim!","Harika, koklayınca benim bile midem bulandı.","Pis Kokulu Balçık"],"en":["Ooze Disguise","I want to look like ooze, so when I deliver letters the beasts will be disgusted at the sight of me! Then I can face any danger calmly! Get me some stinking ooze from the Ooze Slimes in the Mud Wilds.","Accept","I'm the fastest runner in the world!","Wonderful, the smell makes even me want to throw up.","Stinking Ooze"]},{"id":82059,"giver":"神眼队长","to":"神眼队长","type":"kill","target":"骷髅","count":10,"sc":"烂泥荒野","rw":{"gold":108,"items":[["10057",1],["10073",1],["10909",1]]},"lv":25,"tr":["Yaban Avcısı","Genç elf, yaban avcısı olmak ister misin? Çamurlu Yaban'daki iskeletler senin için iyi bir sınav; göreyim bakalım, soylu bir yaban avcısı olabilir misin?","Kabul","Elfler kibirli bir ırktır, bütün canlılardan üstündür!","Hm, demek bir şeyler biliyormuşsun."],"en":["Wilds Hunter","Young elf, do you want to become a wilds hunter? The skeletons of the Mud Wilds are a good test for you; let me see whether you could become a noble wilds hunter.","Accept","Elves are a proud race, stronger than all creatures!","Hm, so you do know a thing or two."]},{"id":82060,"giver":"医生工会志愿者","to":"医生工会志愿者","type":"collect","target":"骷髅","count":5,"sc":"烂泥荒野","chance":0.6,"rw":{"gold":233,"items":[["10659",1]]},"lv":25,"tr":["Kemik Tozu","Askerlerimizden biri Balçık Slime'larla savaşırken kemiğini kırdı… Nasıl kırdı peki?! Neyse, bunu boş verelim, kırılmış işte. Çamurlu Yaban'da iskeletler var, kemikleri çok sert görünüyor… Git, onları öldür ve uyluk kemiği getir; toz edip elf savaşçılarımızı tedavi edeceğim.","Kabul","Vakit kaybetmeden git.","Uyluk kemiği, harika.","Uyluk Kemiği"],"en":["Bone Dust","One of our soldiers broke a bone fighting the Ooze Slimes… How did he break it?! Never mind, he did. There are skeletons in the Mud Wilds, and their bones look very hard… Go kill them and bring back thigh bones; I'll grind them into powder to treat our elf warriors.","Accept","Go without delay.","Thigh bones, wonderful.","Thigh Bone"]},{"id":82063,"giver":"夜羽","to":"夜羽","type":"kill","target":"黑秃鹫","count":10,"sc":"噩梦平原南","rw":{"gold":154,"items":[]},"lv":27,"tr":["Gece Katili","Kara akbabalar Kâbus Ovası'nın gecelerinin hâkimidir; geceleri gölgelere gizlenirler, gölge kurtlar bile onlara av olur. Bu gece katilleri avcılıkta yükselmen için büyük fırsat. Gözcü Kampı'nın elflerine gücünü göster!","Kabul","Gitmeye korkuyor musun?","Gecenin hâkimi artık sensin!"],"en":["Night Killers","Black vultures rule the nights of the Nightmare Plain; they hide in the shadows at night, and even shadow wolves become their prey. These night killers are your chance to rise as a hunter. Show the elves of the Watcher Camp what you can do!","Accept","Too scared to go?","You are the ruler of the night!"]},{"id":82064,"giver":"达尔","to":"达尔","type":"collect","target":"侏儒怪人","count":1,"sc":"噩梦平原南","chance":1,"rw":{"gold":108,"items":[]},"lv":27,"tr":["Ucube Maketi","Kâhin Tapınağı'ndaki yeğenim doğum günü hediyesi olarak yeni bir maket istiyor! Cücelerin kendilerine benzeyen bebek maketleri yaptığı söylenir; onlardan birini getir de sevgili yeğenime vereyim.","Kabul","Mutlaka büyük bir tane seç!","Hm, bu maket harika, gerçeği gibi.","Ucube Maketi"],"en":["Freak Model","My nephew far away at the Prophet's Temple wants a new model for his birthday! They say gnomes often make doll models that look just like them; bring me one so I can give it to my dear nephew.","Accept","Be sure to pick a big one!","Hm, this model is great, just like the real thing.","Freak Model"]},{"id":82065,"giver":"达尔","to":"特派武官","type":"talk","count":1,"rw":{"gold":111,"items":[["30126",1]]},"req":82064,"lv0":19,"tr":["Maketi Onar","Bu ucube maketi pek kusursuz değil; o korkunç suratı yeğenimi korkutur. Özel Ataşe'ye götür; eskiden heykel yaptığını duydum, biraz düzeltsin de yeğenime öyle gönderelim.","Kabul","Çabuk Özel Ataşe'yi bul! Yeğenim maketi bekliyor.","Çocuğa güzel bir hediye olacak.","Ucube Maketi"],"en":["Fix the Model","This freak model isn't quite right; that scary face would frighten my nephew. Take it to the Military Attaché; I hear he used to sculpt, so he can fix it before we send it to my nephew.","Accept","Hurry to the Military Attaché! My nephew is waiting.","It'll make a lovely gift for the child.","Freak Model"],"lv":23},{"id":82066,"giver":"夜精灵望气士","to":"夜精灵望气士","type":"kill","target":"钻地蠕虫","count":10,"sc":"噩梦平原南","rw":{"gold":123,"items":[["30126",1]]},"lv":27,"tr":["Kazıcı İşçiler","Kâbus Ovası'nın durumu gittikçe kötüleşiyor: pis koku, kirli toprak! Şimdi de bazı \"kazıcı işçiler\" türedi; zaten delik deşik olan toprağı daha da deliyorlar. Bu beni ilgilendirmezdi ama yüzlerinden ovadaki canlı türleri azalıyor, öz yoğunluğu hızla düşüyor! Git, bu \"kazıcı işçileri\" yok et, bize \"iyi\" bir ortamı geri ver.","Kabul","Bütün öz Güneşgören Şehri'nindir.","Sonunda eski \"iyi\" ortamımıza kavuştuk."],"en":["Burrowing Workers","The Nightmare Plain keeps getting worse: stench, filthy ground! And now some \"burrowing workers\" have appeared, drilling into the already riddled earth. That wouldn't concern me, but because of them the plain's species are dwindling and the essence density is plummeting! Go wipe out these \"burrowing workers\" and give us back a \"good\" environment.","Accept","All essence belongs to Sunwatch City.","At last we're back to our old \"good\" environment."]},{"id":82067,"giver":"【飞毛腿】多多","to":"【飞毛腿】多多","type":"collect","target":"黑秃鹫","count":10,"sc":"噩梦平原南","chance":0.5,"rw":{"gold":144,"items":[["30126",1]]},"lv":27,"tr":["Kalem Görmemiştir","Keskin gözlü bir ulak olarak Dal'ın o güçlü bedeni bana koruma olur diye düşündüm. Hmm… Ona tanışma hediyesi olarak ne vereyim? Buldum! Bu savaşçıya bir kalem vereyim! Eminim bu adam hayatında kalem kullanmamıştır! Git, biraz kara tüy topla!","Kabul","Yakında Labilia'nın korumalı tek ulağı olacağım!","Bu kara tüyler kalem yapmak için harika malzeme.","Kara Tüy"],"en":["Never Used a Pen","As a sharp-eyed courier, I figured Dal's strong body would make a fine bodyguard for me. Hmm… what gift should I give him? Got it! A pen for this warrior! I bet this guy has never used a pen! Go collect some black feathers!","Accept","Soon I'll be the only courier in Labilia with a bodyguard!","These black feathers are great material for pens.","Black Feather"]},{"id":82068,"giver":"【飞毛腿】多多","to":"达尔","type":"talk","count":1,"req":82067,"rw":{"gold":153,"items":[["30126",1]]},"lv0":19,"tr":["Parlak Tüy Kalem","Bu kara tüylere biraz kemik tozu sürsem daha parlak görünür! İşte, kendi yaptığım parlak tüy kalem hazır; şimdi kalem görmemiş Dal'a götür! Kesin duygulanıp hemen korumam olur.","Kabul","Labilia'nın korumalı tek ulağı benim!","Kim demiş kalem kullanmadım diye! Tamam, kalemi aldım…","Parlak Tüy Kalem"],"en":["Shiny Quill","If I rub some bone powder on these black feathers they'll look brighter! There, my homemade shiny quill is done; now take it to Dal, who's never used a pen! He'll be so moved he'll become my bodyguard at once.","Accept","I'm the only courier in Labilia with a bodyguard!","Who says I've never used a pen! Fine, I'll take it…","Shiny Quill"],"lv":19},{"id":82069,"giver":"夜羽","to":"夜羽","type":"collect","target":"☆☆羽翼蝙蝠","count":1,"sc":"噩梦平原南","chance":1,"rw":{"gold":236,"items":[]},"lv":27,"tr":["Efsanevi Kanatlar","Biliyor musun? İlahi Göz Yüzbaşı bana Güneşgören Şehri'nin lonca başkanlarında bile olmayan bir yeteneği olduğunu söyledi! Uçabilen tek elfmiş! Ama uçmak için efsanevi yarasa kanatları gerekiyormuş; işte fırsat! Kâbus Ovası Güney'de böyle yarasalar var! Uçan bir elf görmek ister misin? Git, efsanevi kanatları getir!","Kabul","Gerçekten uçabiliyor mu?","İşte böyle ince ve saydam bir şey.","Yarasa Kanadı"],"en":["Legendary Wings","Did you know? The Godeye Captain told me he has a talent even Sunwatch City's guild masters lack! He's the only elf who can fly! But he needs a pair of legendary bat wings to take off, and now's our chance! There are such bats in Nightmare Plain South! Want to see a flying elf? Go get the legendary wings!","Accept","Can he really fly?","Just like this, thin and transparent.","Bat Wing"]},{"id":82070,"giver":"夜羽","to":"神眼队长","type":"talk","count":1,"req":82069,"rw":{"gold":62,"items":[["30126",1]]},"lv0":19,"tr":["Uçan Elf","Uçan bir elf görmek ister misin? Kanatları İlahi Göz Yüzbaşı'na götür, herkese bir gösteri yapsın!","Kabul","Yakında uçan bir elf göreceğiz, ne heyecanlı.","Ben uçabilirim mi dedim? Dedim mi? Bu berbat yarasa kanadını nereden aldıysan oraya geri götür!","Yarasa Kanadı"],"en":["The Flying Elf","Want to see a flying elf? Take the wings to the Godeye Captain and have him give everyone a show!","Accept","Soon we'll see a flying elf; how exciting.","Did I say I can fly? Did I? Take this rotten bat wing back wherever you got it!","Bat Wing"],"lv":19},{"id":82071,"giver":"达尔","to":"达尔","type":"kill","target":"☆老影狼","count":10,"sc":"噩梦平原西","rw":{"gold":169,"items":[["30126",1]]},"lv":29,"tr":["Usta Gölge Taklitçisi","Gölge taklidi yapan kurtları hallettik! Şimdi de Kâbus Ovası Batı'da gündüz bile elflerin gölgesine girebilen bir kurt türü çıktı! Git, onları da gölge kurtların akıbetine uğrat!","Kabul","Canları cehenneme!","Gerçek gece avcısı sensin."],"en":["Master Shadow Mimic","We've dealt with the shadow-mimicking wolves! Now in Nightmare Plain West there's a kind of wolf that can slip into an elf's shadow even in daylight! Go give them the same fate as the shadow wolves!","Accept","To hell with them!","You are the true night hunter."]},{"id":82072,"giver":"医生工会志愿者","to":"医生工会志愿者","type":"kill","target":"生病的影狼","count":10,"sc":"噩梦平原西","rw":{"gold":126,"items":[]},"lv":29,"tr":["Salgın","Kâbus Ovası'nda salgın yayılıyor, hasta elflerin sayısı artıyor. Hayvanların özü de kirlendi! Böyle giderse burası yakında Ceset Bekçileri Kampı olacak! Git, hastalığın kaynağını öldür: Kâbus Ovası Batı'daki hasta gölge kurtları!","Kabul","Biz Gözcü Kampı'yız!","Bu tedavimizin sadece ilk adımı."],"en":["Epidemic","An epidemic is spreading across the Nightmare Plain, and more and more elves are falling ill. The beasts' essence is tainted too! At this rate this place will soon be the Corpse Keepers' Camp! Go kill the source of the disease: the sick shadow wolves of Nightmare Plain West!","Accept","We are the Watcher Camp!","This is only the first step of our treatment."]},{"id":82073,"giver":"医生工会志愿者","to":"夜羽","type":"talk","req":82072,"rw":{"gold":114,"items":[]},"lv0":19,"tr":["Bulaşmayı Önle","Gecekanat, Gözcü Kampı'nın en iyi avcısıdır; defalarca ölümün kıyısından döndü. Bulaşmayı nasıl önleyeceğimizi ona sor; deneyimli bir avcı bunu herkesten iyi bilir.","Kabul","Gecekanat ile konuş.","Hm, bulaşmayı önlemek istiyorsak aşı yapmalıyız."],"en":["Prevent Infection","Nightwing is the Watcher Camp's best hunter; he's escaped death many times. Ask him how to prevent further infection; an experienced hunter knows this better than anyone.","Accept","Talk to Nightwing.","Hm, if we want to prevent infection, we must make a vaccine."],"lv":19},{"id":82074,"giver":"夜羽","to":"夜羽","type":"collect","target":"生病的影狼","count":5,"sc":"噩梦平原西","chance":0.6,"req":82073,"rw":{"gold":67,"items":[]},"lv":29,"tr":["Hastalıklı Dişler","Bu zehir kesin o kurtların dişlerinden geliyor; git, hastalıklı dişlerinden topla. Aşı yapmak için gereken malzeme bu!","Kabul","Bu dişlerin hakkından gelmelisin.","Malzeme olunca her şey kolay.","Hastalıklı Diş"],"en":["Infected Teeth","This toxin must come from those wolves' teeth; go collect some of their infected teeth. That's what we need to make a vaccine!","Accept","You must deal with these teeth.","With materials in hand, everything's easier.","Infected Tooth"]},{"id":82075,"giver":"夜羽","to":"医生工会志愿者","type":"talk","count":1,"req":82074,"rw":{"gold":103,"items":[]},"lv0":19,"tr":["Aşı Yap","Bu hastalıklı dişleri dikkatle Hekimler Loncası Gönüllüsü'ne götür; aşı yapmak onun işi olmalı! Gözcü Kampı için, haydi git.","Kabul","Vakit kaybetme, Gözcü Kampı için.","Gerisi bende!","Hastalıklı Diş"],"en":["Make the Vaccine","Carefully take these infected teeth to the Healers' Guild Volunteer; making vaccines should be his specialty! For the Watcher Camp, go now.","Accept","Don't delay, for the Watcher Camp.","Leave the rest to me!","Infected Tooth"],"lv":19},{"id":82076,"giver":"医生工会志愿者","to":"神眼队长","type":"talk","req":82075,"rw":{"gold":133,"items":[["11243",1]]},"lv0":19,"tr":["Gönüllünün Katkısı","Aşının tamamlanması için elf kanı da gerekiyor; durum daha kötüye gidemez, aşıyı kendi kanımla tamamlayacağım! Yakında bütün Gözcü Kampı'na yetecek kadar aşı yapacağım! Git, İlahi Göz Yüzbaşı'na sorunun yakında çözüleceğini bildir!","Kabul","Aşıyı yapmaya başlıyorum, sen yüzbaşıya rapor ver.","Hekimler Loncası Gönüllüsü gerçekten aferin."],"en":["The Volunteer's Sacrifice","The vaccine also needs elf blood; things can't get any worse, so I'll complete it with my own blood! Soon I'll have enough for the whole Watcher Camp! Go and tell the Godeye Captain the problem will soon be solved!","Accept","I'm starting on the vaccine; you report to the captain.","The Healers' Guild Volunteer has done splendidly."],"lv":19},{"id":82077,"giver":"夜精灵望气士","to":"夜精灵望气士","type":"kill","target":"☆邪教追随者","count":10,"sc":"邪教基地","rw":{"gold":151,"items":[]},"lv":31,"tr":["Tarikatçıların Komplosu","Gölge kurtların hastalığı tesadüf değil; Tarikat Üssü'nde son zamanlarda gizli işler dönüyor. Eminim burayı Ceset Bekçileri Kampı'na çevirip özümüzü çalmak istiyorlar! Şu alçak ☆tarikatçılar! Tahammül edilemez!","Kabul","Komplolarının başarmasına asla izin vermeyeceğim.","Bu piyonlar artık gücümüzü anladı!"],"en":["The Followers' Plot","The shadow wolves' sickness is no coincidence; something secret has been going on at the Cult Base lately. I'm sure they want to turn this place into a Corpse Keepers' Camp and steal our essence! Those vile ☆cultists! Intolerable!","Accept","I'll never let their plot succeed.","Now these underlings know our strength!"]},{"id":82078,"giver":"特派武官","to":"特派武官","type":"collect","target":"☆邪教追随者","count":10,"sc":"邪教基地","chance":0.5,"rw":{"gold":217,"items":[]},"lv":31,"tr":["Hayale Kestirme","Güneşgören Şehri Savaşçılar Loncası'na yeni asker önerme zamanı geldi! Bu hayatımın hayali! İlahi Göz Yüzbaşı'nın silahı biraz paslanmış galiba; silahına bakarken gözlerindeki tereddüdü hep yakalıyorum! Bu büyük fırsat! Tarikat Üssü'ne git, askerlerin kullandığı baltalardan getir, yüzbaşıya hediye edelim; keyfi yerine gelince beni Savaşçılar Loncası'na önerir!","Kabul","Birkaç tane fazla getirmeyi unutma!","İşte bu keskin baltalar; kesin onunkinden çok daha iyi.","Tarikat Baltası"],"en":["Shortcut to a Dream","It's time to recommend new recruits to Sunwatch City's Warrior Guild! It's my life's dream! The Godeye Captain's weapon seems a bit rusty; I always catch the hesitation in his eyes when he looks at it! What a chance! Go to the Cult Base and bring back the axes their soldiers use, as a gift for the captain; once he's happy, he'll recommend me to the Warrior Guild!","Accept","Remember to bring extra!","These sharp axes are surely much better than his.","Cult Axe"]},{"id":82079,"giver":"特派武官","to":"神眼队长","type":"talk","count":1,"req":82078,"rw":{"gold":63,"items":[["30126",1]]},"lv0":19,"tr":["Ataşenin Katkısı","Bu baltaları hemen İlahi Göz Yüzbaşı'na götür! Hiç vakit kaybetme; geç kalırsak baltalar da paslanır!","Kabul","Benim gönderdiğimi söylemeyi unutma!","Artık balta değil kılıç kullanıyorum; bu hurdalar ne işime yarar?!","Sandık Dolusu Balta"],"en":["The Attaché's Gift","Take these axes to the Godeye Captain right away! Don't waste a moment; if we're late, the axes will rust too!","Accept","Remember to say they're from me!","I use a sword now, not an axe; what good is this junk?!","Crate of Axes"],"lv":29},{"id":82081,"giver":"特派武官","to":"特派武官","type":"collect","target":"☆野蛮巨魔","count":10,"sc":"噩梦平原西","chance":0.5,"rw":{"gold":181,"items":[["30126",1]]},"lv":29,"tr":["Barbar Topuzu","İlahi Göz Yüzbaşı kılıç kullanıyormuş, şaşırdım! O zaman şimdi kesin çekiç kullanıyordur! Kâbus Ovası Batı'daki ☆Barbar Troller de topuz kullanır! Cesetlerinden topuzları al! Böylece Güneşgören Şehri Savaşçılar Loncası'na girebilirim!","Kabul","Birkaç tane fazla getirmeyi unutma!","Ne ağır topuzlar; kesin onun külüstür kılıcından iyidir.","Barbar Topuzu"],"en":["Savage Club","So the Godeye Captain uses a sword; I'm surprised! Then I bet he uses a hammer now! The ☆Savage Trolls of Nightmare Plain West use clubs! Take the clubs from their corpses! Then I can join Sunwatch City's Warrior Guild!","Accept","Remember to bring extra!","What heavy clubs; surely better than his rusty sword.","Savage Club"]},{"id":82082,"giver":"特派武官","to":"神眼队长","type":"talk","count":1,"req":82081,"rw":{"gold":98,"items":[]},"lv0":19,"tr":["Kesin Topuzdur","Eminim İlahi Göz Yüzbaşı'nın silahı artık topuzdur; topuzlarımızı ona götür! Eminim çok sevecek!","Kabul","Benim gönderdiğimi söylemeyi unutma!","Bu ne saçmalık? Yine mi beni kandırmaya çalışıyorsun?","Sandık Dolusu Topuz"],"en":["Surely a Club","I'm sure the Godeye Captain's weapon is a club now; take him our clubs! I'm sure he'll love them!","Accept","Remember to say they're from me!","What is this junk? Trying to fool me again?","Crate of Clubs"],"lv":29},{"id":82083,"giver":"夜精灵望气士","to":"夜精灵望气士","type":"kill","target":"梦游傀儡","count":10,"sc":"漫雾低地","rw":{"gold":148,"items":[["30126",1]]},"lv":30,"tr":["Kontrolden Kurtar","Sisli Ova'da bazı uyurgezer kuklalar türedi; bir şey onları yönetiyor gibi. Oradaki canlıları katledip öz topladığımız türleri azalttılar. Silahını al ve onları uyandır!","Kabul","Haydi git, neden tereddüt ediyorsun?","Bu işte bir tuhaflık var."],"en":["Break the Control","Some sleepwalking puppets have appeared in the Misty Lowland, as if something controls them. They've slaughtered the creatures there and reduced the species we gather essence from. Take your weapon and wake them up!","Accept","Go, why do you hesitate?","There's something odd about this."]},{"id":82084,"giver":"夜精灵望气士","to":"神眼队长","type":"talk","req":82083,"rw":{"gold":79,"items":[]},"lv0":19,"tr":["Sarı Alarm","Bu işte bir bit yeniği var; bu kuklaları yöneten biri olmalı! Git, İlahi Göz Yüzbaşı'na sor, sonra ne yapacağız; yüzbaşının kararları hep en akıllıcasıdır.","Kabul","İlahi Göz Yüzbaşı buranın en bilge elfidir.","Basit görünen bu iş o kadar basit değil; sarı alarm vermek için yeterli sebep var."],"en":["Yellow Alert","Something's fishy here; someone must be controlling these puppets! Go ask the Godeye Captain what we do next; the captain's decisions are always the wisest.","Accept","The Godeye Captain is the wisest elf here.","This seemingly simple matter isn't simple at all; it's worth a yellow alert."],"lv":24},{"id":82085,"giver":"神眼队长","to":"夜精灵望气士","type":"talk","req":82084,"rw":{"gold":126,"items":[["30126",1]]},"lv0":19,"tr":["Yüzbaşının Kararı","Araştırmama göre bu iş o kadar karmaşık değil; kuklaları yöneten kişinin büyüsü zayıf, uzakta olamaz. Dön ve Aura Gözcüsü'ne sor, Sisli Ova'da şüpheli bir yaratık görmüş mü.","Kabul","Hâlâ burada ne duruyorsun, git söyle.","İlahi Göz Yüzbaşı gerçekten bilge!"],"en":["The Captain's Decision","From my investigation, this isn't so complicated; whoever controls the puppets has weak magic and can't be far. Go back and ask the Aura Watcher if he's seen any suspicious creature in the Misty Lowland.","Accept","Why are you still standing here? Go tell him.","The Godeye Captain is truly wise!"],"lv":24},{"id":82086,"giver":"夜精灵望气士","to":"夜精灵望气士","type":"kill","target":"安魂歌手","count":10,"sc":"漫雾低地","req":82085,"rw":{"gold":105,"items":[]},"lv":30,"tr":["Hipnozcu Katiller","Yüzbaşı öyle deyince aklıma geldi! Ağıt Şarkıcıları! Sisli Ova'da hep şarkı söyleyen o grup, dinleyenin tüylerini ürpertiyor! Kesin onların işi.","Kabul","Kesin Ağıt Şarkıcıları.","……"],"en":["Hypnotic Killers","Now that the captain mentions it, I remember! The Requiem Singers! That group always singing in the Misty Lowland; it gives you the creeps! It must be them.","Accept","It must be the Requiem Singers.","……"]},{"id":82087,"giver":"达尔","to":"达尔","type":"collect","target":"梦游傀儡","count":5,"sc":"漫雾低地","chance":0.6,"rw":{"gold":185,"items":[["30126",1]]},"lv":30,"tr":["Kukla Bebek","Gecekanat bir keresinde tehlikeli bir avda hayatımı kurtardı; hep borcumu ödemenin yolunu arıyorum. Kukla bebeklere bayıldığını duydum; Sisli Ova'daki uyurgezer kuklalar genelde böyle bebekleri yönetir… Ne olursa olsun bu sefer borcumu ödeyeceğim.","Kabul","Velinimetimin borcunu ödemeliyim.","Bunlar… ben… bir şey yok.","Kukla Bebek"],"en":["Puppet Doll","Nightwing once saved my life on a dangerous hunt, and I've always wanted to repay him. I hear he loves puppet dolls; the sleepwalking puppets in the Misty Lowland usually control such dolls… Whatever it takes, this time I'll repay him.","Accept","I must repay my benefactor.","These… I… it's nothing.","Puppet Doll"]},{"id":82088,"giver":"达尔","to":"夜羽","type":"talk","count":1,"req":82087,"rw":{"gold":75,"items":[["30126",1]]},"lv0":19,"tr":["Tuhaf Merak","Bu kukla bebekleri Gecekanat'a götür, bak bakalım hoşuna gidecek mi.","Kabul","Gecekanat'a götür.","Bu kukla bebekler… çok kirli.","Kukla Bebek"],"en":["A Strange Hobby","Take these puppet dolls to Nightwing and see if they suit his taste.","Accept","Take them to Nightwing.","These puppet dolls… so dirty."],"lv":23},{"id":82089,"giver":"夜羽","to":"达尔","type":"talk","req":82088,"rw":{"gold":66,"items":[]},"lv0":19,"tr":["Tencere Yuvarlanmış Kapağını Bulmuş","Aslında şarkıcı bebeklere bayılırım; şarkı söyleyen o bebekler her yalnız gecemde bana arkadaşlık eder. Gerçekten çok severim.","Kabul","Dur durma, dön ve Dal'a söyle.","Şarkıcı bebek! Gerçekten harika bir şey!"],"en":["Birds of a Feather","Actually, I love singer dolls; those singing dolls keep me company on every lonely night. I really love them.","Accept","Don't just stand there; go tell Dal.","A singer doll! What a wonderful thing!"],"lv":19},{"id":82090,"giver":"达尔","to":"达尔","type":"collect","target":"安魂歌手","count":2,"sc":"漫雾低地","chance":0.6,"req":82089,"rw":{"gold":176,"items":[["30126",1]]},"lv":30,"tr":["Şarkıcı Bebek","Sisli Ova'daki Ağıt Şarkıcıları şarkı söylerken ses üstlerindeki bir şeyden çıkıyor gibi; kesin onlar da uyurgezer kuklalar gibi bebek taşıyor! Onları öldür, uzun gecelerde bize arkadaşlık edecek iki şarkıcı bebek getir…","Kabul","Böyle bir şarkıcı bebeğe sahip olmak ne tuhaf bir mutluluk.","Harika!","Şarkıcı Bebek"],"en":["Singer Dolls","When the Requiem Singers of the Misty Lowland sing, the sound seems to come from something they carry; they must carry dolls just like the sleepwalking puppets! Kill them and bring two singer dolls to keep us company through the long nights…","Accept","Owning such a singer doll is a strange kind of joy.","Wonderful!","Singer Doll"]},{"id":82091,"giver":"达尔","to":"夜羽","type":"talk","count":1,"req":82090,"rw":{"gold":76,"items":[]},"lv0":19,"tr":["Sürpriz!","Şimdi şarkıcı bebeği Gecekanat'a götür; kesin sevinçten havalara uçar!","Kabul","Gecekanat'a götür! Sevinçten havaya zıplayacak.","Ah!!! Bu gerçek mi!!","Şarkıcı Bebek"],"en":["Surprise!","Now take the singer doll to Nightwing; he'll be over the moon!","Accept","Take it to Nightwing! He'll jump for joy.","Ah!!! Is this real!!","Singer Doll"],"lv":23},{"id":82092,"giver":"【飞毛腿】多多","to":"【飞毛腿】多多","type":"kill","target":"歌唱鸭","count":3,"sc":"漫雾低地","rw":{"gold":176,"items":[["30126",1]]},"lv":30,"tr":["Şarkı Söyleyen Ördekler","Ağıt Şarkıcılarının şarkısıyla insanı kendinden geçirdiğini duydum… Bu çok korkunç; onlara rastlarsam ölmüş sayılırım… Zekâm bana diyor ki tek elden ses çıkmaz! Kesin Sisli Ova'daki şarkıcı ördekler onlarla atışıyor! Şimdi git, şu küçük yaratıkları ez! Ne alçaklık!","Kabul","Bu küçük ördekler bana bulaşmaya cüret ediyor!","Şimdi kim olduğumu anladılar!"],"en":["Singing Ducks","I hear the Requiem Singers can entrance people with their songs… That's terrifying; if I meet them, I'm dead… My genius tells me it takes two to sing a duet! The singing ducks in the Misty Lowland must be singing along with them! Go squash those little creatures! How vile!","Accept","These little ducks dare to mess with me!","Now they know who they're dealing with!"]},{"id":80051,"giver":"观林镇镇长","to":"皇家骑士特使","type":"talk","req":81732,"rw":{"gold":206,"items":[]},"tr":["Kral'ın Fermanı","Bizim için o kadar çok şey yaptın ki hepsinin karşılığını veremeyiz. Senin gibi bir kahraman daha önemli yerlerde iş görmeli. Kral, Gümüşkartal Dükü'nün isyanındaki çıkmazı kırmak için Koşanat Şehri'nde maceracı topluyor. İşte bir tavsiye mektubu; bunu görünce değerini anlayacaklardır. Kendini göster!","Kabul","Tavsiye mektubunu Koşanat Şehri'ndeki Kraliyet Şövalye Elçisi'ne götür.","Guanlin muhtarının mektubu mu? Hoş geldin, yiğit; tam vaktinde geldin.","Tavsiye Mektubu"],"en":["The King's Decree","You've done so much for us that we can never repay it all. A hero like you should serve where it matters more. The King is gathering adventurers in Galloping Horse City to break the deadlock in the Silver Eagle Duke's rebellion. Here's a letter of recommendation; when they see it, they'll understand your worth. Make us proud!","Accept","Take the letter of recommendation to the Royal Knight Envoy in Galloping Horse City.","A letter from the mayor of Guanlin? Welcome, hero; you've come just in time.","Letter of Recommendation"],"lv":10},{"id":81618,"giver":"民兵队长","to":"民兵队长","type":"kill","target":"毒蛇帮路匪","count":4,"sc":"阳光森林","rw":{"gold":122,"items":[]},"lv":7,"tr":["Engerek Çetesine Ceza (1)","Delikanlı, buraya bir katkın olsun isterim. Köyün dışındaki ormanı Engerek Çetesi işgal etti; sıradaki hedefleri Guanlin Kasabası. Buradaki halkın acı çekmesine izin veremem; onları durdurmanın bir yolunu bulmalısın!","Kabul","Engerek Çetesine haddini bildir!","Harika iş, dostum."],"en":["Punish the Viper Gang (1)","Young one, I hope you'll do your part here. The forest outside the village has been taken over by the Viper Gang, and Guanlin Town is their next target. I can't let our people suffer; you must find a way to stop them!","Accept","Teach the Viper Gang a lesson!","Nicely done, friend."]},{"id":81619,"giver":"民兵队长","to":"民兵队长","type":"kill","target":"毒蛇帮精英","count":8,"sc":"阳光森林南","rw":{"gold":68,"items":[["10032",1],["10040",1]]},"lv":13,"tr":["Engerek Çetesine Ceza (2)","Bu sefer Engerek Çetesine ağır bir darbe vurmalıyız. Artık buna gücün yetiyor; beni hayal kırıklığına uğratmayacağına inanıyorum, değil mi?","Kabul","Engerek Çetesine haddini bildir!","Muhteşem, dostum! Artık belleri kırıldı."],"en":["Punish the Viper Gang (2)","This time we must deal the Viper Gang a heavy blow. You're strong enough now; I trust you won't let me down, right?","Accept","Teach the Viper Gang a lesson!","Splendid, friend! That crippled them."]},{"id":81623,"giver":"走私者","to":"走私者","type":"collect","target":"蜘蛛掠夺者","count":5,"sc":"阳光森林北","chance":0.6,"rw":{"gold":202,"items":[]},"lv":10,"tr":["Yağmacının Sırrı","Daha önce… bazı önemli eşyalarımı o lanet Örümcek Yağmacılar kaptı. Bu aslında bir sırdı; böyle mallarım olduğunu kimse bilmesin istiyordum. Sana sorunu çözmek için söylüyorum, sakın etrafa yayma… Pekâlâ, gerçek şu ki o yağmacılar şimdi Güneşli Orman Kuzey'e kaçtı. Onları bul… öldür, içindekileri bana getir.","Kabul","Yoksa hepsini kendine mi sakladın?","Ahh, bu küçük hazineler sonunda elime döndü… İyi ki sen ahmak değerlerini bilmiyorsun. Al ödülünü, haydi git!","Kilitli Kese"],"en":["The Raiders' Secret","Earlier… some important things of mine were stolen by those cursed Spider Raiders. It was supposed to be a secret; I didn't want anyone to know I had such goods. I'm telling you only to get this solved, so don't go spreading it… Well, the truth is those raiders have moved to Sunny Forest North. Find them… kill them, and bring me what they carry.","Accept","Did you keep them for yourself?","Ahh, my little treasures are back in my hands at last… Good thing an idiot like you doesn't know their worth. Take your reward and go!","Locked Pouch"]},{"id":81624,"giver":"走私者","to":"疯子","type":"talk","req":81623,"rw":{"gold":78,"items":[]},"tr":["Uyarı!","Ha, aklıma bir şey geldi: Deli'yi uyar, benden uzak dursun. Bir gün deliliği tutar da sırrımı ağzından kaçırır, kim bilir. Söyle ona, dikkatli olsun!","Kabul","Deli'ye uyarıyı ilet.","(Deli omuz silkiyor ve kıkırdıyor.)"],"en":["A Warning!","Oh, something just occurred to me: warn the Madman to stay away from me. Who knows, one day he might go mad and blurt out my secret. Tell him to watch it!","Accept","Pass the warning on to the Madman.","(The Madman shrugs and giggles.)"],"lv":10},{"id":81629,"giver":"观林镇镇长","to":"杰克医生","type":"talk","rw":{"gold":138,"items":[["30016",5],["30019",5],["30024",1]]},"tr":["Muhtarın Derdi","Son zamanlarda ne oluyor bilmiyorum, sırtım hep sızlıyor; yoksa kötü bir işaret mi bu? Kızım Doktor Jack'e görünmem için başımın etini yiyor ama işlerim o kadar yoğun ki hiç vaktim yok. Durumumu Doktor Jack'e anlatır mısın?","Kabul","Doktor Jack'e muhtarın durumunu anlat.","Sırt ağrısı mı? Hmm, bir düşüneyim."],"en":["The Mayor's Trouble","I don't know what's going on lately, but my back keeps stinging; could it be a bad omen? My daughter keeps nagging me to see Doctor Jack, but I'm too busy with official duties. Could you tell Doctor Jack about my condition?","Accept","Tell Doctor Jack about the mayor's condition.","Back pain? Hmm, let me think."],"lv":10},{"id":81630,"giver":"杰克医生","to":"杰克医生","type":"pickup","node":"魔法草","count":5,"sc":"阳光森林南","req":81629,"rw":{"gold":145,"items":[["30016",5],["30019",5],["30024",1]]},"lv":13,"tr":["Büyülü İksir (1)","Muhtarın sırt ağrısını geçirecek bir büyülü iksir üzerinde çalışmam gerek; malzemesi Güneşli Orman Güney'deki büyü otu. Ama orada bir sürü vahşi hayvan var; bu konuda bana bir tek sen yardım edebilirsin.","Kabul","Haydi büyü otlarını topla; Güneşli Orman Güney'de.","Biraz bekle, iksiri hemen hazırlıyorum.","Büyü Otu"],"en":["Magic Potion (1)","I need to work on a magic potion that will cure the mayor's back pain; the ingredient is the magic herb in Sunny Forest South. But there are many wild beasts there; only you can help me with this.","Accept","Go and gather the magic herbs in Sunny Forest South.","Wait a moment, I'll mix the potion right away.","Magic Herb"]},{"id":81631,"giver":"杰克医生","to":"观林镇镇长","type":"talk","req":81630,"rw":{"gold":28,"items":[["30016",5],["30019",5],["30024",1]]},"tr":["Büyülü İksir (2)","Sonunda bitti; bu iksiri muhtara götür. Onu acısından kurtaracağına söz veriyorum.","Kabul","İksiri muhtara götür.","Oh, sırtım rahatladı! Teşekkür ederim."],"en":["Magic Potion (2)","It's finally done; take this potion to the mayor. I promise it will free him from his pain.","Accept","Take the potion to the mayor.","Oh, my back feels better! Thank you."],"lv":13},{"id":81635,"giver":"疯子","to":"寡妇安娜","type":"talk","rw":{"gold":81,"items":[]},"tr":["Dul Kadına Taziye","Geceleri hep Anna'nın sessizce ağladığını duyuyorum. Ah, çocuğunu da kocasını da vahşi hayvanlar yedi; çok yazık. Git, yardımıma ihtiyacı var mı bir sor; varsa… anlarsın ya. Sakın karıma söyleme.","Kabul","Dul Anna ile konuş.","Deli mi gönderdi seni? Hıh."],"en":["Comfort the Widow","At night I always hear Anna weeping softly. Ah, her child and her husband were both eaten by wild beasts; it's so sad. Go and ask if she needs my help; if she does… you know. Whatever you do, don't tell my wife.","Accept","Talk to the Widow Anna.","The Madman sent you? Hmph."],"lv":13},{"id":81636,"giver":"寡妇安娜","to":"疯子的老婆","type":"talk","req":81635,"rw":{"gold":101,"items":[]},"tr":["Dulun Dileği","O Deli kendi karısıyla ilgilenmiyor da bana mı ilgi gösteriyor! Git, karısına söyle; biz kadınların öyle kolay kandırılmadığını bilsin. Kocam öldü diye bana yanaşmaya çalışmak ha? Asla!","Kabul","Deli'nin karısına anlat.","Neee? O mu?!"],"en":["The Widow's Wish","That Madman doesn't care about his own wife, yet he cares about me! Go and tell his wife; let her know we women aren't so easily fooled. Trying to get close to me because my husband died? Never!","Accept","Tell the Madman's wife.","Whaaat? Him?!"],"lv":10},{"id":81637,"giver":"疯子的老婆","to":"疯子","type":"talk","req":81636,"rw":{"gold":75,"items":[["30024",1]]},"tr":["Kıyamet Koptu","Alçak herif, onu asla affetmeyeceğim! Beni kandırmaya nasıl cüret eder, ona o kadar iyi davrandım! Madem öyle, gününü göstereceğim; buranın meşhur cadısıyım ben! Git, söyle ona, beni bir daha göremeyecek!","Kabul","Deli'ye haberi ver.","Eyvah! Karım duydu mu?!"],"en":["Raging Fury","That scoundrel, I'll never forgive him! How dare he deceive me after all I've done for him! Fine then, I'll show him; I'm the most famous shrew around here! Go and tell him he'll never see me again!","Accept","Give the Madman the news.","Oh no! My wife found out?!"],"lv":13},{"id":81638,"giver":"疯子","to":"疯子的老婆","type":"talk","req":81637,"rw":{"gold":31,"items":[["30024",1]]},"tr":["Karıcığım! Hata Ettim!","Yalvarırım, bana yardım etmelisin; hatamı anladım… Eminim sen bir yolunu bulursun.","Kabul","Deli'nin karısıyla konuş.","Hıh, şimdi mi aklı başına geldi?"],"en":["Darling! I Was Wrong!","Please, you have to help me; I know I was wrong… I'm sure you'll find a way.","Accept","Talk to the Madman's wife.","Hmph, he comes to his senses now?"],"lv":13},{"id":81639,"giver":"疯子的老婆","to":"疯子","type":"talk","req":81638,"rw":{"gold":27,"items":[]},"tr":["Affedilemez","Söyle ona, onu affetmeyeceğim! Ben daha ölmedim, başka kadınların peşine düşmeye nasıl cüret eder!","Kabul","Deli'ye cevabı ilet.","Affetmiyor mu? Ah, ne yapacağım şimdi…"],"en":["Unforgivable","Tell him I won't forgive him! I'm not even dead yet, and he dares to chase other women!","Accept","Take her answer to the Madman.","She won't forgive me? Oh, what do I do now…"],"lv":13},{"id":81640,"giver":"疯子","to":"疯子","type":"collect","target":"蜂蜜仙子","count":10,"sc":"阳光森林东","chance":0.5,"rw":{"gold":122,"items":[]},"lv":18,"tr":["Deli'nin Ricası","Dostum, Güneşli Orman Doğu'ya gitmen lazım; orada bal perileri var. Bir yolunu bul, onlardan tatlı toz al; tatlı yapmak için en iyi malzeme. Karıma nefis bir tatlı hazırlayacağım.","Kabul","Ah, bana mutlaka yardım etmelisin.","Çok teşekkür ederim, velinimetim!","Tatlı Toz"],"en":["The Madman's Request","Friend, I need you to go to Sunny Forest East; there are honey fairies there. Find a way to get sweet powder from them; it's the best ingredient for desserts. I want to make my wife a lovely treat.","Accept","Ah, you simply must help me.","Thank you so much, my benefactor!","Sweet Powder"]},{"id":81641,"giver":"疯子","to":"馋鬼","type":"talk","req":81640,"rw":{"gold":108,"items":[["30024",1]]},"tr":["Tatlı Yapımı","Dostum, paketlediğim bu tatlı tozu oradaki Obur'a ver; mutlaka nefis bir tatlı yapar. Gerçi gizlice atıştıracak ama yeterince malzeme hazırladım. Ha ha.","Kabul","Tatlı tozunu Obur'a götür.","Tatlı toz mu? Mmm, harika!"],"en":["Making Dessert","Friend, give this packed sweet powder to the Glutton over there; he'll make a delicious dessert. He'll sneak a few bites, but I prepared plenty. Ha ha.","Accept","Take the sweet powder to the Glutton.","Sweet powder? Mmm, wonderful!"],"lv":13},{"id":81642,"giver":"馋鬼","to":"馋鬼","type":"talk","count":1,"req":81641,"rw":{"gold":60,"items":[["30024",1]]},"tr":["Çeşni","Hımm, tadı gayet güzel; bir de bana bir porsiyon acılı kanat bulsan mükemmel olur, ha ha ha!","Kabul","Çabuk git gel.","Ha ha, bu tat kusursuz!","Acılı Kızarmış Kanat"],"en":["Seasoning","Mmm, it tastes great; if you could find me a serving of spicy roast wings, it would be perfect, ha ha ha!","Accept","Be quick.","Ha ha, this flavor is simply perfect!","Spicy Roast Wings"],"lv":10},{"id":81645,"giver":"护林游侠","to":"护林游侠","type":"kill","target":"☆精英护卫","count":5,"sc":"阳光森林东","rw":{"gold":150,"items":[["30024",1]]},"lv":18,"tr":["Hattı Yar","Guanlin Kasabası'nda bir hain çıktı: Sadinman kasabanın bilgilerini çaldı, şimdi de Güneşli Orman Doğu'da kim bilir ne çeviriyor. Bunu araştırmanı istiyorum; önce ☆Seçkin Muhafızların hattını yarmalısın.","Kabul","☆Seçkin Muhafızlara dikkat et.","Yardımın için teşekkürler; bu işi Milis Komutanı ile konuşacağım."],"en":["Break the Line","A traitor has appeared in Guanlin Town: Sadinman stole the town's intelligence, and now he's in Sunny Forest East plotting who knows what. I'd like you to investigate; first you must break through the ☆Elite Guards' line.","Accept","Beware of the ☆Elite Guards.","Thank you for your help; I'll discuss this with the Militia Captain."]},{"id":81646,"giver":"疯子","to":"疯子的老婆","type":"talk","rw":{"gold":87,"items":[]},"req":81642,"tr":["Deli'nin Kefareti","Obur tatlıyı bana verdi; neyse ki çok atıştırmamış. Eminim karım beni affedecek; Tanrım, yardım et! Onu mutlaka bizzat eline ver, kahraman!","Kabul","Tatlıyı Deli'nin karısına götür.","Bu tatlı… onun için mi yaptı?"],"en":["The Madman's Atonement","The Glutton gave me the dessert; luckily he didn't eat much of it. I'm sure my wife will forgive me; gods, help me! You must hand it to her personally, hero!","Accept","Take the dessert to the Madman's wife.","This dessert… he made it for me?"],"lv":13},{"id":81647,"giver":"疯子的老婆","to":"疯子","type":"talk","req":81646,"rw":{"gold":35,"items":[["30024",1]]},"tr":["Affet Onu","Onu affettim ama bir dahası yok; bir daha böyle yaparsa boşanırım!!!!","Kabul","Deli'ye müjdeyi ver.","Affetti mi? Yaşasın!"],"en":["Forgive Him","I've forgiven him, but there won't be a next time; if he does this again, I'll divorce him!!!!","Accept","Give the Madman the good news.","She forgave me? Hooray!"],"lv":13},{"id":81709,"giver":"民兵队长","to":"观林镇镇长","type":"talk","rw":{"gold":122,"items":[]},"tr":["Muhtar Değişti","Muhtar eskiden çok yufka yürekli biriydi; asla böyle sert cezalar vermezdi. Dön ve muhtara ceza yöntemine hayran kaldığımı söyle; bir de Güneşli Orman Doğu'daki ☆Engerek Çetesi Kasaplarını ne yapacağımızı sor.","Kabul","Muhtar ne yapacak acaba? Gerçekten değişti mi?","Komutan bu küçük işi bile çözemiyor; iyi ki sen varsın!"],"en":["The Mayor Has Changed","The mayor used to be very soft-hearted; he would never hand out such harsh punishments. Go back and tell the mayor I admire his methods, and ask him what we should do about the ☆Viper Gang Butchers in Sunny Forest East.","Accept","What will the mayor do? Has he really changed?","The captain can't even handle such a small matter; good thing you're here!"],"lv":7},{"id":81710,"giver":"观林镇镇长","to":"民兵队长","type":"kill","target":"☆毒蛇帮虐杀者","count":10,"sc":"阳光森林东","req":81709,"rw":{"gold":203,"items":[["30024",1]]},"lv":18,"tr":["Kasapların Sonu","Milis Komutanı'nın sorusunu hemen cevaplayabilirim; çok basit: Güneşli Orman Doğu'ya git ve onları kasaplıklarına pişman et! Hiç acıma! Kaçsalar da yalvarsalar da ancak kan onları pişman eder! İşin bitince Milis Komutanı ile konuş; bakalım bana hayran kalmış mı.","Kabul","Basit ve etkili; benim yolum budur. Merhamet hiçbir şeyi çözmez.","Demek şüphelerim doğruymuş; muhtarda gerçekten bir tuhaflık var…"],"en":["The End of the Butchers","I can answer the Militia Captain's question right away; it's simple: go to Sunny Forest East and make them regret their butchery! Show no mercy! Whether they flee or beg, only blood will make them repent! When you're done, talk to the Militia Captain and see if he admires me.","Accept","Simple and effective is my way. Mercy solves nothing.","So my suspicions were right; something really is wrong with the mayor…"]},{"id":81711,"giver":"民兵队长","to":"护林游侠","type":"talk","req":81710,"rw":{"gold":85,"items":[]},"tr":["Muhtar Gerçekten Değişti","Muhtar son zamanlarda bir sarsıntı mı geçirdi de böyle aşırı şeyler yapıyor? Git, Orman Korucusu'na sor; o her zaman muhtarın en iyi dostu oldu, bir şey fark etmiş mi bak.","Kabul","Muhtar gerçekten çok tuhaf, hiç anlayamıyorum.","Muhtar son zamanlarda neredeyse kimseyle konuşmuyor."],"en":["The Mayor Has Truly Changed","Has the mayor suffered some setback lately, to do such excessive things? Go and ask the Forest Ranger; he's always been the mayor's best friend; see if he's noticed anything.","Accept","The mayor is really strange; I can't make sense of it.","The mayor has hardly spoken to anyone lately."],"lv":7},{"id":81712,"giver":"护林游侠","to":"兽人医师","type":"talk","req":81711,"rw":{"gold":160,"items":[]},"tr":["Keşke Hastalık Olsa","Muhtar son zamanlarda benimle neredeyse hiç konuşmuyor; umarım sadece hastadır. Koşanat Şehri'ne git ve bir Ork Hekim bul; büyüde usta bu şifacı muhtarın hastalığını iyileştirebilir. Durum acil; \"Mürekkep\"imi bir günlüğüne sana ödünç veriyorum, ne kadar çabuk o kadar iyi!","Kabul","Muhtarın hastalığı ne acaba? Çok tuhaf.","Muhtar benim velinimetim, borcumu ödeyeceğim!"],"en":["I Hope It's Just Illness","The mayor hardly talks to me anymore; I hope he's only ill. Go to Galloping Horse City and find an Orc Healer; that healer, skilled in magic, should be able to cure the mayor. It's urgent; I'll lend you my \"Ink\" for a day, the sooner the better!","Accept","What illness could the mayor have? So strange.","The mayor is my benefactor; I'll repay him!"],"lv":18},{"id":81723,"giver":"炼金师","to":"炼金师","type":"collect","target":"☆☆【欺诈者】迪加","count":1,"sc":"奔马海港","chance":1,"rw":{"gold":160,"items":[["10057",1],["10073",1],["10909",1]]},"req":81722,"lv":25,"tr":["Kristal Küre","Bu iş epey karışık; bir fal bakmam gerekecek. Ama fal kristal kürem çalındı; mutlaka Koşanat Limanı'ndaki o haydutların işi. Kırmızılar giymiş bir cüce gördüm, galiba liderleri; cesedinden kristal küremi geri getir!","Kabul","Kristal kürem… o olmadan bir hiçim…","İşte kristal kürem, sapasağlam; çok teşekkür ederim!","Kristal Küre"],"en":["The Crystal Ball","This matter is rather complicated; I'll need to do a divination. But my crystal ball was stolen; it must be those bandits at Galloping Horse Harbor. I saw a gnome in red who seemed to be their leader; bring my crystal ball back from his corpse!","Accept","My crystal ball… without it I'm useless…","This is my crystal ball, perfectly intact; thank you so much!","Crystal Ball"]},{"id":81724,"giver":"炼金师","to":"炼金师","type":"talk","req":81723,"rw":{"gold":56,"items":[]},"tr":["Fal","Madem kristal küremi geri getirdin, sana bir fala bedava bakayım! Biraz bekle…","Kabul","Merak etme, senden para almayacağım; biraz bekle.","Korkunç bir gerçek… Kabullenmekten başka çaremiz yok…"],"en":["Divination","Since you brought back my crystal ball, I'll do a divination for you for free! Please wait…","Accept","Don't worry, I won't charge you; just a moment.","A terrible truth… we can only accept it…"],"lv":25},{"id":81725,"giver":"炼金师","to":"民兵队长","type":"talk","req":81729,"rw":{"gold":154,"items":[]},"tr":["Tarikat!","Tarikat! Ne korkunç bir durum; daha önce böyle şeyler duymuştum. Yoksa muhtar tarikatın kuklası mı oldu? Bu çok korkunç; kukla yalnızca kalbi olmayan bir cesettir. Guanlin Kasabası da tehlikede. Halkı tedirgin etmemek için gizlice Milis Komutanı'na sor; bakalım ne yapacak.","Kabul","Korkunç bir durum; düşündükçe tüylerim diken diken oluyor!","Muhtarın ruhunu belki de rivayetlerdeki Kalp Hırsızı Büyücü çaldı… Guanlin Kasabası gerçekten tehlikede!"],"en":["The Cult!","A cult! What a terrible situation; I've heard of such things before. Has the mayor become the cult's puppet? That's dreadful; a puppet is just a corpse without a heart. Guanlin Town is in danger too. So as not to alarm the townsfolk, quietly ask the Militia Captain what he'll do.","Accept","A horrifying situation; it makes my skin crawl just thinking about it!","Perhaps the mayor's soul was stolen by the rumored Heart-Stealing Mage… Guanlin Town really is in danger!"],"lv":25},{"id":81726,"giver":"民兵队长","to":"民兵队长","type":"kill","target":"受伤的银鹰战士","count":10,"sc":"草原前线","req":81725,"rw":{"gold":180,"items":[["30024",1]]},"lv":29,"tr":["Gücünü Kanıtla","Görünen o ki tarikatla doğrudan yüzleşmeden bu iş çözülmeyecek. Ama gücün sadece Engerek Çetesine yetiyorsa, tarikata karşı gitmek bir ceset göndermekten farksız olur. Sınavımı kabul et; bakalım yiğit misin korkak mı! Çayır Cephesi'ne git, 10 Yaralı Gümüşkartal Savaşçısı öldür ve gücünü kanıtla!","Kabul","Tarikatla savaşabilecek misin?","Seni küçümsemek benim hatammış."],"en":["Prove Your Strength","It seems we can only solve this by facing the cult directly. But if your strength is only enough for the Viper Gang, going against the cult would be like sending a corpse. Take my test; let's see if you're a hero or a coward! Go to the Prairie Front, kill 10 Wounded Silver Eagle Warriors and prove your strength!","Accept","Can you really fight the cult?","It was my mistake to underestimate you."]},{"id":81728,"giver":"炼金师","to":"炼金师","type":"collect","target":"森林巨魔","count":1,"sc":"巨魔森林","chance":1,"req":81724,"rw":{"gold":161,"items":[]},"lv":28,"tr":["Tuhaf Olaylar","İrade falım hep Trol Ormanı'nda bir engele takılıyor; bu nasıl iş? Üstelik son zamanlarda troller de huzursuz; normalde ot yiyen bu iri yaratıklar kana susadı. Belki muhtar oradaki durumdan endişelendiği için böyle oldu. Onlardan birkaç örnek getir, neler olduğuna bakayım.","Kabul","Trol Ormanı'nda neler oluyor acaba?","Bu ne? Kara bir muska mı? Bu şey ne işe yarıyor?","Şüpheli Nesne"],"en":["Strange Happenings","My will divination is always blocked at the Troll Forest; why is that? And lately the trolls are restless too; these normally plant-eating brutes have become bloodthirsty. Maybe the mayor became like this out of worry about that place. Bring back some samples from them; let me see what's going on.","Accept","What on earth is happening in the Troll Forest?","What's this? A black amulet? What does this thing do?","Suspicious Object"]},{"id":81729,"giver":"炼金师","to":"炼金师","type":"talk","count":1,"req":81728,"rw":{"gold":46,"items":[["30024",1]]},"tr":["Kara Muska","Bence bunu muhtara göstermelisin; ona merak etmemesini, çözümü bulduğumuzu söyle. Bakalım tuhaf hastalığı biraz düzelecek mi.","Kabul","Muhtar bu tuhaf şeyi görünce belki içindeki dert geçer.","Ne?! Bu hiç beklemediğim bir sonuç…","Kara Muska"],"en":["The Black Amulet","I think you should show this to the mayor; tell him not to worry, we've found a solution. Let's see if his strange illness improves.","Accept","Once the mayor sees this strange thing, perhaps his heart will be eased.","What?! I never expected this…","Black Amulet"],"lv":25},{"id":81731,"giver":"民兵队长","to":"观林镇镇长","type":"talk","count":1,"req":81726,"rw":{"gold":108,"items":[["30024",1]]},"tr":["Ruhun Dönüşü","(Bu soğuk şişeye dokunuyorsun; içinde mavi, soğuk bir ışık saçan bir sis var. Sis toplandığında içinde muhtarın acı çeken yüzünü görüyorsun.) ☆Tarikatçılar muhtarı belki de bununla yönetiyordu. Bunu al ve muhtarı kurtar.","Kabul","Artık içim rahat.","Öhö öhö… çok kötüyüm…","Ruh Şişesi"],"en":["The Soul Returns","(You touch the cold bottle; inside is a mist glowing with a cold blue light. As the mist gathers, you see the mayor's tormented face within.) The ☆cultists may have used this to control the mayor. Take it and save him.","Accept","Now I can rest easy.","Cough… I feel awful…","Soul Bottle"],"lv":7},{"id":81732,"giver":"观林镇镇长","to":"观林镇镇长","type":"kill","target":"☆邪教追随者","count":15,"sc":"邪教基地","req":81731,"rw":{"gold":92,"items":[]},"lv":31,"tr":["Kökünü Kazı","Ah, başım çatlıyor; bu süre boyunca sanki ölmüş gibi bulanık bir bilinçle yaşadım… Bu lanet tarikatçılar! Guanlin Kasabası'nın huzuru için, kahraman… yalvarırım, şu tarikatçıları bir an önce yok et!","Kabul","Guanlin Kasabası'nın geleceği için git, şu tarikatçıların kökünü kazı!","Sen her zaman Guanlin halkının kahramanı olacaksın!"],"en":["Wipe Them Out","Ah, my head is pounding; all this time I lived with a clouded mind, as if I'd died… These cursed cultists! For the peace of Guanlin Town, hero… I beg you, wipe out these cultists as soon as you can!","Accept","For the future of Guanlin Town, go and root out these cultists!","You will always be the hero of Guanlin's people!"]},{"id":80100,"giver":"艺术家工会代表","to":"艺术家工会代表","type":"talk","rw":{"gold":120,"items":[["33846",1]]},"lv0":29,"tr":["Farklı Altın","(Bu ince işçilik ancak dağ cücelerinde olur; altının üzerindeki gizemli baş da başlığına bakılırsa çok eski bir döneme ait. Güneşgören Şehri'nin Sanatçılar Loncası Temsilcisi bir ipucu verebilir.)","Kabul","Sanatçılar Loncası Temsilcisi ile konuş.","Bu altın… ilginç."],"en":["A Different Coin","(Such fine craftsmanship belongs only to dwarves, and judging by the headdress, the mysterious head on the coin is from a very ancient age. Sunwatch City's Artist Guild Representative may have a clue.)","Accept","Talk to the Artist Guild Representative.","This coin… interesting."],"lv":30},{"id":80113,"giver":"艺术家工会代表","to":"受伤的矮人大师","type":"talk","req":80100,"rw":{"gold":284,"items":[["33847",1]]},"lv0":29,"tr":["Toast'un Varisi","Altındaki başın Kargaşa Çağı'nın sonundaki elf kralı olduğu kesin; parayı birleştirmek için en iyi dağ cücesi ustalarına bastırmış. Ama bu kadim zanaat çoktan unutuldu. Elimde bulanık bir ipucu var: dağ cüceleri arasında Toast adlı çok ünlü bir bilgin varmış, olağanüstü zekâsıyla döküme dair bazı şeyler bulmuş; çoktan öldü. Ama hâlâ birkaç varisi var, Toast'un izinden bilinmeyeni keşfediyorlar. Altın Dalga Limanı'nın lağımında eşya toplarken çılgınca kazı yapan bir dağ cücesi görmüştüm; aradığın kişi o olmalı.","Kabul","Yaralı Dağ Cücesi Usta'yı bul.","Toast mu? Kim sordu?"],"en":["Toast's Heir","The head on the coin is surely the elf king at the end of the Age of Chaos, who ordered the best dwarf smiths to mint them to unify the currency. But this ancient craft was lost long ago. I have one vague lead: among the dwarves was a famous scholar named Toast, whose extraordinary mind uncovered things about minting; he died long ago. But he still has a few heirs who follow his will to explore the unknown. While collecting things in the Golden Wave Harbor sewers, I saw a dwarf digging madly there; he must be the one you're looking for.","Accept","Find the Wounded Dwarf Master.","Toast? Who's asking?"],"lv":30},{"id":80988,"giver":"温妮迪失心先知","to":"温妮迪失心先知","type":"talk","rw":{"gold":171,"items":[["31218",1]]},"lv0":29,"tr":["Öfkeyi Yatıştır","Büyü birçok canı aldı… Ne zaman gözlerimi kapasam korkunç bir gelecek görüyorum. Ölülerin öfkesini yatıştıramazsak hepimiz onların safına katılacağız. Bu ağıtı Aşağı Şehir Kenar Mahallesi'ne götürüp yak. Bir de… özel bir şeyle karşılaşırsan onun dediğini yap, yoksa canın tehlikeye girer!","Kabul","……","Ne büyük bir güç… Getirdiğin için teşekkürler; öfkelerini yatıştırmanın bir yolunu bulacağım. Böyle daha çok hortlak olduğuna eminim; yardımına yine ihtiyacım olabilir…"],"en":["Quell the Grudge","Magic has taken many lives… Whenever I close my eyes I see a terrible future. If we can't quell the dead's resentment, we'll all join their ranks. Take this elegy to the Lower City Slums and burn it. And… if you meet anything unusual, do as it says, or your life will be in danger!","Accept","……","Such great power… Thank you for bringing it back; I'll find a way to calm their fury. I'm sure there are many more such spirits; I may need your help again…"],"lv":50},{"id":81428,"giver":"温妮迪失心先知","to":"温妮迪失心先知","type":"talk","rw":{"gold":69,"items":[]},"lv0":29,"tr":["Geldiğin Yere Dön","Dostum, yardımın için teşekkürler. Şimdi geldiğin yere dön; sanırım seni Kâhin gönderdi, varlığımı sezebiliyor. Ona görevime devam ettiğimi söyle. Yolun açık olsun.","Kabul","Kehanet Kâhini'ne haber ver.","Marcos'un durumunu öğrendim, teşekkürler."],"en":["Back Where You Came From","Friend, thank you for your help. Now go back where you came from; I suppose the Prophet sent you, since he can sense my presence. Tell him I'll continue my mission. Travel safely.","Accept","Report to the Oracle Prophet.","I've learned how Marcos is doing; thank you."],"lv":50},{"id":81442,"giver":"奴隶商人","to":"奴隶商人","type":"talk","rw":{"gold":97,"items":[]},"lv0":29,"tr":["Soylu Hanımın Oyunu","O mallarla epey para kazandım; ne yapayım, akıllıyım. Hıh, bana hizmet edecek daha çok uşak lazım. Köle Tüccarı'na söyle: kölelerini bana satmazsa soylulara kafa tutmanın sonucunu görür.","Kabul","Para her şeyi satın alır.","Lanet kadın, soylu kanı var diye her istediğini yapabileceğini mi sanıyor!"],"en":["The Noblewoman's Ways","I made a fortune with those goods; what can I say, I'm clever. Hmph, I need more servants. Tell the Slave Trader that if he won't sell me his slaves, he'll learn what it means to defy nobility.","Accept","Money buys everything.","Wretched woman, does she think noble blood lets her do whatever she likes!"],"lv":10},{"id":81443,"giver":"妖术师","to":"妖术师","type":"talk","rw":{"gold":118,"items":[]},"lv0":29,"tr":["Tüccarın Ricası","Dostum, bana bir iyilik yapar mısın? Kölelerimi büyüyle bitkin ve zayıf göstermek istiyorum; böylece Soylu Hanım onlara göz dikmez. Kara Büyücü'ye git, mutlaka bir çaresi vardır.","Kabul","Kölelerimi kimseye vermem.","Ha, demek mesele bu."],"en":["The Trader's Request","Friend, could you do me a favor? I want to use sorcery to make my slaves look haggard and weak, so the Noblewoman stops eyeing them. Go to the Warlock; he's sure to have a way.","Accept","I won't give my slaves to anyone.","Oh, so that's what this is about."],"lv":33},{"id":81470,"giver":"法师工会会长","to":"法师工会会长","type":"kill","target":"吸血鬼法师","count":20,"sc":"恶魔之间","rw":{"gold":65,"items":[]},"lv":10,"tr":["Başkanın Sınavı (3)","İblis Odası'nın çevresindeki vampir büyücüleri temizlersen iblisin gücü zayıflar; umarım başarırsın.","Kabul","Hı hı, göster bakalım marifetini.","Güzel iş, beni hayal kırıklığına uğratmadın."],"en":["The Master's Trial (3)","If you clear out the vampire mages around the Demon Chamber, the demon's power will weaken; I hope you can do it.","Accept","Heh, let's see what you can do.","Well done; you didn't disappoint me."]},{"id":81471,"giver":"首席大法师","to":"首席大法师","type":"talk","rw":{"gold":63,"items":[]},"lv0":29,"tr":["Sonucu Bildir","Git, Başbüyücü'ye sınavının sonucunu anlat; beklediğimin üstünde, gücün değerini kanıtladı.","Kabul","Benimle ne işin var?","Senin hakkında duyduklarım var."],"en":["Report the Results","Go tell the Archmage the result of your trial; beyond my expectations, your strength has proven your worth.","Accept","What do you want with me?","I've heard about you."],"lv":37},{"id":81480,"giver":"移民代表","to":"移民代表","type":"kill","target":"吸血鬼法师","count":20,"sc":"恶魔之间","rw":{"gold":109,"items":[]},"lv":10,"tr":["Vampir Büyücüler","Bu lanet kan emici yarasalar! Buraya onlara kan sağlamak için göç etmedik. Pek çok arkadaşımı kaybettim, kendi canımı da vermek istemem. Dostum, o vampir büyücüleri öldürüp arkadaşlarımın intikamını alır mısın?","Kabul","Zavallı dostlarım, sizi anacağım.","Teşekkürler dostum, intikamımı aldın."],"en":["Vampire Mages","These cursed bloodsucking bats! We didn't migrate here to feed them our blood. I've lost many companions and don't want to lose my own life too. Friend, will you kill those vampire mages and avenge my companions?","Accept","My poor companions, I'll honor your memory.","Thank you, friend; you've avenged me."]},{"id":81790,"giver":"法师工会会长","to":"法师工会会长","type":"kill","target":"粘稠怪","count":10,"sc":"阴暗海岸","rw":{"gold":56,"items":[["30126",1]]},"lv":33,"tr":["Lonca Sınavı (2)","Kıyıda yapışkan canavarlar nereden çıktı? Buraya yayılmalarına izin verme, hemen durdur onları.","Kabul","Daha fazla vakit kaybetme.","Buraya yayılsalardı sonuçları düşünülemezdi; çok cesur davrandın."],"en":["Guild Trial (2)","How did gooey fiends appear on the coast? Don't let them spread here; stop them at once.","Accept","Don't waste any more time.","If they'd spread here, the consequences would be unthinkable; you were very brave."]},{"id":81791,"giver":"法师工会会长","to":"首席大法师","type":"kill","target":"☆灵气仙子","count":10,"sc":"阴暗海岸","req":81790,"rw":{"gold":67,"items":[]},"lv":33,"tr":["Lonca Sınavı (3)","Kıyıda tuhaf bir şey fark ettin mi? Bu periler nereden geldi? Yerin altından mı? Yoksa başka bir yerden mi? Bu, Büyücüler Loncası'ndaki son sınavın; ne yapacağını biliyorsundur.","Kabul","Orayı iyice araştır.","Çok başarılı oldun!"],"en":["Guild Trial (3)","Did you notice anything strange on the coast? Where did those fairies come from? Underground? Somewhere else? This is your last trial in the Mage Guild; I think you know what to do.","Accept","Investigate that place thoroughly.","You performed brilliantly!"]},{"id":81792,"giver":"首席大法师","to":"战士工会会长","type":"talk","req":81791,"rw":{"gold":81,"items":[["30126",1]]},"lv0":29,"tr":["Güneşgören Savaşçılar Loncası","Gücünü herkes gördü; şimdi sana çok önemli bir görev vereceğim. İnsanlar askerî limanımızı işgal etmeye başladı; ayrıntıları Savaşçılar Loncası Terası'ndaki başkana sor.","Kabul","Savaşçılar Loncası Başkanı ile konuş.","Başbüyücü mü gönderdi? Gel bakalım."],"en":["Sunwatch Warrior Guild","Everyone has seen your strength; now I'll give you a very important task. Humans have begun invading our naval port; ask the master at the Warrior Guild Terrace for details.","Accept","Talk to the Warrior Guild Master.","The Archmage sent you? Come here."],"lv":37},{"id":81793,"giver":"战士工会会长","to":"战士工会会长","type":"kill","target":"☆守卫","count":10,"sc":"望日城军港","rw":{"gold":74,"items":[]},"lv":35,"tr":["Denizi Geçmelerini Engelle","Lanet insanlar harekete geçti, askerî limanı işgal ettiler; denizi geçmelerini mutlaka engelle, oradaki ☆Muhafızları sil.","Kabul","Unutma, yalnız değilsin!","Harika iş! Askerî limanı korudun!"],"en":["Stop the Crossing","The cursed humans have made their move and occupied the naval port; you must stop them crossing the sea; wipe out the ☆Guards there.","Accept","Remember, you're not alone!","Splendid! You defended the naval port!"]},{"id":81794,"giver":"战士工会会长","to":"武技长","type":"talk","req":81793,"rw":{"gold":83,"items":[]},"lv0":29,"tr":["Liman Planı","İnsanların limanda bir miktar gücü var artık; yayılmalarına izin veremeyiz. Erzaklarını alıp adamlarını öldürmeliyiz. Silah Ustası'nı bul, bir yolunu bulur.","Kabul","Topraklarımız kutsaldır, dokunulamaz.","Geldin; oraya sürekli adam gönderip gözetliyordum, başlayalım."],"en":["The Harbor Plan","The humans now have some forces in the port; we can't let them expand. We must seize their supplies and kill their men. Find the Weapons Master; he'll have a way.","Accept","Our land is sacred and inviolable.","You've come; I've been watching that place, let's begin."],"lv":35},{"id":81795,"giver":"武技长","to":"武技长","type":"collect","target":"☆持刀者","count":10,"sc":"战士工会平台","chance":0.5,"req":81794,"rw":{"gold":77,"items":[["30126",1]]},"lv":10,"tr":["Silahları Topla","Önce silahlarını toplamalıyız; yani oradaki ☆Bıçaklıları öldürüp silahlarını almak. Ha ha, gücünü sınama vakti.","Kabul","Çabuk git gel!","İnsanların silahları hep kusurlu!","İnsan Silahı"],"en":["Seize the Arms","First we must take their weapons; that is, kill the ☆Knife Wielders there and seize their arms. Ha ha, time to test your strength.","Accept","Be quick!","Human weapons are all defective!","Human Weapon"]},{"id":81796,"giver":"武技长","to":"武技长","type":"kill","target":"弓箭手","count":10,"sc":"望日城军港","req":81795,"rw":{"gold":101,"items":[]},"lv":35,"tr":["Keskin Nişancı","Fark ettin mi, limanda çok okçu var; hepsi seçkin askerler. Arkana dikkat et; o okçuların hakkından geleceğine inanıyorum.","Kabul","Bize arkadan saldırmayı severler.","Liman geri alındı, sayende."],"en":["Sharpshooter","Have you noticed many archers at the port; all elite troops. Watch your back; I believe you can cut down those archers.","Accept","They like to attack us from behind.","The port has been retaken, thanks to you."]},{"id":81797,"giver":"武技长","to":"首席大法师","type":"talk","req":81796,"rw":{"gold":20,"items":[["30126",1]]},"lv0":29,"tr":["Başbüyücünün Çağrısı","Başbüyücü'nün seninle önemli bir işi var galiba; hemen git, gör onu.","Kabul","Vakit kaybetme!","Silah Ustası'nın limanı geri almasına yardım ettiğin için teşekkürler; şimdi alışılmadık bazı şeyler keşfettim."],"en":["The Archmage's Summons","It seems the Archmage has something important for you; go see him at once.","Accept","Don't waste time!","Thank you for helping the Weapons Master retake the port; I've now discovered some unusual things."],"lv":10},{"id":81831,"giver":"首席大法师","to":"战士工会会长","type":"talk","req":81792,"rw":{"gold":80,"items":[["30126",1]]},"lv0":29,"tr":["Başbüyücünün Bildirisi","Savaşçılar Loncası Başkanı'na söyle, Tarikat Üssü'nü gözetlemek için güçlü bir birlik göndersin; içimde kötü bir his var.","Kabul","Tarikat Üssü, tuhaf bir yer.","Neden bu kadar acele? Tarikat Üssü mü? Bana bırak."],"en":["The Archmage's Notice","Tell the Warrior Guild Master to send a strong force to watch the Cult Base; I have a bad feeling.","Accept","The Cult Base, a strange place.","Why the rush? The Cult Base? Leave it to me."],"lv":37},{"id":81834,"giver":"首席大法师","to":"刺客工会代表","type":"talk","req":81831,"rw":{"gold":101,"items":[["30126",1]]},"lv0":29,"tr":["Suikastçılar Loncası","Önce Suikastçılar Loncası Temsilcisi'ni bul; Güneşgören Şehri'nin Dinlenme Bölgesi'nde.","Kabul","Gece elfleri haini affetmez.","Başbüyücü'nün önerdiği sen misin? Göster bakalım marifetini."],"en":["The Assassins' Guild","First find the Assassins' Guild Representative; he's in Sunwatch City's Leisure District.","Accept","Night elves never forgive traitors.","You're the one the Archmage recommended? Show me what you can do."],"lv":37},{"id":81858,"giver":"炼金术工会代表","to":"炼金术工会代表","type":"collect","target":"☆毒液史莱姆","count":10,"sc":"垃圾场","chance":0.5,"rw":{"gold":116,"items":[]},"lv":38,"tr":["Zehir Örneği","Biraz zehir örneği lazım; ☆Zehir Slimelardan biraz zehir al, Aşağı Şehir'deki çöplükte yaşarlar.","Kabul","Zehirlerine dikkat et.","Güzel iş; bu zehirleri incelemem gerek.","Zehir Örneği"],"en":["Venom Samples","I need some venom samples; get some venom from the ☆Venom Slimes, who live in the Lower City dump.","Accept","Watch out for their venom.","Well done; I need to study this venom.","Venom Sample"]},{"id":81859,"giver":"炼金术工会代表","to":"医生工会代表","type":"talk","req":81858,"rw":{"gold":64,"items":[]},"lv0":29,"tr":["Örnek Raporu","Bu zehir gerçekten güçlü; çürütme hızı müthiş. Hemen Hekimler Loncası Temsilcisi'ne söyle, kirlilik giderek hızlanıyor.","Kabul","Vakit kaybetme!","Demek zehir bütün çöplüğe yayılmış."],"en":["Sample Report","This venom is truly potent; it corrodes incredibly fast. Go tell the Healers' Guild Representative that the pollution is accelerating.","Accept","Don't waste time!","So the venom has spread throughout the dump."],"lv":38},{"id":81860,"giver":"医生工会代表","to":"医生工会代表","type":"kill","target":"病变尸体","count":10,"sc":"垃圾场","req":81859,"rw":{"gold":69,"items":[["30126",1]]},"lv":38,"tr":["Cerrahi Müdahale","Zehir cesetleri bile diriltebiliyormuş; çöplükte yürüyen ölüler çoğaldı. Hemen git, onları yok et; Yukarı Şehir'e adım atmalarına izin verme.","Kabul","Neşterini al.","Bir felaketi önledin."],"en":["Surgery","The venom can even revive corpses; the dump is filling with walking dead. Go destroy them at once; don't let them set foot in the Upper City.","Accept","Pick up your scalpel.","You've prevented a disaster."]},{"id":81866,"giver":"首席大法师","to":"铁匠工会代表","type":"talk","rw":{"gold":87,"items":[["30126",1]]},"lv0":29,"tr":["Demir Cevheri","Biraz nadir demir cevheri lazım; Demirciler Loncası Temsilcisi'ne sor, onlar hep nadir cevher çıkarır.","Kabul","Rahatsız etme, düşünüyorum.","Son zamanlarda cevher bulmak çok zor."],"en":["Iron Ore","I need some rare iron ore; ask the Blacksmiths' Guild Representative; they always dig up rare ores.","Accept","Don't disturb me; I'm meditating.","Ore has been very hard to find lately."],"lv":37},{"id":81883,"giver":"首席大法师","to":"夜精灵蛇头","type":"talk","req":81866,"rw":{"gold":195,"items":[["30126",1]]},"lv0":29,"tr":["Gece Elfi Kaçakçıbaşı","Güneşgören Şehri'nin en akıllısı Gece Elfi Kaçakçıbaşı'nı bulmanı istiyorum; şimdi Altın Dalga Limanı'nda bazı şeyleri araştırıyor. Büyücüler Loncası Terası'ndaki ışınlanma çemberini bul, seni Altın Dalga Limanı'na götürür.","Kabul","Biraz yalnız kalmam lazım.","Benimle ne işin var?"],"en":["The Night Elf Snakehead","I need you to find the smartest person in Sunwatch City, the Night Elf Snakehead; he's investigating something in Golden Wave Harbor. Find the teleport circle on the Mage Guild Terrace; it'll take you to Golden Wave Harbor.","Accept","I need to be alone for a while.","What do you want with me?"],"lv":37},{"id":81948,"giver":"首席大法师","to":"浓雾镇镇长","type":"talk","rw":{"gold":77,"items":[]},"lv0":29,"tr":["Yoğunsis Kasabası'na Yardım","Cücelerin bize yardım etmesi için biz de cücelere yardım etmeliyiz; Yoğunsis Kasabası'nda bir kriz çıktı. Önce muhtarı bul, sonrasını ben ayarlayacağım.","Kabul","Hemen Yoğunsis Kasabası'na git.","Yine görüştük; seni uzun zamandır bekliyordum."],"en":["Help Thickfog Town","For the gnomes to help us, we must help them; a crisis has broken out in Thickfog Town. Find the mayor first, and I'll arrange the rest.","Accept","Head to Thickfog Town at once.","We meet again; I've been waiting for you a long time."],"lv":37},{"id":82051,"giver":"炼金术工会代表","to":"炼金术工会代表","type":"kill","target":"☆致死仙子","count":10,"sc":"噩梦平原东","rw":{"gold":225,"items":[]},"lv":24,"tr":["Yeni Zehir (1)","Aklıma yeni bir zehir tarifi geldi; öncekilerden kesin daha güçlü olacak. ☆Ölümcül Perilerin içinde bol zehir var ama toplanamıyor; git, ☆Ölümcül Perileri öldür, zehirleri silahına yapışır. ☆Ölümcül Periler Kâbus Ovası Doğu'da.","Kabul","Çok dikkatli ol, kendi güvenliğini düşün.","Gerçekten hızlısın; gel, silahındaki zehri alayım."],"en":["New Poison (1)","I've just thought of a new poison recipe; it'll surely be stronger than before. ☆Deadly Fairies contain lots of toxin, but it can't be harvested; go kill ☆Deadly Fairies and their toxin will cling to your weapon. ☆Deadly Fairies are in Nightmare Plain East.","Accept","Be careful; think of your own safety.","You really are fast; come, let me collect the poison on your weapon."]},{"id":82052,"giver":"炼金术工会代表","to":"炼金术工会代表","type":"kill","target":"鸡蛇","count":10,"sc":"噩梦平原中部","req":82051,"rw":{"gold":160,"items":[["10658",1]]},"lv":23,"tr":["Yeni Zehir (2)","Şimdi kokatrislerin üreme mevsimi; git, yumurtlayan kokatrisleri avla, üreme döneminde zehirleri çok artar. Yumurtlayan kokatrisler Kâbus Ovası Orta'da.","Kabul","Canavarların baharı geldi, benim baharım nerede?","Dikkat, dikkat, silahına dokunma…"],"en":["New Poison (2)","It's the cockatrices' breeding season; go hunt egg-laying cockatrices, whose toxin grows much stronger while breeding. They're in Nightmare Plain Center.","Accept","Spring has come for the monsters; where's mine?","Careful, careful, don't touch your weapon…"]},{"id":82053,"giver":"炼金术工会代表","to":"炼金术工会代表","type":"kill","target":"影狼","count":10,"sc":"噩梦平原中部","req":82052,"rw":{"gold":250,"items":[]},"lv":23,"tr":["Yeni Zehir (3)","İnsan haksızlığa uğrayınca kin biriktirir; canavarlar da öyle. Gözcü Kampı'nın muhafızları çok sayıda gölge kurdu püskürtmüş; içlerinde yaralılar olmalı. Yaralı canavarın içinde zehir oluşur; git, birkaç gölge kurt avla, belki tam aradığım şeydir. Gölge kurtlar Kâbus Ovası Orta'da.","Kabul","Uyarıyorum, sakın beni kırmayın!","Tam ihtiyacım olan şey; umarım kendini yaralamamışsındır?"],"en":["New Poison (3)","People who are wronged harbor grudges, and so do monsters. The Watcher Camp's guards drove off many shadow wolves; some must be wounded. Wounded monsters produce toxins; go hunt some shadow wolves, maybe that's just what I need. They're in Nightmare Plain Center.","Accept","I warn you, don't you dare upset me!","Just what I needed; I hope you didn't hurt yourself?"]},{"id":82106,"giver":"首席大法师","to":"温妮迪失心先知","type":"talk","req":82114,"rw":{"gold":57,"items":[["18489",1]]},"lv0":29,"tr":["Kâhinin Sözü","Tarikatın ne yapmak istediği hâlâ bir sır; iblisin neden ortaya çıktığı da tuhaf. Belki Aklını Yitirmiş Kâhin'e sormalısın; falı sana yol gösterir.","Kabul","Aklını Yitirmiş Kâhin Winnidy'ye sor.","İblis mi?… Bir bakayım."],"en":["The Prophet's Word","What the cult wants is still a mystery, and why a demon appeared is a strange question. Perhaps you should ask the Lost Prophet; her divination will show you the way.","Accept","Ask Winnidy the Lost Prophet.","A demon?… Let me see."],"lv":37},{"id":82107,"giver":"温妮迪失心先知","to":"浓雾镇镇长","type":"talk","rw":{"gold":106,"items":[["18489",1]]},"lv0":29,"tr":["Karanlık Mezar","Bu tuhaf güç daha önce dokunduğum bir eşyanınkiyle aynı. O şeyi bir kâşif Yoğunsis Kasabası tarafından getirmişti; bende ölüm ve korku hissi uyandıran bir güç. Belki oraya dönüp muhtara bunları sormalısın.","Kabul","Yoğunsis Kasabası Muhtarı ile konuş.","Yine mi sen? Gel, anlatacaklarım var."],"en":["The Dark Tomb","This strange power is the same as an object I once touched. An explorer brought that thing from the Thickfog Town area; a power that fills me with death and dread. Perhaps you should go back there and ask the mayor about it.","Accept","Talk to the Thickfog Town Mayor.","You again? Come, I have things to tell you."],"lv":50},{"id":82114,"giver":"首席大法师","to":"【指挥官】斯蒂芬","type":"talk","rw":{"gold":37,"items":[["17647",1]]},"lv0":29,"tr":["Savaşa Hazırlık","İlgili büyücüleri loncaya savaşa yardım etmeye göndereceğim; dön ve komutana söyle, iblisle savaşın hazırlığı başlıyor!","Kabul","【Komutan】Stephen ile konuş.","Büyücüler mi geliyor? Güzel, hazırlanalım."],"en":["Prepare for Battle","I'll send the relevant mages to the guild to help in the fight; go back and tell the commander that preparations for the battle with the demon have begun!","Accept","Talk to 【Commander】Stephen.","Mages are coming? Good, let's get ready."],"lv":37},{"id":82127,"giver":"温妮迪失心先知","to":"温妮迪失心先知","type":"kill","target":"☆恐惧卫士","count":10,"sc":"地下庙宇","rw":{"gold":107,"items":[]},"lv":50,"tr":["Lanetli Sınır","Bu kötü güçleri önceden görmenin yolunu buldum ama tam kritik anda tuhaf bir güç hep engel oluyor. Bu korku büyüsünü ancak tarikatın ☆Korku Muhafızları kullanabilir; bu engeli kaldırmama yardım et.","Kabul","Dikkat et, korku büyüleri çok tuhaftır.","Sanırım artık fal bakabilirim."],"en":["The Cursed Boundary","I've found a way to foresee these evil forces, but at the crucial moment some strange power always interferes. Only the cult's ☆Fear Guards could use such fear magic; help me remove this obstacle.","Accept","Careful, their fear magic is very strange.","I think I can perform the divination now."]},{"id":82128,"giver":"温妮迪失心先知","to":"神谕先知","type":"talk","req":82127,"rw":{"gold":133,"items":[["18100",1],["30126",1]]},"lv0":29,"tr":["Geleceği Gör","Ne ürkütücü bir kehanet; o iblisi tarikatçılar kötü bir çağırma çemberiyle çağırmış. O tuhaf kötü güç… kötü tanrı! Kadim kötü tanrının gücü! Ama kötü tanrı mühürlenmişti; bu güç neden hâlâ var? İnanılmaz; keşke falım yanlış çıksa. Hemen Kehanet Kâhini'ne söyle.","Kabul","Kehanet Kâhini'ne söyle.","Kötü tanrı mı?… Bu çok vahim."],"en":["Foresee the Future","What a shocking prophecy; that demon was summoned by cultists with an evil summoning circle. That eerie evil power… an evil god! The power of the ancient evil god! But the evil god was sealed; why does this power still exist? Unbelievable; I wish my divination were wrong. Go tell the Oracle Prophet at once.","Accept","Tell the Oracle Prophet.","An evil god?… This is grave."],"lv":50},{"id":82159,"giver":"奴隶商人","to":"军士长","type":"talk","req":82162,"rw":{"gold":154,"items":[]},"lv0":29,"tr":["Köle Tüccarının Cevabı","Ork köleleri mi askere alacaksınız? Kötü zamanda geldin; o köleleri Soylu Hanım az önce satın aldı. Hem de köle başına bir mücevher ödedi; bir soylu olarak kölelerini size bedavaya vermez.","Kabul","Paraya bayılırım!","Köle el değiştirince fiyat da bir hayli artar…"],"en":["The Trader's Reply","Requisition the orc slaves? Bad timing; the Noblewoman just bought them. And she paid one gem per slave; being a noble, she'll never let you take them for free.","Accept","I love money!","Once a slave changes hands, the price goes way up…"],"lv":38},{"id":82161,"giver":"军士长","to":"宝石加工者工会代表","type":"talk","req":82159,"rw":{"gold":200,"items":[["30126",1]]},"lv0":29,"tr":["Stoktaki Mücevherler","Şu an daha iyi bir çaremiz yok. Mücevherciler Loncası ordunun mücevherlerini saklıyor; git, Mücevherciler Loncası Temsilcisi'nden bir kese mücevher iste. Temsilci Güneşgören Şehri'nin Dinlenme Bölgesi'nde.","Kabul","Çabuk ol, kaybedecek vaktimiz yok.","Loncanın deposunda hiç stok kalmadı; Gözcü Kampı'nın muhafızları teçhizatlarına çok mücevher harcadı."],"en":["Gems in Stock","We have no better option right now. The Jewelers' Guild keeps the army's gems; go ask the Jewelers' Guild Representative for a bag of gems. He's in Sunwatch City's Leisure District.","Accept","Hurry, we have no time to lose.","The guild's vault is empty; the Watcher Camp's garrison spent too many gems on their gear."],"lv":38},{"id":82162,"giver":"军士长","to":"奴隶商人","type":"talk","rw":{"gold":231,"items":[]},"lv0":29,"tr":["Köleleri Askere Al!","Kâbusun Kaynağı gibi büyük bir desteğimiz olsa da genel gücümüz insanlardan çok geride; asker sayısı en büyük derdim. Gece elfleri hep azdır, senin gibi yiğitler daha da az. Gece elfi köle tüccarı yakın zamanda bir grup ork köle getirdi; orklar iyi savaşır, savaşa çok uygunlar. Mesajımı ona götür: kaçak kölelerine el koyacağımı söyle.","Kabul","Köle tüccarı paragözdür; gerekirse sert ol.","Başçavuşun mesajı mı? Anlat bakalım."],"en":["Conscript the Slaves!","Even with the great aid of the Source of Nightmares, our strength is far behind the humans'; manpower is my biggest worry. Night elves are always few, and heroes like you fewer still. The night elf slave trader recently brought in a group of orc slaves; orcs fight well and are perfect for war. Take him my message: I'm requisitioning his smuggled slaves.","Accept","The slave trader only cares about profit; be firm if you must.","A message from the Sergeant Major? Let's hear it."],"lv":38},{"id":82163,"giver":"宝石加工者工会代表","to":"宝石加工者工会代表","type":"collect","target":"灵魂蛇","count":10,"sc":"漫雾低地","chance":0.5,"rw":{"gold":178,"items":[["30126",1]]},"lv":30,"tr":["Ham Cevher","Tek yol şu: git, biraz ham cevher topla, ben de sana bir sandık mücevher arıtayım. Canavarlar parlak şeyler toplamaya bayılır; Sisli Ova'daki Ruh Yılanlarını öldür, üstlerindeki ham cevheri topla.","Kabul","En kaliteli mücevher ancak en kaliteli cevherden çıkar.","Gerçekten kaliteli cevher; biraz bekle, mücevherler hemen hazır.","Ham Cevher"],"en":["Raw Ore","There's only one way: go gather some raw ore, and I'll refine a chest of gems for you. Monsters love collecting shiny things; kill the Soul Snakes in the Misty Lowland and collect the raw ore they carry.","Accept","Only the finest ore yields the finest gems.","Truly fine ore; wait a moment, the gems will be ready soon.","Raw Ore"]},{"id":82165,"giver":"女贵族","to":"军士长","type":"talk","req":82161,"rw":{"gold":92,"items":[["30126",1]]},"lv0":29,"tr":["Soylu Hanımın Karşılığı","Ben de bir gece elfiyim, damarlarımda gece elfi kanı akıyor. İnsanlara karşı savaşı desteklemek isterim. Git, Başçavuş'a söyle: özel bir muhafız birliğim var; gerekirse ordusuna destek veririz.","Kabul","Soylu gece elfi kanım paraya tamamen bulaşmadı.","Bu kadın gerçekten derin biriymiş!"],"en":["The Noblewoman's Answer","I'm a night elf too; night elf blood runs in my veins. I want to support the war against the humans. Go tell the Sergeant Major I have a private guard; when needed, we'll support his army.","Accept","My noble night elf blood isn't entirely tainted by money.","This woman has hidden depths!"],"lv":33},{"id":82166,"giver":"军士长","to":"铁匠工会代表","type":"talk","rw":{"gold":210,"items":[]},"lv0":29,"tr":["Teçhizat Toplama","Köleleri birliklere dağıttım, askerlik hayatına çabuk alışsınlar diye kısa bir eğitimden geçiyorlar. Ama bir sorun daha var: ordunun bu gençleri donatacak silahı yok. Demirciler Loncası Temsilcisi'ni bul, ne durumda olduğuna bak. Temsilci Güneşgören Şehri'nin Dinlenme Bölgesi'nde.","Kabul","Yiğit savaşçı silaha daha çok muhtaçtır.","Loncada hiç silah kalmadı; savaşın masrafı çok büyük."],"en":["Gathering Equipment","I've assigned the slaves to squads for a short training so they can adapt to army life. But there's another problem: the army has no weapons to equip these youngsters. Find the Blacksmiths' Guild Representative and see how he's doing. He's in Sunwatch City's Leisure District.","Accept","The braver the warrior, the more he needs a weapon.","The guild has no weapons left; war is terribly expensive."],"lv":38},{"id":82167,"giver":"铁匠工会代表","to":"军士长","type":"collect","target":"☆觅血妖刀","count":10,"sc":"罪恶庭院","chance":0.5,"rw":{"gold":280,"items":[["30126",1]]},"lv":10,"tr":["Kanlı Kılıcın Gövdesi","Şimdi ocak yakıp silah dövmeye vakit yok. Ama hızlı ve riskli bir yolum var: Tarikat Üssü'ndeki ☆Kan Arayan Kılıçlar aslında ölen savaşçıların silahlarıdır; kötü canavarların kanına bulanıp bu hâle gelmişler. Onları öldürürsen gövdelerini alırsın, sonra doğrudan Başçavuş'a teslim edebilirsin. ☆Kan Arayan Kılıçlar Tarikat Üssü'nün ikinci katında, Günah Avlusu'nda.","Kabul","Kılıçların seni yaralamasın.","Bunca yıl geçmiş, bu silahlar hâlâ ne kadar keskin.","Kılıç Gövdesi"],"en":["Body of the Blade","There's no time to fire up the forge now. But I have a quick, risky way: the ☆Bloodseeking Blades in the Cult Base were once the weapons of fallen warriors, turned this way by the blood of evil monsters. Kill them to get their bodies, then report straight to the Sergeant Major. They're on the second floor of the Cult Base, the Courtyard of Sin.","Accept","Don't let the blades cut you.","After so many years these weapons are still so sharp.","Blade Body"]},{"id":82168,"giver":"军士长","to":"种植者工会代表","type":"talk","req":82166,"rw":{"gold":155,"items":[["30126",1]]},"lv0":29,"tr":["Erzak Toplama","Asker de silah da tamam ama önemli bir sorun daha var: ordu bu kadar çok yiyecek sağlayamıyor. Ekiciler Loncası Temsilcisi'ni bul, ihtiyacımızı karşılayabilir mi bak. Temsilci Dinlenme Bölgesi'nde.","Kabul","Atasözü der ki: ordu yürümeden önce erzak yürür. Haberini bekliyorum.","Yine mi yiyecek? Tencerelerimizin dibini kazıdınız…"],"en":["Gathering Food","We have troops and weapons now, but there's another big problem: the army can't supply so much food. Find the Growers' Guild Representative and see if he can meet our needs. He's in the Leisure District.","Accept","As the saying goes, before the army moves, the provisions move. I await your news.","Food again? You've scraped our pots clean…"],"lv":38},{"id":82169,"giver":"艺术家工会代表","to":"艺术家工会代表","type":"kill","target":"灵魂蛇","count":15,"sc":"漫雾低地","rw":{"gold":95,"items":[]},"lv":30,"tr":["Öldürme Sanatı","Sanatçı olmak mı istiyorsun? Sanat birçok şekilde kendini gösterir! Peki, yalvaran bakışların hatırına git, 15 Ruh Yılanı öldür! Sanatçı, öldüreceği hedefi de yöntemi de çok özgün seçer!","Kabul","Sanat her yerde!","Sanattan pek anlamıyorsun galiba."],"en":["The Art of Killing","You want to be an artist? Art shows itself in many ways! Fine, for the sake of your pleading eyes, go kill 15 Soul Snakes! An artist chooses both the target and the method of killing very uniquely!","Accept","Art is everywhere!","It seems you don't quite understand art yet."]},{"id":82170,"giver":"矮人奴隶","to":"矮人奴隶","type":"collect","target":"☆暗魂海星","count":10,"sc":"阴暗海岸","chance":0.5,"rw":{"gold":127,"items":[]},"lv":33,"tr":["Dağ Cücesi Kölenin Dileği","İyi kalpli yabancı! Şu yaşlı dağ cücesine bir iyilik yapar mısın? Karlı dağlarda doğdum, elli yaşımda yakalanıp buraya köle getirildim; yüzlerce yıl oldu… Denizi geçerken kıyıda beş köşeli, ışıl ışıl şeyler görmüştüm, ne güzeldiler! Onları bir daha görsem, bir dokunsam… birkaç ömür daha köle olmaya razıyım!","Kabul","O ışıl ışıl şey neydi acaba?","Harika! Harika! Sana sarılıp ağlamak istiyorum.","Deniz Kabuğu"],"en":["The Dwarf Slave's Wish","Kind stranger! Could you do this old dwarf a favor? I was born in the snowy mountains, captured and enslaved here at fifty, and it's been hundreds of years… When we crossed the sea I saw five-pointed, sparkling things on the shore; so beautiful! If I could see them again, touch them… I'd gladly be a slave for several more lifetimes!","Accept","What were those sparkling things?","Wonderful, wonderful! I want to hug you and cry.","Seashell"]},{"id":82171,"giver":"女贵族","to":"奴隶商人","type":"talk","rw":{"gold":177,"items":[["30126",1]]},"lv0":29,"tr":["Köle Kavgası","Bir cüce köle almak istiyorum; o küçük şeyler ne kadar komik! Onu bir trol kadar güçlü yetiştirmek istiyorum! Hep Köle Tüccarı'ndan alırım; bana bir cüce köle hediye eder mi, sorar mısın?","Kabul","Küçük cüceler çok eğlenceli!","Ne? Ona hediye mi edeyim?"],"en":["Slave Squabble","I want to buy a gnome slave; those little things are so funny! I want to raise one to be as strong as a troll! I always buy from the Slave Trader; could you ask if he'd give me a gnome slave as a gift?","Accept","Little gnomes are so much fun!","What? Give her one?"],"lv":33},{"id":82172,"giver":"奴隶商人","to":"女贵族","type":"talk","req":82171,"rw":{"gold":156,"items":[["30126",1]]},"lv0":29,"tr":["Göz Boyama","Eski müşterim ama iyi bir tüccarın ilk kuralı asla indirim yapmamaktır! Dön ve ona söyle: cüce kölemi dağ cücesi köle yedi! Artık yok! Bu arada… sen cüce köle ister misin? Sana ucuza veririm!","Kabul","Cüce köle ister misin?","Dağ cücesi köle mi yedi? Dağ cüceleri çok korkunç olmuş!"],"en":["Pulling the Wool","She's an old customer, but a good merchant's first rule is never give a discount! Go back and tell her my gnome slave was eaten by the dwarf slave! None left! Oh, by the way… do you want a gnome slave? I'll sell you one cheap!","Accept","Want a gnome slave?","Eaten by the dwarf slave? Dwarves have become so frightening!"],"lv":33},{"id":82173,"giver":"驭兽者工会代表","to":"驭兽者工会代表","type":"kill","target":"☆暗魂海星","count":15,"sc":"阴暗海岸","rw":{"gold":108,"items":[["10062",1],["10071",1],["10916",1]]},"lv":33,"tr":["Söz Dinlemeyen Yaratıklar","Terbiyeciler temsilcisi olarak dünyadaki her hayvanı evcilleştirebilirim! Elbette söz dinlemeyenler hep olur; belki beyinsizdirler. Bence beyni olmayanın yaşamasına gerek yok! Kasvetli Kıyı'ya git, temizle şunları.","Kabul","Söz dinlemeyen beyinsizdir, beyinsiz ölür.","Çok güzel, çok güzel."],"en":["Disobedient Creatures","As the beastmasters' representative, I can tame any beast in the world! Of course, there are always disobedient ones; maybe they have no brains. I think anything without a brain doesn't need to live! Go to the Gloomy Coast and wipe them out.","Accept","Disobedient means brainless means dead.","Very good, very good."]},{"id":82174,"giver":"驭兽者工会代表","to":"驭兽者工会代表","type":"kill","target":"粘稠怪","count":15,"sc":"阴暗海岸","req":82173,"rw":{"gold":70,"items":[]},"lv":33,"tr":["Kana Bulanan Deniz","Kıyıda hep yapışkan canavarlar çıkıyor, çok çok güzel kumsalımızı kirletiyorlar! Lafı uzatmayalım; çöp temizleme zamanı!","Kabul","İğrenç, beyinsiz yapışkan canavarlar!","Çok güzel, çok güzel!"],"en":["Blood in the Sea","Gooey fiends keep appearing on the coast and polluting our very, very beautiful beach! No more talk; time to take out the trash!","Accept","Disgusting, brainless gooey fiends!","Very good, very good!"]},{"id":82175,"giver":"格诺姆安抚者","to":"沙罗曼蛇烈焰侍女","type":"talk","rw":{"gold":153,"items":[["30126",1]]},"lv0":29,"tr":["Kurtçukları Yatıştır","Kan akıtan, yavaşça kıvranan, ölümsüz bedenler. Evet, bunlar kan solucanları! Elfler bile ölümsüz değilken bu kurtlar mı ölümsüz? Gerçekten ölümsüz olan Semender Alev Nedimesi'ne git, bu solucanları nasıl öldürebileceğimizi sor.","Kabul","Bu biz elfler için büyük bir aşağılanma.","O solucanlara çok acı çektirerek öldüreceğim!"],"en":["Appease the Maggots","Bleeding, slowly squirming, immortal bodies. Yes, these are blood worms! Even elves aren't immortal, and these worms are? Go ask the truly immortal Salamander Flame Maiden how to kill these worms.","Accept","This is a great humiliation for us elves.","I'll make those worms die a very painful death!"],"lv":35},{"id":82178,"giver":"种植者工会代表","to":"军士长","type":"collect","target":"喷毒蠕虫","count":10,"sc":"邪教基地","chance":0.5,"req":82167,"rw":{"gold":240,"items":[]},"lv":31,"tr":["Zehir Püskürten Solucan Eti","Aslında birçok canavarın eti yenebilir; en lezzetlisi solucan etidir, kurutulunca da iyi saklanır. Solucanların çoğu çok zehirlidir ama Zehir Püskürten Solucanların savaşta zehir püskürttükten sonra kısa süre zehirsiz kaldığını keşfettim. Biraz zehir püskürten solucan eti toplayıp Başçavuş'a götür; çok sevinecektir.","Kabul","Mutlaka zehrini püskürttükten sonra öldür, yoksa zehir etinde birikir.","Gerçekten kaliteli solucan eti; biraz bekle, hemen işlerim.","Solucan Eti"],"en":["Spitting Worm Meat","Actually many monsters' meat is edible; worm meat is the tastiest and keeps well dried. Most worms are very poisonous, but I found that Spitting Worms have no toxin for a short while after spitting in battle. Collect some spitting worm meat and take it to the Sergeant Major; he'll be delighted.","Accept","Kill them only after they spit, or the toxin will build up in the meat.","Truly fine worm meat; wait, I'll process it right away.","Worm Meat"]},{"id":82179,"giver":"兽人奴隶","to":"兽人奴隶","type":"collect","target":"粘稠怪","count":10,"sc":"阴暗海岸","chance":0.5,"rw":{"gold":115,"items":[["30126",1]]},"lv":33,"tr":["Ork Kölenin Dileği","Ben yakışıklı bir orkum! Şimdi köle düşmüş olsam da damarlarımdaki kan ruhumun özgür olduğunu söylüyor! Bedenin aşağılanması ruhun saflığını asla kirletemez. Ama şu an gerçekten çok sıkılıyorum; bana kemirecek bir şeyler getirir misin?","Kabul","Biraz tadı olsun ama!","Bunu kemirmek çok güzel! Kesin iyi bir şey.","Yapışkan Madde"],"en":["The Orc Slave's Wish","I'm a handsome orc! Though I've been reduced to a slave, the blood in my veins tells me my spirit is free! The body's humiliation can never stain the spirit's purity. But I'm really bored right now; could you bring me something to chew on?","Accept","Something with a bit of flavor, please!","This feels great to chew! Must be good stuff.","Sticky Substance"]},{"id":82180,"giver":"放债者","to":"走私者","type":"talk","rw":{"gold":118,"items":[]},"lv0":29,"tr":["Borcumu Tahsil Et","Kaçakçı bana epey borçlu, hep geciktiriyor! Faiziyle şimdiye bin ork köle alırdım! Git, paramı geri al! Param gelmezse uyuyamıyorum.","Kabul","Borcumu tahsil edeceğim! Uyumak istiyorum!","Ha! Unutmuşum; bir cüzdanıma bakayım."],"en":["Collect My Debt","The smuggler owes me a lot of money and keeps putting it off! With interest I could buy a thousand orc slaves by now! Go and get my money back! Without it I can't sleep.","Accept","I'll collect my debt! I want to sleep!","Oh! I forgot; let me check my wallet."],"lv":37},{"id":82181,"giver":"走私者","to":"放债者","type":"talk","rw":{"gold":86,"items":[["30126",1]]},"lv0":29,"tr":["Ekonomik Kriz","Çok üzgünüm, ekonomik kriz geldi, kıtadan mal bulmak zor; bak, cüzdanım yüzümden temiz! Dön ve Tefeci'ye söyle, çok üzgünüm; birkaç on yıl sonra kesin öderim.","Kabul","Ekonomik kriz benim gibi nice büyük girişimciyi batırdı.","Dolandırıcı!"],"en":["Economic Crisis","I'm really sorry, but there's an economic crisis and goods from the mainland are scarce; look, my wallet is cleaner than my face! Go back and tell the Moneylender I'm very sorry; I'll definitely pay him in a few decades.","Accept","The economic crisis ruined so many big entrepreneurs like me.","That swindler!"],"lv":10},{"id":82182,"giver":"放债者","to":"奴隶商人","type":"talk","req":82180,"rw":{"gold":89,"items":[]},"lv0":29,"tr":["Borç Peşinde","Bir zengin daha bana büyük bir borç taktı! Pinti herif! Parayı alırsan onda birini sana veririm! Ne? Az mı buldun? Oğluma bile kuruş kuruş veririm ben.","Kabul","Borcumu tahsil edeceğim! Uyumak istiyorum!","Ha! Doğru, ona epey borcum var."],"en":["More Debts to Collect","Another rich man owes me a fortune! That miser! If you get the money back, I'll give you a tenth! What? Too little? I give my own son coin by coin.","Accept","I'll collect my debt! I want to sleep!","Oh! It's true, I owe him quite a bit."],"lv":37},{"id":82183,"giver":"奴隶商人","to":"放债者","type":"talk","req":82181,"rw":{"gold":124,"items":[["30126",1]]},"lv0":29,"tr":["Durgun Piyasa","Ah, işler son zamanlarda hiç iyi değil! Bak, yeni getirdiğim bin cüce köleye hâlâ alıcı bulamadım! Bu ne para! Yüz bin cüce köle satınca borcunun yarısını kesin öderim!","Kabul","Gerçekten param yok.","Dolandırıcı!"],"en":["Slow Business","Ah, business has been bad lately! Look, I still haven't found buyers for these thousand new gnome slaves! What a cost! When I've sold a hundred thousand, I'll definitely pay him half!","Accept","I really have no money.","That swindler!"],"lv":37},{"id":82184,"giver":"妖术师","to":"妖术师","type":"kill","target":"☆灵气仙子","count":20,"sc":"阴暗海岸","rw":{"gold":55,"items":[["30126",1]]},"lv":33,"tr":["Kıyının Perileri","Kıyıda özümüzü emen periler türedi; zahmetle topladığım özün yarısından fazlasını emdiler! Doğanın dengesini bozan bu perileri öldür!","Kabul","☆Öz Perileri gerçekten çok alçak!","Özüm, özümün geri döndüğünü hissediyorum!"],"en":["Fairies of the Coast","Fairies that absorb our essence have appeared on the coast; they've sucked up more than half the essence I worked so hard to gather! Kill these fairies that upset nature's balance!","Accept","☆Essence Fairies are utterly vile!","My essence, I can feel my essence returning!"]},{"id":82185,"giver":"女贵族","to":"女贵族","type":"collect","target":"粘稠怪","count":10,"sc":"阴暗海岸","chance":0.5,"rw":{"gold":86,"items":[]},"lv":33,"tr":["Gece Bakımı","Benim gibi bir güzel her yerde ilgi odağıdır! Ama güzellik bakım ister; benim gibi büyük bir güzel için biraz yüz maskesi bulur musun? Kıskançlıktan gitmezlik etmezsin herhalde? Peki o zaman: Labilia'nın kirli havasındaki pislikleri ancak yapışkan bir maske temizler.","Kabul","Güzellik insanı hep meşgul eder!","Güzelliğime katkın için teşekkürler; bana birkaç kez daha bakabilirsin.","Yapışkan Maske"],"en":["Nightly Beauty Care","A beauty like me is the center of attention everywhere! But beauty needs maintenance; would you fetch some face masks for a great beauty like me? You won't refuse out of jealousy, will you? Well then: only a sticky mask can clear away the grime of Labilia's dirty air.","Accept","Beauty keeps one so busy!","Thank you for contributing to my beauty; you may look at me a few more times.","Sticky Mask"]},{"id":82186,"giver":"女贵族","to":"女贵族","type":"collect","target":"☆灵气仙子","count":10,"sc":"阴暗海岸","chance":0.5,"req":82185,"rw":{"gold":95,"items":[["30126",1]]},"lv":33,"tr":["Makyaj","Benim gibi bir güzeli ancak parlak şeyler ışıl ışıl yapar; bunu düşünebildiğim için kıskanıp gitmezlik etmezsin herhalde? Peki: ☆Öz Perisi tozu benim gibi bir güzele çok yakışır.","Kabul","Güzellik insanı hep meşgul eder!","Güzelliğime katkın için teşekkürler; bana birkaç kez daha bakabilirsin.","Öz Tozu"],"en":["Cosmetics","Only shiny things can make a beauty like me truly radiant; you won't refuse out of jealousy that I thought of it, will you? Well: ☆Essence Fairy dust is just right for a beauty like me.","Accept","Beauty keeps one so busy!","Thank you for contributing to my beauty; you may look at me a few more times.","Essence Dust"]},{"id":82188,"giver":"走私者","to":"铁匠工会代表","type":"talk","rw":{"gold":95,"items":[["30126",1]]},"lv0":29,"tr":["Kaçak Mal","Biraz zırh plakası kaçırmıştım ama bazı utanmazlar yolda kaptı! Bu iş duyulmamalı; Demirciler Loncası Temsilcisi ile konuş, kimin elinde olduğunu biliyorsa geri alınca ona da pay veririm!","Kabul","Bu lanet haydutlar.","Bu şeyler benim gözümden kaçmaz."],"en":["Smuggled Goods","I smuggled some armor plates, but some shameless thugs snatched them on the way! This can't get out; talk to the Blacksmiths' Guild Representative, and if he knows who has them, I'll give him a share once they're back!","Accept","Those damned bandits.","Nothing escapes my eyes."],"lv":10},{"id":82189,"giver":"铁匠工会代表","to":"铁匠工会代表","type":"collect","target":"☆守卫","count":10,"sc":"望日城军港","chance":0.5,"rw":{"gold":157,"items":[["30126",1]]},"lv":35,"tr":["Muhafız Zırh Plakası","Son zamanlarda bazı ☆Muhafızlar zırhlarını güçlendirmem için sürekli bana geliyor; bu yoksul muhafızlar o pahalı zırh plakalarını nereden buluyor? Eminim onlar! O ☆Muhafızlar Güneşgören Askeri Limanı'nda; cesetlerine bir bak.","Kabul","Kesin onlar, hiç şüphem yok.","Tamam, sözümüzü tutuyoruz; yarısını alıyorum.","Muhafız Zırh Plakası"],"en":["Guard Armor Plates","Lately some ☆Guards keep coming to me to reinforce their armor; where would these poor guards get such expensive plates? I'm sure it's them! Those ☆Guards are at the Sunwatch Naval Port; search their corpses.","Accept","It's definitely them, no doubt.","Fine, we keep our promise; I'll take half.","Guard Armor Plate"]},{"id":82191,"giver":"搜粮官","to":"搜粮官","type":"kill","target":"☆守卫","count":20,"sc":"望日城军港","rw":{"gold":129,"items":[["30126",1]]},"lv":35,"tr":["Önce Güvenlik!","Erzakımız son zamanlarda hızla azalıyor! Yoksa biri mi çalıyor? Yakında tuhaf davranan bir tek Güneşgören Askeri Limanı'nın ☆Muhafızları var! Önce güvenlik… bin masumu yanlışlıkla öldürsek de bir suçluyu kaçırmayalım.","Kabul","Güvenlik, savaş ikmalinin teminatıdır.","Harika! Yanlışlıkla öldürsek de fark etmez."],"en":["Safety First!","Our provisions have been plummeting lately! Is someone stealing them? The only ones acting strangely nearby are the ☆Guards of the Sunwatch Naval Port! Safety first… better to wrongly kill ten thousand than let one culprit go.","Accept","Safety guarantees war logistics.","Excellent! It doesn't matter if we got the wrong ones."]},{"id":82192,"giver":"劫掠队长","to":"劫掠队长","type":"kill","target":"☆持刀者","count":20,"sc":"望日城军港","rw":{"gold":82,"items":[["10064",1],["10072",1],["10917",1]]},"lv":35,"tr":["Yol Kesme!","Soygun! Ha, sen bir elfmişsin… Son zamanlarda bıçaklı bazı ufaklıklar buralarda gelip geçeni soyuyor! Yağma Yüzbaşısı benim! Bu işi yapmaya nasıl cüret ederler!","Kabul","Kabul edilemez!","Harika, ekmeğime göz dikmenin sonu bu!"],"en":["Highway Robbery!","A robbery! Oh, you're an elf… Lately some kids with knives have been robbing passersby around here! I'm the Raid Captain! How dare they do such a thing!","Accept","Intolerable!","Excellent, that's what they get for stealing my livelihood!"]},{"id":82193,"giver":"刺客工会代表","to":"刺客工会代表","type":"kill","target":"☆守卫","count":20,"sc":"望日城军港","rw":{"gold":106,"items":[]},"lv":35,"tr":["Muhafız Suikastı","Suikast başlıyor! İyi bir elf avcısı olarak düşmanı karanlıkta öldürmeyi öğrenmelisin; şimdi Güneşgören Askeri Limanı'na git ve o ☆Muhafızlara suikast düzenle!","Kabul","Suikastçı karanlıkta yürür.","Beni çok hayal kırıklığına uğrattın; onları yüz yüze, açık açık öldürdün."],"en":["Assassinate the Guards","The assassination begins! As a good elf hunter you must learn to kill in the dark; go to the Sunwatch Naval Port and assassinate those ☆Guards!","Accept","The assassin walks in darkness.","You've really disappointed me; you killed them face to face, out in the open."]},{"id":82194,"giver":"刺客工会代表","to":"刺客工会代表","type":"kill","target":"☆持刀者","count":20,"sc":"望日城军港","req":82193,"rw":{"gold":82,"items":[["30126",1]]},"lv":35,"tr":["Bıçaklılara Suikast","Başarısız suikastın beni hayal kırıklığına uğrattı ama birine bu kadar erken hüküm vermemeliyim. Şimdi ☆Bıçaklılara suikast düzenle; sessizce öldürmeyi unutma!","Kabul","Suikastçı karanlıkta yürür.","Sanırım artık kararımı verebilirim: sen savaşçı olmaya uygunsun!"],"en":["Assassinate the Knife Wielders","Your failed assassination disappointed me, but I shouldn't judge anyone so soon. Now assassinate the ☆Knife Wielders; remember to kill them quietly!","Accept","The assassin walks in darkness.","I think I can conclude: you're suited to be a warrior!"]},{"id":82198,"giver":"人类奴隶","to":"奴隶商人","type":"talk","rw":{"gold":201,"items":[]},"lv0":29,"tr":["İnsan Kölenin Dileği","İyi kalpli elf! İnsan olsam da sıradan biriyim; soydaşlarınızı öldürmeyi, Güneşgören Şehri'ni almayı hiç düşünmedim, hiç… (İnsan köle ağlamaya başladı…) Freyania'ya dönüp yaşlı anamı görmek istiyorum; belki… belki o… Bana yardım eder misin? Köle Tüccarı'na yalvar, beni kurtarsın!","Kabul","Kurtar beni! Evime dönmek istiyorum.","İnsan köle mi gönderdi? Ne iyi kalplisin."],"en":["The Human Slave's Wish","Kind elf! Though I'm human, I'm just an ordinary man; I never thought of killing your kin or taking Sunwatch City, never… (The human slave starts to cry…) I want to go back to Freyania and see my old mother; maybe… maybe she… Can you help me? Beg the Slave Trader to set me free!","Accept","Save me! I want to go home.","The human slave sent you? You really are kind."],"lv":35},{"id":82199,"giver":"奴隶商人","to":"人类奴隶","type":"talk","req":82198,"rw":{"gold":78,"items":[["30126",1]]},"lv0":29,"tr":["Paragöz","Bana iki sandık para verirsen belki şartını kabul ederim! Ama o insan, iki katı olmalı! Bir sandığa ne kadar sığar mı? Neyse, paran olmadığına göre dön ve ona söyle, burada huzur içinde yaşlansın.","Kabul","Para varsa her şey konuşulur.","Ne yapacağım şimdi! Hiç param yok."],"en":["Money-Grubber","If you give me two chests of money, maybe I'll accept! But he's human, so double that! How much does a chest hold? Well, since you have no money, go tell him to grow old here in peace.","Accept","With money, anything can be discussed.","What do I do now! I have no money."],"lv":35},{"id":82200,"giver":"人类奴隶","to":"人类奴隶","type":"collect","target":"弓箭手","count":10,"sc":"望日城军港","chance":0.5,"req":82199,"rw":{"gold":105,"items":[]},"lv":35,"tr":["Aklıma Geldi","Buldum! Geçen gün birçok okçunun nereden çaldıkları belli olmayan birkaç sandık eşyayı sattığını gördüm; epey para kazanmışlar! Belki cüzdanlarını getirirsen fidyemi denkleştirebiliriz! Teşekkürler, iyi kalpli yabancı.","Kabul","Evime dönmek istiyorum.","Bu para hiç yetmiyor…","Okçu Cüzdanı"],"en":["A Bright Idea","I know! The other day I saw many archers selling a few chests of goods they'd stolen from who knows where; they made a lot of money! Maybe if you bring their wallets we can scrape together my ransom! Thank you, kind stranger.","Accept","I want to go home.","This isn't nearly enough…","Archer's Wallet"]},{"id":82201,"giver":"人类奴隶","to":"女贵族","type":"talk","req":82200,"rw":{"gold":117,"items":[["30126",1]]},"lv0":29,"tr":["Soylu Hanımla İş Birliği","Sanırım bu hayatta evime dönemeyeceğim… yaşlı anamı göremeyeceğim… Hep bu cimri yüzünden! Soylu Hanım'ın iyi biri olduğunu hep duydum; acaba böyle bir zengin bana yardım eder mi…","Kabul","Evime dönmek istiyorum.","Yine mi o köle tüccarı? Para için yapmayacağı şey yok!"],"en":["Teaming Up with the Noblewoman","I suppose I'll never go home in this life… never see my old mother… All because of that miser! I've always heard the Noblewoman is kind; I wonder if someone so rich would help me…","Accept","I want to go home.","That slave trader again? There's nothing he won't do for money!"],"lv":35},{"id":82202,"giver":"女贵族","to":"人类奴隶","type":"talk","req":82201,"rw":{"gold":57,"items":[["30126",1]]},"lv0":29,"tr":["Köle Tüccarını Cezalandır","Böyle biri cezalandırılmalı! Merak etme, bu iş bende; yıllardır gurbette savrulan zavallı bir yüreğin hissini anlıyorum. Lütfen ona ilet.","Kabul","Bazı elfler bir insan köle kadar bile değil!","Ona da sana da çok teşekkür ederim!"],"en":["Punish the Slave Trader","Such a man must be punished! Don't worry, leave it to me; I understand how a poor heart feels after drifting so many years from home. Please tell him.","Accept","Some elves are worse than a human slave!","Thank her so much, and thank you too!"],"lv":33},{"id":82203,"giver":"格诺姆安抚者","to":"格诺姆安抚者","type":"kill","target":"弓箭手","count":20,"sc":"望日城军港","rw":{"gold":47,"items":[["30126",1]]},"lv":35,"tr":["İnsanları Yatıştır","Bazı insanlar limanımıza çıktı bile; şimdi soylu elfler adına emrediyorum: hemen git, bu misafirleri karşıla ve onları \"yatıştır\"…","Kabul","İyice \"yatıştırmayı\" unutma.","Gerçekten akıllı birisin."],"en":["Appease the Humans","Some humans have already landed in our harbor; on behalf of the noble elves I order you to go at once, greet these guests and \"appease\" them…","Accept","Remember to \"appease\" them thoroughly.","You really are clever."]},{"id":82204,"giver":"走私者","to":"铁匠工会代表","type":"talk","rw":{"gold":60,"items":[["30126",1]]},"lv0":29,"tr":["Gizli Alışveriş","Son zamanlarda bir planım var ama özel konumum yüzünden ortaya çıkmam uygun değil. Genç elf, mesajımı iletir misin? İş olursa sana da yararı dokunur!","Kabul","Akıllı insan kazancı kaçırmaz.","Ha! Anladım, demek o iş."],"en":["A Secret Deal","I have a plan lately, but given my special position I shouldn't show my face. Young elf, will you pass on my message? If the deal goes through, there's something in it for you!","Accept","A smart person never passes up profit.","Ah! I see, so it's that business."],"lv":10},{"id":82205,"giver":"铁匠工会代表","to":"铁匠工会代表","type":"collect","target":"弓箭手","count":10,"sc":"望日城军港","chance":0.5,"rw":{"gold":194,"items":[["30126",1]]},"lv":35,"tr":["Gerekli Aletler","Mektup getirdiğine göre güvenilir birisin. Bir parti kaliteli ok kaçırmaya hazırlanıyoruz; insanlara satmak yasak ama büyük para bizi çağırıyor! Bu riske giriyorum! Yardım edersen kaçakçı da seni ödüllendirir; Güneşgören Askeri Limanı'ndan biraz bileme aleti getir!","Kabul","Sessizce zengin ol!","Bu bileme aletleriyle işi çabuk bitiririz!","Bileme Aleti"],"en":["Necessary Tools","Since you brought the letter, you must be trustworthy. We're preparing to smuggle a batch of quality arrows; selling to humans is illegal, but big money is calling! I'll take the risk! If you help, the smuggler will reward you too; bring some sharpening tools from the Sunwatch Naval Port!","Accept","Get rich quietly!","With these sharpening tools we'll finish soon!","Sharpening Tool"]},{"id":82208,"giver":"沙罗曼蛇烈焰侍女","to":"沙罗曼蛇烈焰侍女","type":"talk","rw":{"gold":54,"items":[]},"lv0":29,"tr":["Üzgün Nedime","(Ağlıyor…) Kolyemi kaybettim… annemin verdiği kolyeyi… Ne yapacağım! Annemden kalan tek hatıra! Bu zavallıya yardım eder misin?","Kabul","Nedimeyi dinle.","Gerçekten yardım edecek misin?"],"en":["The Sad Maiden","(Crying…) I lost my necklace… the necklace my mother gave me… What do I do! It's my mother's keepsake! Will you help this poor soul?","Accept","Listen to the maiden.","Will you really help?"],"lv":33},{"id":82209,"giver":"沙罗曼蛇烈焰侍女","to":"沙罗曼蛇烈焰侍女","type":"collect","target":"☆灵气仙子","count":1,"sc":"阴暗海岸","chance":1,"req":82208,"rw":{"gold":134,"items":[]},"lv":33,"tr":["Kayıp Kolye","Rüyamda hep benimle oynaşan periler görüyorum; semender iradesi bana bunun kayıp eşyamla ilgili olduğunu söylüyor. Eminim o ☆Öz Perileri çaldı! Benim eşyamı çalmak ha! Canlarına susamışlar!","Kabul","☆Öz Perileri gerçekten çok alçak!","Teşekkürler, soylu elf.","Nedimenin Altın Kolyesi"],"en":["The Lost Necklace","In my dreams I keep seeing fairies playing with me; the salamander's will tells me it's connected to what I lost. I'm sure those ☆Essence Fairies stole it! Stealing from me! They must be tired of living!","Accept","☆Essence Fairies are utterly vile!","Thank you, noble elf.","Maiden's Gold Necklace"]},{"id":82210,"giver":"沙罗曼蛇烈焰侍女","to":"沙罗曼蛇烈焰侍女","type":"collect","target":"☆持刀者","count":1,"sc":"望日城军港","chance":1,"req":82209,"rw":{"gold":124,"items":[["30126",1]]},"lv":35,"tr":["Kayıp Yüzük","Yüzüğüm! Lanet hırsızlar! Annemden kalma değil ama ilk erkek arkadaşımın hediyesi! O hırsızlar yüzüğü haydutlara satmış! ☆Bıçaklılar kalabalık; yüzüğümü geri getirir misin? Mutlaka birinin üstündedir.","Kabul","Bu yüzük benim için çok önemli.","Teşekkürler, soylu elf.","Nedimenin Yüzüğü"],"en":["The Lost Ring","My ring! Those damned thieves! It's not from my mother, but it was a gift from my first boyfriend! The thieves sold it to bandits! There are many ☆Knife Wielders; could you get my ring back? It must be on one of them.","Accept","This ring means a lot to me.","Thank you, noble elf.","Maiden's Ring"]},{"id":82211,"giver":"军士长","to":"首席大法师","type":"talk","rw":{"gold":192,"items":[["30126",1]]},"lv0":29,"tr":["Başbüyücüyü Ziyaret","Cephedeki savaş çıkmazda, insan ordusunun baskısı giderek artıyor. Doğru yolu bulmalıyız: devam mı, çekilmek mi? Başbüyücü'yü bul, Kâhin Winnidy'den savaşın geleceğini görmesini istesin. Başbüyücü Kâhin'in öğrencisidir; Güneşgören Şehri Büyücüler Loncası Terası'nda.","Kabul","Kâhin Winnidy su büyücülerinin önderidir; bilgeliği ve kehanet gücü ölçülemez.","Kehanet mi? Kâhin aklını yitirdi, kehanet gücünü kaybetti. Zavallı hocam böyle oldu; onu şimdi Güneşgören Şehri'nde görebilirsin, herkes ona Aklını Yitirmiş Kâhin Winnidy diyor."],"en":["Visit the Archmage","The war at the front is deadlocked, and the human army's pressure grows. We need the right guidance: fight on or withdraw? Find the Archmage and have him ask Prophet Winnidy to foresee the war's future. The Archmage is the Prophet's pupil, at Sunwatch City's Mage Guild Terrace.","Accept","Prophet Winnidy leads the water mages; her wisdom and prophetic power are immeasurable.","A prophecy? The Prophet has lost her mind and her power of prophecy. My poor teacher, reduced to this; you can find her in Sunwatch City now; everyone calls her Winnidy the Lost Prophet."],"lv":38},{"id":82212,"giver":"首席大法师","to":"神谕先知","type":"talk","rw":{"gold":298,"items":[["30126",1]]},"lv0":29,"tr":["Gerçeği Ara","Hocam Özel Ataşe ile Tarikat Üssü'nü araştırdıktan sonra aklını yitirdi; sonra ataşe Tarikat Üssü'ne kaçtı. O alçak hain, hocama kesin o tuzak kurdu. Ataşeyi öldürüp eşyalarını Kehanet Kâhini'ne verdiğini duydum; git, Kâhin'e sor, hocamı kurtaracak bir ipucu bulmuş mu.","Kabul","Hocam da Kehanet Kâhini gibi gece elfleri arasında çok saygındır; ona yardım etmek senin de sorumluluğun.","Kâhin Winnidy biz gece elflerinin hiç dinmeyen acısıdır. Ataşenin eşyalarını dikkatle inceledim ama işe yarar bir ipucu bulamadım."],"en":["Seek the Truth","My teacher lost her mind after investigating the Cult Base with the Military Attaché; then the attaché defected to the Cult Base. That vile traitor surely set a trap for her. I hear you killed the attaché and gave his belongings to the Oracle Prophet; go ask the Prophet if she found any clue to save my teacher.","Accept","My teacher, like the Oracle Prophet, is highly revered among night elves; you have a duty to help her.","Prophet Winnidy is an everlasting sorrow for us night elves. I studied the attaché's belongings carefully but found no useful clue."],"lv":37},{"id":82215,"giver":"首席大法师","to":"首席大法师","type":"collect","target":"望日城士兵","count":1,"sc":"下城区贫民窟","chance":1,"req":82212,"rw":{"gold":85,"items":[["30126",1]]},"lv":37,"tr":["Askerin Kalbi","Aşağı Şehir'deki askerler tarikat tarafından hipnotize edilmiş gibi; git, onları öldür ve kalplerini getir; ☆Fanatik Savaşçıların kontrol edilme biçimiyle aynı mı, inceleyeyim.","Kabul","Dikkatli ol; en korkak kişi bile ölümle yüz yüze gelince çok tehlikeli olur.","Kalpleri kapkara olmuş; ☆Fanatik Savaşçılarınkiyle aynı maddeler var. Bu ciddi bir sorun ama iyi iş çıkardın; ileride bana yine yardım edeceğin olur sanırım.","Askerin Kalbi"],"en":["The Soldier's Heart","The soldiers in the Lower City seem hypnotized by the cult; go kill them and bring back their hearts so I can see if it's the same as how the ☆Fanatic Warriors are controlled.","Accept","Be careful; even the most cowardly become very dangerous when facing death.","Their hearts have turned black, with the same substance as the ☆Fanatic Warriors'. This is a serious problem, but you did well; I think you'll help me again in the future.","Soldier's Heart"]},{"id":82216,"giver":"格诺姆安抚者","to":"格诺姆安抚者","type":"collect","target":"望日城士兵","count":5,"sc":"下城区贫民窟","chance":0.6,"rw":{"gold":114,"items":[]},"lv":37,"tr":["Toprağı Yatıştır","Güneşgören Şehri şiddetli depremlerle yıkılmasın diye her gün gnomların hareketini gözlüyoruz. Olağandışı güçlü bir yer kayması fark ettim. Gnomların öfkesini yatıştırmak için sunu gerekiyor. Birkaç ceset. Aşağı Şehir'deki askerlerden toplayabilirsin.","Kabul","Gelişigüzel ölüm saçmak istemem ama bazen fedakârlık kaçınılmazdır.","Döndün; tören birazdan başlayacak…","Sunu Cesedi"],"en":["Appease the Earth","So Sunwatch City isn't destroyed by violent quakes, we watch the gnomes' activity daily. I've detected an unusually strong shift in the strata. We need offerings to appease the gnomes' wrath. Some corpses. You can collect them from the soldiers in the Lower City.","Accept","I don't wish to spread death carelessly, but sometimes sacrifice is unavoidable.","You're back; the ceremony will begin soon…","Sacrificial Corpse"]},{"id":82217,"giver":"武技长","to":"武技长","type":"kill","target":"☆潦倒的战士","count":20,"sc":"下城区贫民窟","rw":{"gold":50,"items":[["30126",1]]},"lv":37,"tr":["Savaşçının Yeri","Savaşçının yeri savaş alanıdır. Kenar mahallede dolaşan o korkaklar savaşçı denmeyi hak etmiyor. Elflerin yüz karası onlar; tek gidecekleri yer mezar!","Kabul","O korkaklara acıyor musun, yoksa onlardan korkuyor musun?!","Onlarda savaşçı yüreği kalmamış; üzülmene gerek yok."],"en":["A Warrior's Place","A warrior's place is the battlefield. Those cowards roaming the slums don't deserve to be called warriors. They're a disgrace to elves; their only place is the grave!","Accept","Do you pity those cowards, or fear them?!","They no longer have a warrior's heart; no need to grieve."]},{"id":82218,"giver":"放债者","to":"放债者","type":"kill","target":"☆潦倒的战士","count":10,"sc":"下城区贫民窟","rw":{"gold":102,"items":[["30126",1]]},"lv":37,"tr":["Tefecinin İddiası","Bütün gün boş boş mu geziyorsun? Benim de bu aralar işim yok… Bir iddiaya girelim mi? Kenar mahallede çok güçlü bir grup ☆Düşkün Savaşçı varmış; onları yenebilir misin? Kazanırsan bu kese altın senin!","Kabul","İddianın süresi sınırlı ama…","Oo… iyi iş. Sana başka işler de verebilirim belki…"],"en":["The Moneylender's Bet","Do you just loaf around all day? I've got no business lately either… How about a bet? I hear there's a very strong group of ☆Fallen Warriors in the slums; can you beat them? If you win, this bag of gold is yours!","Accept","The bet has a time limit, you know…","Oh… nicely done. Maybe I'll hire you for other jobs…"]},{"id":82219,"giver":"妖术师","to":"妖术师","type":"kill","target":"望日城士兵","count":20,"sc":"下城区贫民窟","rw":{"gold":95,"items":[]},"lv":37,"tr":["Ele Geçirilmiş Askerler","Askerlerimiz kötü bir büyünün kontrolüne girdi; şimdi bize karşı dönüyorlar. Çare yok; ruhları esir, bedenleri ihanet etti. Umarım ruhları ölümsüz olur; git, bedenlerini yen!","Kabul","Gitmeye korkuyor musun?","Ruhları ölümsüz olsun."],"en":["Controlled Soldiers","Our soldiers have fallen under evil magic and now turn against us. There's no help for it; their minds are enslaved, their bodies have betrayed us. May their spirits endure; go and defeat their bodies!","Accept","Afraid to go?","May their souls endure."]},{"id":82220,"giver":"宝石加工者工会代表","to":"宝石加工者工会代表","type":"collect","target":"望日城士兵","count":10,"sc":"下城区贫民窟","chance":0.5,"rw":{"gold":105,"items":[["30126",1]]},"lv":37,"tr":["Akik Taşları","Hırsız! Hırsız! Kenar mahallede hırsızlar türedi, bütün akik taşlarımı çaldılar! Güneşgören Şehri'nde böyle cüretkâr hırsızlar mı! Böyle kural tanımazlık olmaz!","Kabul","Taşlarımı geri getir!","Aşağılık elfler, gerçekten aşağılık.","Akik Taşı"],"en":["Agate Gems","Thief! Thief! Thieves have appeared in the slums and stolen all my agate gems! Such bold thieves in Sunwatch City! Such lawlessness won't do!","Accept","Bring back my gems!","Lowly elves, truly lowly.","Agate Gem"]},{"id":82221,"giver":"艺术家工会代表","to":"艺术家工会代表","type":"kill","target":"☆狂信武士","count":20,"sc":"传送回廊","rw":{"gold":130,"items":[]},"lv":10,"tr":["Savaşçının Sanatı","Bu sanattan anlamayan elf değil mi? Şimdi başka bir sınava gir, beni küçümsetme. Tarikat Üssü'ndeki ☆Fanatik Savaşçılar tarikatçı olsalar da çok usta dövüşçüler; onları yenersen gücünü kabul ederim.","Kabul","Sanattan anlar mısın?","Gerçekten iyi bir savaşçıymışsın."],"en":["The Warrior's Art","Isn't this the elf who doesn't understand art? Take another test now, and don't make me look down on you. The ☆Fanatic Warriors in the Cult Base may be cultists, but they're highly skilled fighters; beat them and I'll acknowledge your strength.","Accept","Do you understand art?","You truly are a good warrior."]},{"id":82222,"giver":"艺术家工会代表","to":"首席大法师","type":"talk","req":82221,"rw":{"gold":142,"items":[["30126",1]]},"lv0":29,"tr":["Savaşçı Ruhu","Sana bir sır vereyim: Başbüyücü'nün asıl hayali usta bir savaşçı olmaktı; gece elflerinin savaşçı ruhunu sürdürmek her elfin hayalidir, belki onda hâlâ biraz savaşçı ruhu vardır. Git, seninle düelloya cesareti var mı sor; sen ☆Fanatik Savaşçıları yenmiş birisin.","Kabul","Sana inanıyorum!","Ben mi? Ben bir büyücüyüm…"],"en":["Warrior Spirit","Let me tell you a secret: the Archmage originally dreamed of becoming an outstanding warrior; carrying on the night elves' warrior spirit is every elf's dream, and maybe some remains in him. Go ask if he dares duel you; you're the one who beat the ☆Fanatic Warriors.","Accept","I believe in you!","Me? I'm a mage…"],"lv":30},{"id":82223,"giver":"首席大法师","to":"温妮迪失心先知","type":"talk","rw":{"gold":141,"items":[["10067",1],["10075",1],["10919",1]]},"lv0":29,"tr":["Savaşçılara Saygı Töreni","Öyle bir düşüncem gerçekten vardı ama artık bir büyücüyüm! Kılıç tutamam, kurallara aykırı olur. Aslında savaşçı inancına çok saygı duyarım; savaşçılar için bir anma töreni yönetebilsem ne güzel olur! Git, Aklını Yitirmiş Kâhin Winnidy'ye sor, olur mu.","Kabul","Ben bir büyücüyüm.","Kesinlikle olmaz; bütün Güneşgören Şehri karışır."],"en":["Honoring the Warriors","I did once have such thoughts, but I'm a mage now! I can't hold a sword; it would break the rules. Actually I deeply respect the warrior faith; how nice it would be if I could lead a memorial for warriors! Go ask Winnidy the Lost Prophet if I may.","Accept","I am a mage.","Absolutely not; all of Sunwatch City would be thrown into chaos."],"lv":37},{"id":82224,"giver":"走私者","to":"首席大法师","type":"talk","rw":{"gold":125,"items":[]},"lv0":29,"tr":["Kaçakçının Dileği (1)","Son zamanlarda burada işler kötü; \"oradan\" gelen mallar çok pahalı. Bir tüccar olarak daha çok kazanmak istiyorum! Ufak bir ricam var: Başbüyücüyle aran iyi görünüyor; ona sorar mısın, denize açılıp mal getirmem için bana izin belgesi verir mi?","Kabul","Ona da pay veririm.","İzin belgesi mi? Onun gibisine mi?"],"en":["The Smuggler's Wish (1)","Business here is bad lately; goods from \"over there\" are expensive. As a businessman I want to earn more! I have a small favor to ask: you seem close to the Archmage; could you ask if he'll give me a pass to sail out for goods?","Accept","I'll even give him a share.","A pass? For someone like him?"],"lv":10},{"id":82225,"giver":"首席大法师","to":"走私者","type":"talk","rw":{"gold":53,"items":[["30126",1]]},"lv0":29,"tr":["Kaçakçının Dileği (2)","O mu? Denize açılıp daha çok mı kazanmak istiyor? Zaten Labilia'nın en zengini! Böylesinin tüccar belgesini iptal etmek bile geçiyor içimden!","Kabul","İyi kalpli elf, unutma: herkese yardım edilmez.","Hayır, hayır, tüccar belgemi iptal etmeyin."],"en":["The Smuggler's Wish (2)","Him? Sailing out to earn even more? He's already the richest man in Labilia! I'm half tempted to revoke his merchant license!","Accept","Kind elf, remember: not everyone deserves help.","No, no, please don't revoke my merchant license."],"lv":37},{"id":82226,"giver":"驭兽者工会代表","to":"驭兽者工会代表","type":"collect","target":"杂种狗","count":10,"sc":"下城区贫民窟","chance":0.5,"rw":{"gold":119,"items":[["30126",1]]},"lv":37,"tr":["Sokak Köpeği Tüyü","Bir diş kolye yapıyorum, yardım eder misin? Takınca kesin çok havalı olacağım! Şimdi Aşağı Şehir Kenar Mahallesi'ndeki sokak köpeklerinden tüy getir, ip yapacağım!","Kabul","En havalı terbiyeci benim.","Hallettin mi?","Sokak Köpeği Tüyü"],"en":["Mongrel Hair","I'm making a tooth necklace; will you help me? I'll definitely look cool wearing it! Now go get hair from the mongrels in the Lower City Slums; I'll make a cord from it!","Accept","I'm the coolest beastmaster.","All done?","Mongrel Hair"]},{"id":82228,"giver":"首席大法师","to":"医生工会代表","type":"talk","rw":{"gold":150,"items":[["30126",1]]},"lv0":29,"tr":["Kuduz","Aşağı Şehir Kenar Mahallesi'nde sessizce bir salgın kaynıyor; oradaki canlılar çıldırmış gibi. Eminim o sokak köpekleri iğrenç hastalıklarını yayıyor! Öz toplamamızı çok etkiliyor; Hekimler Loncası Temsilcisi'ne sor, hastalığın yayılmasını nasıl durdurabiliriz.","Kabul","Kuduz daha fazla yayılmamalı.","Güneşgören Şehri adına teşekkür ederim."],"en":["Rabies","A disease is quietly brewing in the Lower City Slums; the creatures there seem to be going mad. I'm sure those mongrels are spreading their vile disease! It's badly affecting our essence gathering; ask the Healers' Guild Representative how we can stop it spreading.","Accept","Rabies must not spread further.","On behalf of Sunwatch City, thank you."],"lv":37},{"id":82229,"giver":"医生工会代表","to":"医生工会代表","type":"kill","target":"杂种狗","count":20,"sc":"下城区贫民窟","rw":{"gold":79,"items":[["30126",1]]},"lv":37,"tr":["Yayılmayı Durdur","Sorunu kökünden çözmek için o sokak köpeklerini öldürüp hastalığın yayılmasını durdurmalıyız; zaten hastalanmış canlılar için de seçerek tedavi yapacağız…","Kabul","Hemen git, o sokak köpeklerini öldür; hastalığı daha fazla yaymasınlar.","Güneşgören Şehri adına teşekkür ederim."],"en":["Stop the Spread","To solve this at the root we must kill those mongrels and stop the disease spreading; for the already sick, we'll have to treat selectively…","Accept","Hurry and kill those mongrels; don't let them spread the disease further.","On behalf of Sunwatch City, thank you."]},{"id":82230,"giver":"医生工会代表","to":"医生工会代表","type":"collect","target":"凶恶蝙蝠","count":10,"sc":"传送回廊","chance":0.5,"req":82229,"rw":{"gold":158,"items":[]},"lv":10,"tr":["Kuduz Aşısı","Hastalığın kaynağı belli oldu; şimdi kalanları tedavi etmeliyiz. Bu korkunç kuduz artık sıradan aşıyla iyileşmiyor; zehri zehirle yenmeliyiz. Tarikat Üssü'ndeki Vahşi Yarasalardan zehir topla; bir damlasının yüz güçlü elfi öldürdüğü söylenir.","Kabul","Çabuk biraz zehir getir, hastalar bekleyemez.","Tamam, hemen aşıyı hazırlıyorum.","Vahşi Yarasa Zehri"],"en":["Rabies Vaccine","The source of the disease is clear; now we must treat the rest. This terrible rabies can't be cured with ordinary vaccine anymore; we must fight poison with poison. Collect venom from the Vicious Bats in the Cult Base; they say one drop can kill a hundred strong elves.","Accept","Hurry and get some venom; the patients can't wait.","Good, I'll prepare the vaccine right away.","Vicious Bat Venom"]},{"id":82235,"giver":"走私者","to":"走私者","type":"kill","target":"垃圾蠕虫","count":20,"sc":"垃圾场","rw":{"gold":183,"items":[]},"lv":38,"tr":["Pis Çöplük","Ne kadar pis yer, o kadar iyi saklanır hazine. Bir kaçakçı için çöplük doğal bir depodur; loncanın kendini beğenmiş herifleri ayakkabılarını kirletmek için oraya asla gelmez. Ama şimdi orayı canavarlar sardı… Oraya koyduğum şeyleri alamıyorum. Yardım eder misin?","Kabul","Sen de mi pis buluyorsun?","Teşekkürler; ama o iğrenç şeyler çok hızlı ürüyor, yardımına yine ihtiyacım olabilir."],"en":["The Filthy Dump","The dirtier the place, the better it hides treasure. For a smuggler, the dump is a natural warehouse; those smug guild types would never dirty their shoes there. But now it's surrounded by monsters… I can't get my stuff back. Can you help?","Accept","You think they're dirty too?","Thanks; but those disgusting things breed fast, I may need your help again."]},{"id":82236,"giver":"走私者","to":"走私者","type":"kill","target":"☆毒液史莱姆","count":20,"sc":"垃圾场","req":82235,"rw":{"gold":164,"items":[["30126",1]]},"lv":38,"tr":["Zehir Slime","Çöplüğü temizledikten sonra mallarımın bir kısmını aldım. Kalanını almaya gittiğimde korkunç bir slime çıktı; işçimi sardı, bir dakikada geriye sadece kemikleri kaldı!! Neyse ki hızlı koştum… Bana son bir kez daha yardım eder misin? Yemin ederim sana çok çok para vereceğim!","Kabul","Sen bile başa çıkamıyor musun? Aman Tanrım…","Öldü mü? Gerçekten öldü mü? Bu şey huzurumu kaçırdı; gözümü her kapadığımda insan yediği an aklıma geliyor, hiç uyuyamıyorum!"],"en":["Venom Slime","After you cleared the dump, I retrieved part of my goods. When I went for the rest, a horrible slime appeared; it wrapped up my worker and in under a minute only bones were left!! Luckily I ran fast… Could you help me one last time? I swear I'll pay you lots and lots!","Accept","Even you can't handle it? Good heavens…","Is it dead? Really dead? That thing robbed me of peace; every time I close my eyes I see it eating people, I can't sleep at all!"]},{"id":82237,"giver":"驭兽者工会代表","to":"驭兽者工会代表","type":"kill","target":"垃圾蠕虫","count":20,"sc":"垃圾场","rw":{"gold":114,"items":[["30126",1]]},"lv":38,"tr":["Büyülü Hayvan Seçimi: Çöp Solucanı","Her büyülü hayvan canavarlar arasından özenle seçilip evcilleştirilir; her canavar büyülü hayvan olmaya uygun değildir. Çöplükte yeni canavarlar çıkmış; benim yerime bir eleme yapar mısın? Kolayca öldürülebiliyorlarsa onlarla vakit kaybetmeme gerek yok.","Kabul","Pis mi buluyorsun, yoksa korkuyor musun?","Bu kadar çabuk mu döndün? Evcilleştirmeye pek uygun değiller galiba…"],"en":["Selecting Pets: Garbage Worms","Every magic beast is carefully chosen from among monsters and tamed; not every monster is suitable. I hear new monsters have appeared in the dump; would you do a selection for me? If they're easy to kill, I needn't waste time on them.","Accept","Is it the filth, or are you scared?","Back so soon? I guess they're not fit for taming…"]},{"id":82238,"giver":"驭兽者工会代表","to":"驭兽者工会代表","type":"kill","target":"☆毒液史莱姆","count":20,"sc":"垃圾场","req":82237,"rw":{"gold":123,"items":[["30126",1]]},"lv":38,"tr":["Büyülü Hayvan Seçimi: Zehir Slime","Çöplükte zehirli gaz saçan bir slime türedi; zehirli gazlı büyülü hayvan! Ne havalı, kesin çok iyi satar! Silahınla benim için bir eleme yap! Uygunlarsa harika olur.","Kabul","Zehirlenmekten mi korkuyorsun?","Bu kadar çabuk mu döndün? Evcilleştirmeye pek uygun değiller galiba…"],"en":["Selecting Pets: Venom Slime","A slime that gives off poison gas has appeared in the dump; a magic beast with poison gas! So cool, it would definitely sell well! Use your weapon to test them for me! If they're suitable, that would be amazing.","Accept","Afraid of being poisoned?","Back so soon? I guess they're not fit for taming…"]},{"id":82284,"giver":"医生工会代表","to":"搜粮官","type":"talk","rw":{"gold":81,"items":[["30126",1]]},"lv0":29,"tr":["Yiyecek Denetimi","Hasta askerlerin sayısı artıyor; yedikleriyle ilgili gibi. Erzak Subayı ile konuş, yiyeceklerin nereden geldiğini sor; bunda kesin bir sorun var!","Kabul","Benim yiyeceklerimde sorun yoktur herhalde…","Yiyeceklerde kesin bir sorun var."],"en":["Inspect the Food","More and more soldiers are falling ill; it seems related to what they eat. Talk to the Forage Officer and ask where the food comes from; something is definitely wrong!","Accept","My food should be fine, surely…","There's definitely something wrong with the food."],"lv":38},{"id":82285,"giver":"搜粮官","to":"搜粮官","type":"collect","target":"垃圾蠕虫","count":10,"sc":"垃圾场","chance":0.5,"rw":{"gold":103,"items":[["30126",1]]},"lv":38,"tr":["Çöp Yemek","Yiyeceklerimizde sorun olmamalı; hepsi cepheye gönderildi. Yemeklerimizi incelemek istiyorsan yenisini getirmelisin; asıl kaynağımız çöp solucanları! O solucanlar tertemizdir.","Kabul","Askerlerin yemeği çöp solucanlarında!","Gayet… temiz görünüyor…","Çöp Yemek"],"en":["Junk Food","Our food should be fine; it's all been sent to the front. If you want to study it, you'll have to get more; our original source is the garbage worms! Those worms are very clean.","Accept","The soldiers' food is on the garbage worms!","Looks… clean enough…","Junk Food"]},{"id":82287,"giver":"炼金术工会代表","to":"炼金术工会代表","type":"collect","target":"☆毒液史莱姆","count":5,"sc":"垃圾场","chance":0.6,"req":82284,"rw":{"gold":179,"items":[]},"lv":38,"tr":["Koruyucu Madde","Son zamanlarda üzerinde çalıştığım koruyucunun malzemesi çok basit; tuhaf gelecek ama gerçekten etkili! Çöplükteki ☆Zehir Slimelardan bu koruyucuyu getir! Hiç işlem gerekmiyor, doğrudan kullanılabilir!","Kabul","Çok temiz, çok hijyenik.","İşte bunlar; yapış yapış, ne güzel.","Koruyucu Madde"],"en":["Preservative","The preservative I'm researching uses very simple materials; it'll sound strange, but it really works! Get this preservative from the ☆Venom Slimes in the dump! No processing needed; it can be used directly!","Accept","Very clean, very hygienic.","These are the ones; so wonderfully gooey.","Preservative"]},{"id":82290,"giver":"女贵族","to":"宝石加工者工会代表","type":"talk","rw":{"gold":122,"items":[["30126",1]]},"lv0":29,"tr":["Soylu Hanımın Dileği","Labilia'nın en güzel kadını olmak için… sadece güzel yüz yetmez; çiçek yaprakla güzeldir. Mücevherciler Loncası Temsilcisi'ne sor, en kaliteli mücevheri var mı; en en en kalitelisini! Ancak öyle bir mücevher benim gibi bir güzele yakışır.","Kabul","Güzellik de bir suçtur.","Bir arayayım."],"en":["The Noblewoman's Wish","To become the most beautiful woman in Labilia… a pretty face isn't enough; a flower needs its leaves. Ask the Jewelers' Guild Representative if he has the finest gem; the very, very finest! Only such a gem suits a beauty like me.","Accept","Beauty is a crime too.","Let me look."],"lv":33},{"id":82291,"giver":"宝石加工者工会代表","to":"走私者","type":"talk","rw":{"gold":112,"items":[]},"lv0":29,"tr":["Değerli Mücevher","Bende en değerli mücevher kalmamış ama güzel hanımlara hizmet etmeye bayılırım; Kaçakçı'ya sor, onda var mı! Mücevherlerimin çoğunu ondan alırım; bütün Labilia'da böyle değerli bir taş ancak onda olabilir!","Kabul","Kaçakçı'ya sor; bir güzelin isteğini geri çevirmez.","Bir taşı kesin hallederim."],"en":["A Precious Gem","I don't have the most precious gems anymore, but I love serving lovely ladies; ask the Smuggler if he has one! I buy most of my gems from him; in all Labilia, only he might have such a precious stone!","Accept","Ask the Smuggler; he won't refuse a beauty's request.","One gem, I can definitely manage."],"lv":30},{"id":82292,"giver":"走私者","to":"走私者","type":"talk","req":82290,"rw":{"gold":64,"items":[["30126",1]]},"lv0":29,"tr":["Para Dediğin El Kiri","Bende gerçekten öyle bir taş var; kıtadaki karlı dağlardan çıkarıldı. Ama bir hanımı memnun etmenin karşılığı olarak bana da bir zahmet bedeli vermelisin! Önce altınlarını görelim.","Kabul","Kaçakçıyla pazarlık et.","Anlaştık."],"en":["Money Is Fleeting","I do have such a stone; it was dug from the snowy mountains on the mainland. But as payment for pleasing a lady, you'll have to give me a little something for my trouble! Let's see your gold first.","Accept","Bargain with the Smuggler.","Deal."],"lv":10},{"id":82293,"giver":"走私者","to":"女贵族","type":"talk","count":1,"req":82292,"rw":{"gold":56,"items":[["30126",1]]},"lv0":29,"tr":["Dilek Gerçekleşti","Tamam, taşı al! (Kadın elf olmak ne güzel…) diye mırıldanıyor kaçakçı.","Kabul","Hâlâ ne duruyorsun, taşı Soylu Hanım'a götür.","Teşekkürler; artık Labilia'nın en güzel gece elfi olabilirim. Benim için para bile mi harcadın? Ama bence bu senin görevindi.","Karlı Dağ Yüreği"],"en":["Wish Granted","Fine, take the gem! (How nice it is to be a female elf…) the smuggler mutters.","Accept","What are you still doing here? Take the gem to the Noblewoman.","Thank you; now I can be the most beautiful night elf in Labilia. You even spent money on me? Well, I think that was your duty.","Heart of the Snow Mountain"],"lv":10},{"id":82295,"giver":"军士长","to":"军士长","type":"kill","target":"病变尸体","count":20,"sc":"垃圾场","rw":{"gold":135,"items":[["30126",1]]},"lv":38,"tr":["Hastalıklı Cesetler","Durum gergin, hiç asker kalmadı; bu işi sana bırakmak zorundayım! O zaman her gece elfi asker gibi emrime uy! Şimdi çöplüğe git, oradaki hastalıklı cesetleri temizle, bitkilere sağlıklı bir ortam geri ver!","Kabul","Haydi, bitkilerimizi kurtar!","Harika iş!"],"en":["Diseased Corpses","The situation is tense and there are no soldiers left; I must leave this to you! So obey my orders like every night elf soldier! Now go to the dump and clear out the diseased corpses, and give the plants a healthy environment again!","Accept","Go save our plants!","Splendid work!"]},{"id":82296,"giver":"军士长","to":"种植者工会代表","type":"talk","req":82295,"rw":{"gold":81,"items":[]},"lv0":29,"tr":["Kirlenen Bitkiler","Belanın kaynağını yok ettik ama bitkilerimizin çoğu zaten mahvoldu. Ne talihsizlik; dön ve Ekiciler Loncası Temsilcisi'ne söyle, çok üzülecek.","Kabul","Ne talihsiz bir haber.","Ne üzücü bir haber."],"en":["Polluted Plants","We eliminated the source of the trouble, but most of our plants were already ruined. How unfortunate; go back and tell the Growers' Guild Representative; he'll be very sad.","Accept","What unfortunate news.","What sad news."],"lv":38},{"id":82298,"giver":"医生工会代表","to":"医生工会代表","type":"collect","target":"病变尸体","count":10,"sc":"垃圾场","chance":0.5,"rw":{"gold":75,"items":[["30126",1]]},"lv":38,"tr":["Cesetlerin Sırrı (1)","Yürüyen ölüler hep korkunçtur… Tıbbi açıdan davranışları ve iradeleri olmamalı. Git, derilerinden örnek getir de inceleyeyim; ceset yürür mü? Bu gerçekten tartışılmaya değer bir konu.","Kabul","Cesetler bile yürüyor, ne ilginç.","Ne iğrenç görünüyor…","Hastalıklı Deri"],"en":["Secret of the Corpses (1)","The walking dead are always terrifying… Medically, they shouldn't have behavior or will. Go collect their skin so I can analyze it; corpses that walk? That's truly worth investigating.","Accept","Even corpses can walk; how interesting.","Looks so disgusting…","Diseased Skin"]},{"id":82301,"giver":"奴隶商人","to":"侏儒奴隶","type":"talk","rw":{"gold":75,"items":[]},"lv0":29,"tr":["Köle Tüccarının Dileği (1)","Bir zamanlar bazı dostlarımın akrabalarını yanlışlıkla sattım; tatile gelmişlerdi, hep benim suçum. Şimdi kefaretimi ödeyip hepsini kurtaracağım! Bana sıra numaralarını getirir misin? Böylece gizlice kurtarırım!","Kabul","Cüce Köle ile konuş.","Beni mi kurtaracaksın?"],"en":["The Slave Trader's Wish (1)","I once mistakenly sold relatives of some friends of mine; they'd come on holiday, and it's all my fault. Now I'll atone and rescue them all! Can you get me their numbers? Then I can secretly free them!","Accept","Talk to the Gnome Slave.","You'll rescue me?"],"lv":10},{"id":82302,"giver":"侏儒奴隶","to":"矮人奴隶","type":"talk","req":82301,"rw":{"gold":41,"items":[["30126",1]]},"lv0":29,"tr":["Köle Tüccarının Dileği (2)","Beni bu alçağın elinden kurtaracağını mı söylüyorsun? Harika; bir de dağ cücesi bir arkadaşım var, onu da kurtar!","Kabul","Dağ Cücesi Köle ile konuş.","Beni mi kurtaracaksın?"],"en":["The Slave Trader's Wish (2)","You say you can free me from this scoundrel? Wonderful; I also have a dwarf friend, free him too!","Accept","Talk to the Dwarf Slave.","You'll rescue me?"],"lv":33},{"id":82305,"giver":"矮人奴隶","to":"兽人奴隶","type":"talk","req":82302,"rw":{"gold":67,"items":[]},"lv0":29,"tr":["Köle Tüccarının Dileği (3)","Beni bu alçağın elinden kurtaracağını mı söylüyorsun? Harika; bir de ork bir arkadaşım var, onu da kurtar!","Kabul","Ork Köle ile konuş.","Beni mi kurtaracaksın?"],"en":["The Slave Trader's Wish (3)","You say you can free me from this scoundrel? Wonderful; I also have an orc friend, free him too!","Accept","Talk to the Orc Slave.","You'll rescue me?"],"lv":33},{"id":82306,"giver":"兽人奴隶","to":"人类奴隶","type":"talk","req":82305,"rw":{"gold":41,"items":[["30126",1]]},"lv0":29,"tr":["Köle Tüccarının Dileği (4)","Beni bu alçağın elinden kurtaracağını mı söylüyorsun? Harika; bir de insan bir arkadaşım var, onu da kurtar!","Kabul","İnsan Köle ile konuş.","Beni mi kurtaracaksın?"],"en":["The Slave Trader's Wish (4)","You say you can free me from this scoundrel? Wonderful; I also have a human friend, free him too!","Accept","Talk to the Human Slave.","You'll rescue me?"],"lv":33},{"id":82307,"giver":"人类奴隶","to":"奴隶商人","type":"talk","req":82306,"rw":{"gold":50,"items":[["10666",1]]},"lv0":29,"tr":["Hiçbiri Geride Kalmasın","Şimdi hemen dön, Köle Tüccarı'na bildir; kurtarılmayı bekliyoruz.","Kabul","Köle Tüccarı'na bildir.","Hepsini buldun mu? Harika, kefaretimi ödeyeceğim."],"en":["Leave No One Behind","Now hurry back and report to the Slave Trader; we're waiting to be rescued.","Accept","Report to the Slave Trader.","You found them all? Wonderful, I'll make amends."],"lv":35},{"id":82308,"giver":"劫掠队长","to":"劫掠队长","type":"kill","target":"病变尸体","count":20,"sc":"垃圾场","rw":{"gold":77,"items":[]},"lv":38,"tr":["Ceset Ordusu (1)","Vaktinde ortadan kaldıramadığımız bazı cesetler bir yerden yaşam enerjisi almış; iradesiz, düşüncesiz… Bu hastalıklı cesetler sadece bir yığın çürümüş et; bu dünyada var olmaları için hiçbir sebep yok.","Kabul","Hastalıklı cesetler çöplüğü istila etti; bu çöpleri temizle.","İyi iş!"],"en":["Corpse Legion (1)","Some corpses we didn't dispose of in time have somehow gained life energy; no will, no thought… These diseased corpses are just piles of rotten flesh; they have no reason to exist in this world.","Accept","Diseased corpses have overrun the dump; clear out this garbage.","Well done!"]},{"id":82310,"giver":"移民代表","to":"移民代表","type":"collect","target":"病变尸体","count":1,"sc":"垃圾场","chance":1,"rw":{"gold":168,"items":[["30126",1]]},"lv":38,"tr":["Tek Hatıra","Geçenlerde Kenar Mahalle Bodrum 1. Kat'tan geçerken çok çirkin, iğrenç şeylere rastladım: çürük bedenler, sendeleyen adımlar! Neyse ki hızlı koştum, yoksa şimdi ben de onlardan biri olurdum! Ama atadan kalma zümrüt kolyemi orada düşürmüşüm! Geri getirir misin? Mutlaka onlardan birinin üstündedir.","Kabul","Sen de mi korkuyorsun onlardan?","İşte zümrüt kolyem! Ama üstüne yapışan ne bu?","Zümrüt Kolye"],"en":["The Only Keepsake","Recently, passing through Slums Basement 1, I ran into some hideous, disgusting things: rotting bodies, staggering steps! Luckily I ran fast, or I'd be one of them now! But I seem to have dropped my ancestral emerald pendant there! Can you get it back? It must be on one of them.","Accept","Are you afraid of them too?","That's my emerald pendant! But what's stuck to it?","Emerald Pendant"]},{"id":82313,"giver":"战士工会会长","to":"法师工会会长","type":"talk","count":1,"rw":{"gold":119,"items":[]},"lv0":29,"tr":["Önemli Haber: Büyücüler Loncası","Bu iş gerçekten acil ama bütün savaşçılarım insanlarla savaşmak için cephede! Mektubumu al, Büyücüler Loncası Başkanı'yla konuş; onda boşta adam çoktur! Bu kadar basit bir işi bile çözemezse onunla dalga geçmek için bir sebebim olur! Ha ha ha!","Kabul","Mektubu çabuk Büyücüler Loncası Başkanı'na götür, rezil olmasını bekliyorum!","Savaşçılar Loncası Başkanı mı gönderdi? Kesin hayra alamet değil!","Acil Mektup"],"en":["Urgent News: Mage Guild","This is truly urgent, but all my warriors are at the front fighting the humans! Take my letter and talk to the Mage Guild Master; he obviously has plenty of idle people! If he can't even solve such a simple thing, I'll have a reason to laugh at him! Ha ha ha!","Accept","Hurry and take the letter to the Mage Guild Master; I can't wait to see him embarrassed!","From the Warrior Guild Master? Can't be anything good!","Urgent Letter"],"lv":35},{"id":82314,"giver":"法师工会会长","to":"妖术师","type":"talk","rw":{"gold":139,"items":[["30126",1]]},"lv0":29,"tr":["Yeni Büyü","Savaşçılar Loncası Başkanı'nın kötü niyetli olduğunu biliyordum! Biz âlimlere o vahşi yaratıklarla göğüs göğüse dövüşmemizi söylüyor; bu barbarlık büyücülere kesinlikle yasaktır! Benimle mi dalga geçmek istiyor? Bunu bizzat yapmama gerek yok; Kara Büyücü halletsin!","Kabul","Hâlâ burada ne bekliyorsun?","Büyücüler Loncası Başkanı'nın görevi. Hemen uygulanacak!"],"en":["A New Sorcery","I knew the Warrior Guild Master meant no good! He wants us scholars to fight those savage creatures hand to hand; such barbarity is expressly forbidden for mages! He wants to laugh at me? I needn't do this myself; let the Warlock handle it!","Accept","What are you still waiting here for?","A task from the Mage Guild Master. Executing at once!"],"lv":10},{"id":82316,"giver":"武技长","to":"武技长","type":"kill","target":"垃圾蠕虫","count":20,"sc":"垃圾场","rw":{"gold":87,"items":[["30126",1]]},"lv":38,"tr":["Hepsi Ölmeyi Hak Ediyor","Dünyada solucan gibi iğrenç bir canavarın neden olduğunu anlamıyorum, hele ki sivillere kendiliğinden saldırırken… Belki yok etme tanrısı onları unuttu; o zaman biz onun yerine yapalım.","Kabul","Korku sende görünmemeli.","Güzel iş."],"en":["They All Deserve to Die","I don't understand why such a disgusting monster as the worm exists, especially one that attacks civilians unprovoked… Maybe the god of destruction forgot them; then let's do it for him.","Accept","Fear should not show in you.","Well done."]},{"id":82319,"giver":"医生工会代表","to":"沙罗曼蛇烈焰侍女","type":"talk","rw":{"gold":128,"items":[]},"lv0":29,"tr":["Trol Gözü (1)","Zehirli gaza maruz kalmış gözler! Doğrusu… o durumda göz belki de… Başka bir yol düşünmeliyiz; ona bir an önce yeni bir göz takmalıyız… Orman gözü hep sık ve derindir; ormanın doğurduğu trollerin dünyanın en keskin gözleri olmalı. Ama onun iznini almalıyız.","Kabul","Vakit kaybetmeden git, trol gözü nakline razı mı sor.","Trol gözü mü? O aşağılık yaratıkların mı?"],"en":["Troll Eye (1)","Eyes exposed to poison gas! Honestly… in that case the eye might… We must think of another way; give her a new eye as soon as possible… The forest's eye is always dense and deep; the trolls born of the forest must have the sharpest eyes in the world. But we must ask her consent.","Accept","Don't delay; go ask if she agrees to a troll eye transplant.","A troll eye? From those lowly creatures?"],"lv":38},{"id":82327,"giver":"女贵族","to":"炼金术工会代表","type":"talk","rw":{"gold":82,"items":[["30126",1]]},"lv0":29,"tr":["Gençlik İksiri (1)","Sonsuz gençlik veren bir iksir istiyorum; beni bir süreliğine genç tutsa bile olur. Şuradaki yaşlı elf kadın gibi olmak istemiyorum; git, simyacıya sor.","Kabul","Güzelliğim soluyor, hâlâ simyacıya gitmedin mi!","Yine mi Soylu Hanım? Hep tuhaf şeyler istiyor."],"en":["Youth Potion (1)","I want a potion of eternal youth; even keeping me young for a while would do. I don't want to end up like that old elf woman over there; go ask the alchemist.","Accept","My looks are fading; why haven't you gone to the alchemist yet!","The Noblewoman again? She always asks for strange things."],"lv":33},{"id":82330,"giver":"放债者","to":"温妮迪失心先知","type":"talk","rw":{"gold":87,"items":[["30126",1]]},"lv0":29,"tr":["Kayıp Cüzdan","Cüzdanımı kaybettim, bütün senetlerim içindeydi! O fukaralar bir yerde gizlice gülüyordur! Git, Aklını Yitirmiş Kâhin Winnidy'ye sor, cüzdanımın yerini falla bulabilir mi!","Kabul","Cüzdanım! Canım!","Fal bakarım."],"en":["Lost Wallet","I lost my wallet, and all my IOUs were in it! Those paupers must be laughing somewhere! Go ask Winnidy the Lost Prophet if she can divine where my wallet is!","Accept","My wallet! My life!","I can divine it."],"lv":37},{"id":82332,"giver":"艺术家工会代表","to":"走私者","type":"talk","rw":{"gold":203,"items":[["30126",1]]},"lv0":29,"tr":["Kaliteli Yılan Derisi (1)","Yılan olmak istiyorum; soylu bir elf bedenim olsa da yılan derisi bir palto giyersem öbür sanatçılarla tartışırken bu kılık herkesin gözünü açar! Harika fikir değil mi? Sanat adına Kaçakçı'yla konuş, bana bir deste kaliteli yılan derisi getirsin!","Kabul","Kaçakçı'dan kaliteli yılan derisi iste.","Benden yılan derisi mi istiyorsun?"],"en":["Fine Snake Skin (1)","I want to be a snake; though I have a noble elf body, if I wore a snakeskin coat, this outfit would dazzle the other artists in our debates! Isn't that a great idea? Talk to the Smuggler on behalf of art and have him get me a bundle of fine snake skin!","Accept","Ask the Smuggler for fine snake skin.","You want snake skin from me?"],"lv":30},{"id":82490,"giver":"炼金术工会代表","to":"炼金术工会代表","type":"kill","target":"污水怪","count":20,"sc":"污水洞穴","rw":{"gold":154,"items":[]},"lv":45,"tr":["Suyu Arıt (1)","Araştırmama göre Güneşgören Şehri'nin suyu gün geçtikçe kötüleşiyor; yavaş yavaş kararan içme suyu boğazdan geçmiyor… Lağım Mağarası'ndaki lağım canavarlarından şüpheleniyorum; git, onları yok et, bakalım su düzelecek mi.","Kabul","Suyu kirletenin bu lağım canavarları olduğundan eminim.","Güneşgören halkı sana teşekkür ediyor."],"en":["Purify the Water (1)","By my investigation, Sunwatch City's water gets worse by the day; the slowly blackening drinking water is hard to swallow… I suspect the sewage beasts in the Sewage Cave; go destroy them and see if the water improves.","Accept","I'm sure these sewage beasts polluted the water.","The people of Sunwatch thank you."]},{"id":82491,"giver":"炼金术工会代表","to":"炼金术工会代表","type":"kill","target":"☆污水巨魔","count":20,"sc":"污水洞穴","req":82490,"rw":{"gold":84,"items":[["10495",1]]},"lv":45,"tr":["Suyu Arıt (2)","Su biraz düzeldi ama sorun tamamen çözülmedi! Az önce suda trol kılı buldum; kirliliğin asıl kaynağının onlar olduğundan eminim!","Kabul","Suyu kirletenin bu ☆Lağım Trolleri olduğundan eminim.","Su sonunda arındı!"],"en":["Purify the Water (2)","The water improved, but the problem isn't fully solved! Just now I found troll hair in the water; I'm sure they're the real source of the pollution!","Accept","I'm sure these ☆Sewer Trolls polluted the water.","The water is finally purified!"]},{"id":82492,"giver":"刺客工会代表","to":"刺客工会代表","type":"kill","target":"污水怪","count":20,"sc":"污水洞穴","rw":{"gold":103,"items":[["30126",1]]},"lv":45,"tr":["Katile Karşı Katil","Suikastçı karanlıkta süzülüp düşmana ölümcül darbeyi indirir; lağım canavarı da karanlık suyun altında süzülüp avına ölümcül darbeyi indirir! Bazıları onların bizden hızlı olduğunu söylüyor! Sen buradaki en iyi suikastçısın; git, suikastçıların onurunu koru!","Kabul","O çöpler nasıl bizim gibi soylularla kıyaslanabilir?","Ha ha, sana rakip olamayacaklarını biliyordum."],"en":["Killer vs. Killer","Assassins move through darkness to strike the fatal blow; sewage beasts move through dark water to strike their prey! Some say they're faster than us! You're our best assassin; go and defend the assassins' honor!","Accept","How can that garbage compare with nobles like us?","Ha ha, I knew they were no match for you."]},{"id":82493,"giver":"铁匠工会代表","to":"铁匠工会代表","type":"collect","target":"☆污水巨魔","count":5,"sc":"污水洞穴","chance":0.6,"rw":{"gold":86,"items":[["30126",1]]},"lv":45,"tr":["Lağım Topuzu","Çekicim suya değince paslandı! ☆Lağım Trollerinin çekici neden suda paslanmıyor? Kesin çok iyi çekiçlerdir! Git, öldür onları, bana birkaç çekiç getir!","Kabul","☆Lağım Trolü çekici! Belki gerçekten harikadır.","Vay! Gerçekten paslanmıyor!","Paslanmayan Çekiç"],"en":["Sewer Hammer","My hammer rusted when it got wet! Why don't the ☆Sewer Trolls' hammers rust in water? They must be excellent hammers! Go kill them and bring me some!","Accept","A ☆Sewer Troll hammer! Maybe it's truly great.","Wow! It really doesn't rust!","Rustless Hammer"]},{"id":82495,"giver":"医生工会代表","to":"医生工会代表","type":"collect","target":"污水怪","count":5,"sc":"污水洞穴","chance":0.6,"rw":{"gold":119,"items":[["30126",1]]},"lv":45,"tr":["Lağım Kabuğu","Dünyada hastalanmayan canlı olmadığına inanırım; ama araştırmamda, kötü ortamda yaşayan bir canlının hiçbir zehirden etkilenmediğini gördüm! Belki özel bir yapıları var! Git, birkaç lağım canavarı kabuğu getir; belki tıp dünyasında bir mucize yaratırım.","Kabul","Yumuşak bedenlerini kabukları koruyor olmalı.","Bunu iyice incelemeliyim.","Lağım Kabuğu"],"en":["Sewage Shell","I believe no living thing never gets sick; but in my research I found a creature living in a foul environment that's immune to all poisons! Maybe they have a special structure! Go get some sewage beast shells; maybe I'll create a medical miracle.","Accept","Their shells must protect their soft bodies.","I must study this carefully.","Sewage Shell"]},{"id":80095,"giver":"神殿教师","to":"神殿教师","type":"collect","target":"蜘蛛","count":5,"sc":"恶臭平原","chance":0.6,"rw":{"gold":87,"items":[]},"lv":10,"tr":["Çocuklar İçin","Çocuklar \"canavar avlayan yiğit\" oyunu oynayabilsin diye bir canavar kukla yapmak istiyorum. Bana 5 örümcek ağı bulabilir misin? O iplikler ipli kukla için birebir.","Kabul","Çocuklar oynamak için bekliyor.","Bu ipliklerin esnekliği harika.","Yapışkan Örümcek Ağı"],"en":["For the Children","I want to make a monster puppet so the children can play \"heroes slaying monsters\". Could you find me 5 spider webs? That silk is perfect for a marionette.","Accept","The children are waiting to play.","This silk is wonderfully elastic.","Sticky Spider Web"]},{"id":80141,"giver":"神谕先知","to":"夜精灵望气士","type":"talk","req":80488,"rw":{"gold":218,"items":[["30033",5],["30030",5]]},"tr":["Kâbusa Adım","Az önceki kehanette… daha net işaretler gördüm. Kâbus Ovası'nın derinliklerinde gizli bir karanlık güç dolaşıyor. İblis Mabedi'nin mührünü kırabileceklerini sanmıyorum ama bu karanlık enerji çevredeki canavarları etkilemiş olabilir. Kâbus Ovası'ndaki Gözcü Kampı'na git ve gözlem işinden sorumlu Gece Elfi Aura Gözcüsü'nü bul; yardımına ihtiyacı olabilir. Durum acil; \"Mürekkep\"imi bir günlüğüne sana ödünç veriyorum, ne kadar çabuk o kadar iyi!","Kabul","Gözcü Kampı'ndaki Gece Elfi Aura Gözcüsü'nü bul.","Kâhin mi gönderdi? Tam zamanında geldin."],"en":["Into the Nightmare","In the divination just now… I saw clearer omens. A hidden dark force is roaming deep in the Nightmare Plain. I don't think they can break the seal of the Demon Sanctum, but this dark energy may be affecting the monsters around it. Go to the Watcher Camp on the Nightmare Plain and find the Night Elf Aura Watcher in charge of observation; he may need your help. It's urgent; I'll lend you my \"Ink\" for a day, the sooner the better!","Accept","Find the Night Elf Aura Watcher at the Watcher Camp.","The Prophet sent you? You've come just in time."],"lv":24},{"id":80154,"giver":"神谕先知","to":"特派武官","type":"talk","rw":{"gold":84,"items":[]},"req":80155,"tr":["Anahtarın Parçası","Eminim, bu bir geçit anahtarının parçası… Ama öbür parçası kayıp gibi… Belki ataşe bir şey biliyordur; gidip tepkisini yoklasana?","Kabul","Özel Ataşe ile konuş.","Peki."],"en":["The Key Fragment","I'm certain this is part of a portal key… but the other part seems to be missing… Perhaps the attaché knows something; why not go and test his reaction?","Accept","Talk to the Military Attaché.","Very well."],"lv":24},{"id":80488,"giver":"神谕先知","to":"神谕先知","type":"collect","target":"☆吸血黑寡妇","count":10,"sc":"噩梦平原东","chance":0.5,"req":80547,"rw":{"gold":160,"items":[["30126",1]]},"lv":24,"tr":["Ayin Hazırlığı","Ayini tamamlamak için kehanet levhasını yoğuracağım biraz büyülü kile ihtiyacım var… Kâbus Ovası Doğu'daki ☆Kan Emici Karadullardan bana 10 parça büyülü kil getirebilir misin?","Kabul","Bu malzemelere ihtiyacım var, lütfen çabuk topla.","Güzel… Şimdi tek yapmamız gereken levhaya rünleri kazımak…","Büyülü Kil"],"en":["Preparing the Ritual","To complete the ritual I need some magic clay to shape the prophecy tablet… Can you get me 10 pieces of magic clay from the ☆Bloodsucking Black Widows in Nightmare Plain East?","Accept","I need these materials, please gather them quickly.","Good… now we only need to carve the runes into the tablet…","Magic Clay"]},{"id":80541,"giver":"狄亚·先知之手","to":"狄亚·先知之手","type":"collect","target":"蝙蝠","count":5,"sc":"怒焰路口","chance":0.6,"req":80540,"rw":{"gold":182,"items":[["30126",1],["30016",5]]},"lv":19,"tr":["Yarasa Pençesi","Doğrusu zırhımı yeni bir tılsımla süslemek istiyordum; hem güzel hem işe yarar olsun, çünkü gösterişli ama işe yaramaz şeylerden hoşlanmam. Yarasalar yabanın derinliklerinde sürü hâlinde dolaşır ama bazıları sürüden ayrılıp tapınağa yakın Öfkealevi Kavşağı'na düşmüş. Bana biraz yarasa pençesi topla.","Kabul","Sabır; sağlam ve güzel yarasa pençesi bulmak kolay değil.","Güzel, bu pençeler tam uygun…","Yarasa Pençesi"],"en":["Bat Claws","Indeed, I'd like to decorate my armor with a new talisman, both beautiful and practical, for I dislike things that are showy but useless. Bats roam in flocks deep in the wilds, but some have strayed to Furyflame Crossing near the temple. Collect some bat claws for me.","Accept","Patience; whole, beautiful bat claws aren't easy to come by.","Good, these claws are just right…","Bat Claw"]},{"id":80545,"giver":"神殿教师","to":"神殿教师","type":"collect","target":"巨魔","count":8,"sc":"怒焰路口","chance":0.5,"req":80543,"rw":{"gold":112,"items":[["30126",1]]},"lv":19,"tr":["Dezenfektan Araştırması (1)","Öğretmenlik yaparken bir yandan da bilimsel makalemi bitirmeye çalışıyorum; şimdi son deney aşamasında. Leşçil canlıların vücut sıvılarının çürüme zehrine nasıl dayandığını incelemek için iç organlarına ihtiyacım var. Bana 8 trol bağırsağı getir, minnettar olurum.","Kabul","İstediğim şeyi daha görmedim.","Harika, planımın yarısı tamam.","Trol Bağırsağı"],"en":["Disinfectant Research (1)","While teaching I'm also trying to finish my research paper, and it's now at the final experiment stage. I need the innards of scavenging creatures to study how their fluids resist rot toxins. Bring me 8 troll intestines; I'll be grateful.","Accept","I haven't seen what I want yet.","Great, half my plan is done.","Troll Intestine"]},{"id":80546,"giver":"神殿教师","to":"神殿教师","type":"collect","target":"红斑蜘蛛","count":8,"sc":"怒焰路口","chance":0.5,"req":80545,"rw":{"gold":65,"items":[["30126",1]]},"lv":19,"tr":["Dezenfektan Araştırması (2)","Sırada 8 Kızıl Benekli Örümcek midesi var. Onları da toplarsan seni iyi ödüllendiririm.","Kabul","İstediğim şeyi daha görmedim.","Harika, bu yıl makalem kesin loncada kabul görecek.","Örümcek Midesi"],"en":["Disinfectant Research (2)","Next I need 8 Red-Spotted Spider stomachs. If you can gather those too, I'll reward you well.","Accept","I haven't seen what I want yet.","Great, this year my paper will surely be accepted by the guild.","Spider Stomach"]},{"id":80547,"giver":"神殿教师","to":"神谕先知","type":"talk","req":80546,"rw":{"gold":90,"items":[["30126",1],["10017",1],["10106",1],["10902",1]]},"tr":["Tapınağın Dostu","Bize o kadar çok yardım ettin ki hepimiz seni çok seviyoruz; ama yakında yine yola çıkacaksın gibi. Kâhin kehanet iksirini hazırladı, geleceğin gidişatını görmeye çalışacak… Ona git; kılıcına, büyüne ve kararlı adımlarına çok ihtiyacı olacak.","Kabul","Kehanet Kâhini ile konuş.","Her şey hazır, ayini başlatayım…"],"en":["Friend of the Temple","You've helped us so much that we all love you; but it seems you'll soon set out again. The Prophet has prepared the prophecy potion and will try to foresee the future… Go to her; she'll urgently need your blade, your magic and your steady stride.","Accept","Talk to the Oracle Prophet.","Everything is ready; let me begin the ritual…"],"lv":10},{"id":80555,"giver":"神谕先知","to":"神眼队长","type":"kill","target":"梦游傀儡","count":10,"sc":"漫雾低地","req":80154,"rw":{"gold":136,"items":[["30126",1]]},"lv":30,"tr":["Kukla Ordusu","Ataşenin mektubundan başka bilgiler de edindim. Hipnoz altındaki bir tarikat ordusu Sisli Ova'da toplanıyor. Git, onları yok et. Sonra Gözcü Kampı'ndaki İlahi Göz Yüzbaşı'na rapor ver.","Kabul","Kuklalar acı nedir bilmez ama planları da yoktur.","Sırada ipleri çeken efendinin sonu var."],"en":["The Puppet Legion","I also gleaned other intelligence from the attaché's letter. A hypnotized cult army is gathering in the Misty Lowland. Go and destroy them. Then report to the Godeye Captain at the Watcher Camp.","Accept","Puppets feel no pain, but they have no cunning either.","Next, the master pulling the strings will be destroyed."]},{"id":81801,"giver":"神殿教师","to":"神殿教师","type":"collect","target":"狼","count":3,"sc":"迷雾荒野","chance":0.6,"rw":{"gold":81,"items":[["30126",1]]},"lv":13,"tr":["Daha Gerçekçi","Kukla daha korkunç görünsün diye biraz kurt postu lazım; bana getirir misin? Dikkat et, postu zedelemeden onları öldürmek zordur.","Kabul","Çok kaba davranıyorsun, o yüzden sağlam post alamıyorsun.","Şu beneklere bak, ne güzel renk; mutlaka çok korkunç bir canavar kukla yapacağım.","Sağlam Kurt Postu"],"en":["More Lifelike","I need some wolf pelts to make the puppet look scarier; could you get me some? Careful, it's hard to kill them without damaging the fur.","Accept","You're too rough, that's why you can't get whole pelts.","Look at these spots, what lovely colors; I'll surely make a very scary monster puppet.","Intact Wolf Pelt"]},{"id":81966,"giver":"神殿教师","to":"神殿教师","type":"collect","target":"路匪","count":3,"sc":"迷雾荒野","chance":0.6,"rw":{"gold":81,"items":[["30126",1]]},"lv":13,"tr":["Kusursuz Olsun","Kukla neredeyse bitti ama biraz ruhsuz duruyor; birkaç tüy taksam çok güzel olur. Şu yol haydutlarının şapkalarındaki tüyler tam uygun, biraz getir.","Kabul","Tüyler olmadan kukla hiç canlı görünmüyor.","Bitti! Süper korkunç Canavar Kukla Komutanı! Dünyayı fethetmeye geldi! Çocuklar! Haydi onunla savaşın!","Şatafatlı Tüy"],"en":["Striving for Perfection","The puppet is nearly done but still lacks spirit; a few feathers would look lovely. The feathers on those road bandits' hats are just right; bring me some.","Accept","Without feathers the puppet doesn't look lively at all.","Done! The super scary Puppet Monster Commander! He's come to conquer the world! Children! Go and fight him!","Fancy Feather"]},{"id":81967,"giver":"追迹者","to":"追迹者","type":"kill","target":"狼","count":10,"sc":"迷雾荒野","rw":{"gold":107,"items":[["30126",1]]},"lv":13,"tr":["Kurt Avcısı","Acemi bir avcı olarak vahşi hayvanlarla dövüşmeyi denemelisin. Sisli Yaban'ın kurtları senin gibi narin bir elf için iyi bir alıştırma olabilir.","Kabul","Elfler kibirli bir ırktır, bütün canlılardan üstündür!","Hm, bedenin artık bu köpeciklerden güçlü görünüyor."],"en":["Wolf Hunter","As a novice hunter you should try fighting some fierce beasts. The wolves of the Misty Wilds may be good practice for a frail elf like you.","Accept","Elves are a proud race, stronger than all creatures!","Hm, it seems your body is now stronger than these puppies."]},{"id":81968,"giver":"神殿教师","to":"夜精灵男孤儿","type":"talk","rw":{"gold":80,"items":[["30126",1]]},"tr":["Okul Öncesi","Anne babası insanlarla savaşta ölen zavallı bir gece elfi oğlan var; bir gün öçlerini almak için sürekli silah talimi yapıyor. Ne iyi çocuk ama bilgisiz de olmaz! Onu okula gelmeye ikna et!","Kabul","Ne gelecek vadeden bir çocuk.","Hm! Haklısın, hemen geliyorum."],"en":["Preschool","There's a poor night elf boy whose parents died in the war with the humans; he trains with weapons all the time, hoping to avenge them one day. A good boy, but he can't go without learning! Convince him to come to school!","Accept","What a promising child.","Hm! You're right, I'll go right away."],"lv":10},{"id":81969,"giver":"夜精灵男孤儿","to":"夜精灵女孤儿","type":"talk","req":81968,"rw":{"gold":39,"items":[]},"tr":["Oğlan ve Kız","Aslında bir de kız kardeşim var, onu bırakamam… Belki ona benimle okula gelmesini söyleyebilirsin.","Kabul","Kız kardeşim de benimle gelsin.","Ha? Ağabeyim beni de mi çağırıyor? Ama ben çok beceriksizim…"],"en":["Boy and Girl","Actually, I have a little sister; I can't leave her behind… Maybe you could tell her to come to school with me.","Accept","I want my sister to come too.","Huh? My brother wants me to come too? But I'm so clumsy…"],"lv":13},{"id":81970,"giver":"神殿大厨","to":"神殿大厨","type":"collect","target":"狼","count":5,"sc":"迷雾荒野","chance":0.6,"rw":{"gold":157,"items":[["30126",1]]},"lv":13,"tr":["Lezzetli Kurt Eti","Kehanet Kâhini en iyi dostumdur; son zamanlarda keyfi pek yerinde değil gibi. Onu iyileştirmek için bir kurt eti ziyafeti yapacağım; Sisli Yaban'ın kurtlarının eti iyi görünüyor.","Kabul","Tapınak aşçısıyım, bununla gurur duyuyorum.","Taş gibi görünüyor… idare eder artık…","Lezzetli Kurt Eti"],"en":["Tasty Wolf Meat","The Oracle Prophet is my best friend; lately he doesn't seem well. I'll make a wolf meat feast to cure him; the wolves of the Misty Wilds look meaty enough.","Accept","I'm the temple cook and proud of it.","Looks rock hard… it'll have to do…","Tasty Wolf Meat"]},{"id":81971,"giver":"种植者工会志愿者","to":"种植者工会志愿者","type":"collect","target":"路匪","count":5,"sc":"迷雾荒野","chance":0.6,"rw":{"gold":189,"items":[["30126",1]]},"lv":13,"tr":["Yol Kesme","Kâhin Tapınağı'nın yeşillendirme elçisi olarak Güneşgören Şehri'nden güç bela biraz gün batımı çamı tohumu getirttim. Ama Sisli Yaban'ın yol haydutları hepsini silip süpürdü! Bu aşağılık elflere katlanamam! Tohumlarımı onlardan geri al!","Kabul","Kâhin Tapınağı'nı yeşillendireceğim.","Bu aşağılık elfler tohum bile çalıyor!","Arınma Tohumu"],"en":["Highway Robbery","As the Prophet's Temple's greening envoy, I had some sunset pine seeds brought from Sunwatch City with great effort. But the road bandits of the Misty Wilds stole every last one! I can't stand these lowly elves! Get my seeds back from them!","Accept","I will make the Prophet's Temple green.","These lowly elves even steal seeds!","Purifying Seed"]},{"id":81972,"giver":"种植者工会志愿者","to":"神谕先知","type":"talk","count":1,"req":81971,"rw":{"gold":158,"items":[]},"tr":["Eskiyi Yeniyle Değiştir","Haydutlar tohumları kullanılamaz hâle getirmiş. Kehanet Kâhini bir zamanlar bana taze tohum vereceğine söz vermişti. Tohumlarımı al, Kâhin'le konuş; sözünü tutsun.","Kabul","Kâhin Tapınağı'nı yeşillendireceğim.","Bu çürük tohumları bırak, gidebilirsin; hiç gelmemişsin sayarım.","Arınma Tohumu"],"en":["Out with the Old","The bandits ruined the seeds. The Oracle Prophet once promised me some fresh ones. Take my seeds and talk to the Prophet; let him keep his word.","Accept","I will make the Prophet's Temple green.","Leave these rotten seeds and go; I'll pretend you were never here.","Purifying Seed"],"lv":13},{"id":81973,"giver":"夜精灵男孤儿","to":"夜精灵男孤儿","type":"collect","target":"路匪","count":1,"sc":"迷雾荒野","chance":1,"rw":{"gold":72,"items":[["30126",1]]},"lv":13,"tr":["Haydut Nişanı","Öğretmen ödev verdi: \"Cesaretini göster.\" Bana bir yol haydudunun nişanını getirebilir misin? O zaman kesin birinci olurum!","Kabul","Birinci, birinci!","Vay! Nişan gerçekten çok havalı.","Haydut Nişanı"],"en":["Bandit Badge","The teacher gave us homework: \"Show your courage.\" Could you get me a road bandit's badge? Then I'll definitely come first!","Accept","First place, first place!","Wow! The badge is so cool.","Bandit Badge"]},{"id":81974,"giver":"夜精灵男孤儿","to":"神秘商人","type":"talk","req":81973,"rw":{"gold":122,"items":[["30126",1]]},"tr":["Al Gülüm Ver Gülüm","Öğretmen bu nişanı benim aldığıma inanmayabilir… Ama gerçekten çok havalı, atmak yazık! Gizemli Tüccar'a git, bu nadir şeyi ister mi sor; sadece bir milyona satarım de!","Kabul","Zengin oldum, zengin oldum!","Bu çocuk rüya görüyor herhalde…"],"en":["Buy and Sell","The teacher may not believe I got this bandit badge myself… But it's so cool, it'd be a shame to throw it away! Go ask the Mysterious Merchant if he wants this rare treasure; tell him I'll sell it for just one million!","Accept","I'm rich, I'm rich!","This child must be dreaming…"],"lv":13},{"id":81975,"giver":"追迹者","to":"追迹者","type":"kill","target":"路匪","count":10,"sc":"迷雾荒野","rw":{"gold":160,"items":[]},"lv":13,"tr":["Gözümün Önünden Çekil","Tebrikler, artık acemi bir avcısın; herkese bir sürü köpeciği tek başına yenebildiğini gururla söyleyebilirsin! Neyse, konumuza dönelim. Bazı elfler soylu kanlarını hiçe sayıp yol haydudu olmuş! Bütün elflerin yüzünü kara çıkardılar! Solucanlar bile bize gülüyordur. Yaşamayı hak etmiyorlar.","Kabul","Elfler kibirli bir ırktır, bütün canlılardan üstündür!","Güzel, bence sende cevher var."],"en":["Out of My Sight","Congratulations, you're now a novice hunter; you can proudly tell everyone you can beat a pack of puppies alone! Anyway, back to business. Some elves, ignoring their noble blood, have become road bandits! They've shamed all elves! I feel even the worms are laughing at us. They don't deserve to live.","Accept","Elves are a proud race, stronger than all creatures!","Good, I think you have real potential."]},{"id":81976,"giver":"狄亚·先知之手","to":"狄亚·先知之手","type":"kill","target":"饥饿的食腐豺","count":15,"sc":"邪气荒野","rw":{"gold":179,"items":[]},"lv":18,"tr":["Çakalların Sonu","Kâhin Tapınağı halkının oylamasıyla en sevilmeyen tür belirlendi! Aç Leş Çakalları, en sevdiğimiz solucanları katlettiği için listenin başında. Şimdi sonları geldi; git, Aç Leş Çakallarını temizle.","Kabul","Kâhin'in emrini koşulsuz uygula.","Aç Leş Çakallarını menüden çıkarmak gerçekten bir kayıp."],"en":["Doom of the Jackals","By vote of the Prophet's Temple residents, the least liked species has been chosen! The Hungry Carrion Jackals top the list for slaughtering our beloved worms. Now their end has come; go and wipe out the Hungry Carrion Jackals.","Accept","Carry out the Prophet's orders without question.","Removing Hungry Carrion Jackals from the menu really is a loss."]},{"id":81977,"giver":"狄亚·先知之手","to":"神谕先知","type":"talk","req":81976,"rw":{"gold":90,"items":[["30126",1]]},"tr":["Durumu Bildir","Kehanet Kâhini'ne bütün leş çakallarını temizlediğimizi bildir; bir de artık çıtır çakal kulağı yiyemeyeceğimizi söyle…","Kabul","Kâhin'in emrini koşulsuz uygula.","Böyle olacağını bilseydim var gücümle karşı çıkardım."],"en":["Report the Situation","Report to the Oracle Prophet that we've dealt with all the carrion jackals, and tell him there'll be no more crispy jackal ears…","Accept","Carry out the Prophet's orders without question.","Had I known, I would have opposed it with all my might."],"lv":19},{"id":81978,"giver":"神秘商人","to":"神秘商人","type":"collect","target":"饥饿的食腐豺","count":5,"sc":"邪气荒野","chance":0.6,"rw":{"gold":197,"items":[["30126",1]]},"lv":18,"tr":["Leşçi Dişleri","Güneşgören Şehri'nin silah ustası kocaman kurt dişi kolyelere bayılıyormuş! Ama kurtların dişleri çok küçük. Leş çakallarınınki epey büyük; bana birkaç tane getir. Sahtesini gerçeğinden ayırt edilemeyecek kadar yaparsam ikimiz de köşeyi döneriz!","Kabul","İş bitince kesin seni yanıma yardımcı alırım.","Gerçeğinden farksız.","Kocaman Ön Diş"],"en":["Scavenger Teeth","It seems Sunwatch City's weapons master loves huge wolf-tooth necklaces! But wolf teeth are too small. Carrion jackal teeth are pretty big; get me a few. If I can pass the fakes off as real, we'll both be rich!","Accept","When this works out, I'll make you my assistant.","They look just like the real thing.","Big Front Tooth"]},{"id":81979,"giver":"追迹者","to":"追迹者","type":"kill","target":"饥饿的食腐豺","count":10,"sc":"邪气荒野","rw":{"gold":105,"items":[]},"lv":18,"tr":["Çakal Ustası","Çaresiz kalan yaratıklar en korkuncudur; belki küçük bir köpekte bile kötü bir tanrının gücü vardır! Yeni talim hedefi: Uğursuz Yaban'taki Aç Leş Çakalları!","Kabul","Elfler kibirli bir ırktır, bütün canlılardan üstündür!","Görünüşe göre usta bir avcı olacak kabiliyetin var."],"en":["Jackal Master","Cornered creatures are always the most terrifying; maybe even a little dog has the power of an evil god! New training target: the Hungry Carrion Jackals of the Wicked Wilds!","Accept","Elves are a proud race, stronger than all creatures!","It seems you have the makings of an outstanding hunter."]},{"id":81980,"giver":"神殿大厨","to":"神殿大厨","type":"collect","target":"精灵战士","count":1,"sc":"迷雾荒野","chance":1,"rw":{"gold":212,"items":[]},"lv":13,"tr":["Savaşçı Mızrağı","Az önce yine bir grup çocuk benimle alay etti; yaptığım yemeği solucanların bile kusacağını söylediler! Bu, Kâhin Tapınağı'nın baş aşçısına büyük hakaret! Bırakıyorum! Çocuklar bile saygı göstermiyor… Savaş alanında satırla yapamam; Sisli Yaban'taki elf savaşçılarından bana bir mızrak getir! Cepheye destek olmaya gidiyorum!","Kabul","Bana Tapınağın Büyük Mızrakçısı de!","Bu mızrağın eldeki hissi satır kadar iyi değil.","Savaşçı Mızrağı"],"en":["Warrior's Spear","Just now a bunch of kids mocked me again, saying even worms would throw up my cooking! That's a grave insult to the Prophet's Temple's head cook! I quit! Even children don't respect me… A cleaver won't cut it on the battlefield; bring me a spear from the elf warriors in the Misty Wilds! I'm off to support the front!","Accept","Call me the Temple's Great Spearman!","This spear doesn't feel as good in the hand as a cleaver.","Warrior's Spear"]},{"id":81982,"giver":"追迹者","to":"追迹者","type":"kill","target":"精灵战士","count":10,"sc":"迷雾荒野","rw":{"gold":139,"items":[]},"lv":13,"tr":["Tapınağı Koru","Bence en zor görevi sana verebilirim. Tapınağın çevresinde dağınık elflerden oluşan küçük birlikler var; Kâhin Tapınağı'na saldırmak için fırsat kolluyorlar gibi… Tapınağı koru, o elf savaşçılarının işini bitir. Çok dikkatli ol; şimdiye kadarki düşmanlarına benzemezler.","Kabul","Tapınağın güvenliği seninle ilgili.","Sana \"avcı\" dememe izin ver."],"en":["Guard the Temple","I think I can give you the toughest task now. Around the temple there are small squads of stray elves; they seem to be waiting for a chance to attack the Prophet's Temple… Guard the temple and deal with those elf warriors. Be very careful; they're unlike any enemy you've faced.","Accept","The temple's safety is in your hands.","Allow me to call you \"hunter\"."]},{"id":81983,"giver":"夜精灵女孤儿","to":"夜精灵女孤儿","type":"talk","rw":{"gold":30,"items":[["30126",1]]},"tr":["Kızın Dileği","Bir dileğim var… İyi kalpli biri bunu gerçekleştirsin istiyorum; bana yardım eder misin?","Kabul","Dileğini dinle.","Gerçekten yardım edecek misin?"],"en":["The Girl's Wish","I have a wish… I hope a kind person can make it come true; will you help me?","Accept","Listen to her wish.","Will you really help me?"],"lv":10},{"id":81984,"giver":"夜精灵女孤儿","to":"神殿教师","type":"talk","req":81983,"rw":{"gold":95,"items":[]},"tr":["İçini Dökmek","Ben… ben… annemi özledim… Ondan kalan tek bir eşya bile olsa yeterdi… Tapınak Öğretmeni şimdi bana en yakın kişi; annemi çok özledim, ne yapmam gerektiğini ona sorar mısın…","Kabul","Annemi istiyorum…","Annesi bir zamanlar silah arkadaşımdı ama çok talihsizdi… Ölmeden önce bana bir hançer bırakmıştı; kız büyüyünce vermeyi düşünüyordum…"],"en":["A Heart-to-Heart","I… I… miss my mother… Even one keepsake of hers would be enough… The Temple Teacher is the closest person I have now; I miss my mom so much, could you ask him what I should do…","Accept","I want my mom…","Her mother was once my comrade-in-arms, but she was very unfortunate… Before she died she gave me a dagger; I meant to give it to the girl when she grew up…"],"lv":10},{"id":81985,"giver":"神殿教师","to":"夜精灵女孤儿","type":"talk","count":1,"req":81984,"rw":{"gold":72,"items":[]},"tr":["Annenin Yüreği","Hançeri Gece Elfi Öksüz Kız'a götür; belki annesinin ona bıraktığı son hediye budur… Üstünde \"Biricik çocuklarıma\" yazıyor.","Kabul","Gece Elfi Öksüz Kız mutlu olsun…","Anne… anne…","Annenin Hançeri"],"en":["A Mother's Heart","Take the dagger to the Night Elf Orphan Girl; perhaps it's the last gift her mother left her… It's engraved: \"To my precious children.\"","Accept","May the Night Elf Orphan Girl be happy…","Mom… mom…","Mother's Dagger"],"lv":10},{"id":81986,"giver":"会计师工会志愿者","to":"会计师工会志愿者","type":"collect","target":"精灵战士","count":1,"sc":"迷雾荒野","chance":1,"rw":{"gold":160,"items":[["30126",1]]},"lv":13,"tr":["Kayıp Defter","Kâhin Tapınağı'nın bütün alışverişini ben yönetirim. Geçen gün kendini Büyücüler Loncası elçisi diye tanıtan biri defterimi aldı, yüzüme gülerek artık Kâhin Tapınağı'nı yöneteceğini söyledi… Galiba şehir dışındaki elf savaşçıları beni kandırdı…","Kabul","Defterim… Kehanet Kâhini bunu öğrenirse işim biter.","Çok teşekkür ederim, işte bu.","Kayıp Hesap Defteri"],"en":["The Lost Ledger","I manage all the trade of the Prophet's Temple. The other day someone calling himself an envoy of the Mage Guild took my ledger, laughed in my face and said now he could rule the Prophet's Temple… I suspect the elf warriors outside the town tricked me…","Accept","My ledger… if the Oracle Prophet finds out, I'm finished.","Thank you so much, that's the one.","Lost Ledger"]},{"id":81987,"giver":"追迹者","to":"追迹者","type":"collect","target":"蛇","count":3,"sc":"邪气荒野","chance":0.6,"rw":{"gold":131,"items":[["30126",1]]},"lv":18,"tr":["Yılandan Korkan İz Sürücü","Selam, en gözde çırağım. Bir avcı olarak utanıyorum ama zor bir durumdayım… İblis de olsa kaya canavarı da olsa hiç korkmam! Ama o uzun, bacaksız yaratığı görünce içim korkuyla doluyor… Bana birkaç yılan derisi getirmelisin… alışmayı öğrenmem lazım.","Kabul","Yılan derisi… düşündükçe dizlerim titriyor.","İşte bu soğuk, kaygan şeyler.","Yılan Derisi"],"en":["The Snake-Shy Tracker","Hi, my favorite apprentice. As a hunter I'm ashamed, but I'm in trouble… Demons or rock fiends, I fear nothing! But when I see those long, legless creatures, I'm terrified to the core… I need you to bring me some snake skins… I have to get used to them.","Accept","Snake skin… just thinking about it makes my knees weak.","These are the cold, slippery things.","Snake Skin"]},{"id":81988,"giver":"神殿大厨","to":"神殿大厨","type":"collect","target":"蛇","count":3,"sc":"邪气荒野","chance":0.6,"rw":{"gold":171,"items":[]},"lv":18,"tr":["Yılan Eti Yemeği","Mutfağa neden döndüğümü sorarsan… Kâhin Tapınağı halkının bana ihtiyacı olduğunu söylerim. Hem savaş alanı sandığımdan biraz daha korkunçmuş… Döndüm! Herkese muhteşem bir yemek yapacağım; dönerken Uğursuz Yaban'ın yılanlarının etinin lezzetli göründüğünü fark ettim.","Kabul","Yılan eti! Yılan eti!","Bu sefer gerçekten harika malzeme; kesin kusursuz bir yemek yaparım.","Taze Yılan Eti"],"en":["Snake Cuisine","If you ask why I came back to cooking… I'll tell you the people of the Prophet's Temple need me. And the battlefield was a bit scarier than I imagined… I'm back! I'll make everyone an amazing dish; on the way back I noticed the snakes of the Wicked Wilds look tasty.","Accept","Snake meat! Snake meat!","This time the ingredients are truly great; I'll surely make a perfect dish.","Tender Snake Meat"]},{"id":82013,"giver":"种植者工会志愿者","to":"种植者工会志愿者","type":"collect","target":"史莱姆","count":5,"sc":"邪气荒野","chance":0.6,"rw":{"gold":145,"items":[["30126",1]]},"lv":18,"tr":["Slime İlacı","Yeşillendirme görevim hâlâ zorlu; bazı yılanlar bitkilerimi boğup kırıyor. Tek çare ilaç! Bir zehirli sıvı var ki bir sürü engereği öldürebiliyormuş: slime salyası.","Kabul","Bu zehre sahip olsam ne harika olurdu!","Yeşillendirmeye katkın için teşekkürler!","Slime Salyası"],"en":["Slime Pesticide","My greening work is still tough; some snakes strangle and break my plants. Only pesticide will do! There's a potent liquid said to kill a whole nest of snakes: slime saliva.","Accept","If only I had this poison, it would be wonderful!","Thank you for your contribution to the greening!","Slime Saliva"]},{"id":82014,"giver":"狄亚·先知之手","to":"狄亚·先知之手","type":"collect","target":"史莱姆","count":5,"sc":"邪气荒野","chance":0.6,"rw":{"gold":171,"items":[]},"lv":18,"tr":["Yiğit Slime'a Karşı","Slimeların güçsüz olduğunu kim söyledi! Güçsüz görünürler ama üstüne yapışırlarsa ömrünün geri kalanını onunla geçirirsin! Böyle yaratıkları ancak yiğitler yenebilir; yiğit olduğunu kanıtlamak ister misin? Uğursuz Yaban'a git, slimeları öldür ve bana kanıt getir!","Kabul","Slimelar çok tehlikelidir.","Sana saygı duyuyorum, yiğit.","Slime Damarı"],"en":["Hero vs. Slime","Who says slimes are weak! They look weak, but if one latches onto you, you'll be carrying it for the rest of your life! Only heroes can beat such creatures; want to prove you're one? Go to the Wicked Wilds, kill slimes and bring me proof!","Accept","Slimes are very dangerous.","I salute you, hero.","Slime Vein"]},{"id":82015,"giver":"通灵学徒","to":"通灵学徒","type":"collect","target":"精灵战士","count":5,"sc":"迷雾荒野","chance":0.6,"rw":{"gold":70,"items":[["30126",1]]},"lv":13,"tr":["Ruh Çağırma Deneyi (1)","Ruh çağırma, elf atalarından kalma gizli bir sanattır; günümüze ulaşan pek az kısmı kaldı. Elflerin soylu kültürünü yaşatmak için kendimiz araştırmalıyız. Önce soydaşlarımızdan biraz kan lazım.","Kabul","Kan, ruh çağırmanın temel malzemesidir.","Doğru, bu gerçekten elf kanı!","Elf Kanı"],"en":["Spirit Experiment (1)","Spirit binding is a secret art left by our elf ancestors, and little of it survives. To carry on the noble culture of the elves, we must research it ourselves. First we need some blood of our own kind.","Accept","Blood is the basic ingredient of spirit binding.","Right, this is indeed elf blood!","Elf Blood"]},{"id":82016,"giver":"通灵学徒","to":"通灵学徒","type":"collect","target":"蛇","count":3,"sc":"邪气荒野","chance":0.6,"req":82015,"rw":{"gold":74,"items":[["30126",1]]},"lv":18,"tr":["Ruh Çağırma Deneyi (2)","Ruh çağırma, kanı ruhla doldurup cansız nesneleri yönetebilmek için birçok sıvının karışımını gerektirir! Sırada yılan mide asidi var.","Kabul","Ruh çağırmayı başarırsam lonca başkanı olurum!","İkinci adım tamam.","Yılan Mide Asidi"],"en":["Spirit Experiment (2)","Spirit binding needs a mix of many liquids to infuse blood with spirit and command lifeless things! Next is snake stomach acid.","Accept","If I succeed, I'll become guild master!","The second step is done.","Snake Stomach Acid"]},{"id":82017,"giver":"通灵学徒","to":"通灵学徒","type":"collect","target":"饥饿的食腐豺","count":1,"sc":"邪气荒野","chance":1,"req":82016,"rw":{"gold":110,"items":[["30126",1]]},"lv":18,"tr":["Ruh Çağırma Deneyi (3)","Son bir adım kaldı: bir şişe leş çakalı salyası. Bu salya yılan asidini nötrler; sonra karışımı vücuduma sürüp ruh çağırabilirim!","Kabul","Bir tane kaldı; ne kadar heyecanlıyım bilemezsin!","Artık deneyi yapabilirim.","Yapışkan Salya"],"en":["Spirit Experiment (3)","Just one last step: a bottle of carrion jackal saliva. It neutralizes the snake acid, and then I can smear the mixture on myself and bind spirits!","Accept","Only one left; you can't imagine how excited I am!","Now I can run the experiment.","Sticky Saliva"]},{"id":80020,"giver":"兽人警卫队长","to":"皇家骑士特使","type":"talk","rw":{"gold":58,"items":[["30024",1]]},"lv0":17,"tr":["Asıl Suçlu","Onların bir başı var, doğru duydun. Belki bir zamanlar subaymış, kim bilir. Ama şimdi bu kargaşanın kaynağı o; onu ortadan kaldırırsak iş kolaylaşır.","Kabul","Bana bakma; bu sopayla onu döverek öldürmemi mi bekliyorsun?","Başları mı var? Bu iş ilginçleşti."],"en":["The Ringleader","They have a leader, you heard right. Maybe he was once an officer, who knows. But now he is the root of this unrest; take him out and things get simple.","Accept","Don't look at me. Do you expect me to beat him to death with this stick?","A leader? Now this is getting interesting."],"lv":29},{"id":80026,"giver":"奔马城城主","to":"奔马城城主","type":"collect","target":"☆走私者军官","count":1,"sc":"奔马海港","chance":1,"req":80058,"rw":{"gold":68,"items":[["30024",1]]},"lv":25,"tr":["Şehir Beyinin Öfkesi","Belki de bu herifleri fazla şımarttım. Gittikçe azıtıyorlar, ben de aptal yerine konuyorum. Eminim şimdi zayıflığıma gülüyorlardır, lanet olasılar! Git, o subayı gebert ve eşyamı geri getir.","Kabul","Belki de o limanı tamamen ele geçirmem gerek.","Bu şeyin nesi var, kendim çözeceğim.","İlginç Ufak Şey"],"en":["The Lord's Wrath","Perhaps I have been too lenient with these fellows. The bolder they get, the more of a fool I look. I'm sure they are laughing at my weakness right now, curse them! Go, kill that officer and bring my thing back.","Accept","Maybe I should take over that harbor entirely.","I'll figure out what this thing is myself.","Curious Trinket"]},{"id":80054,"giver":"幸运的卡卡","to":"幸运的卡卡","type":"collect","target":"兵痞","count":1,"sc":"阳光草原","chance":1,"rw":{"gold":141,"items":[["30024",1],["30033",10],["30030",10]]},"lv":20,"tr":["Centilmenin İntikamı","İnanabiliyor musun? O başıboş serseri askerler beni, bir centilmeni haraca bağladı! Şu sol gözüme bak; bu morluğu kazara bir yere çarparak edinmediğim belli değil mi? Üstümdeki her şeyi aldılar, Ork kardeşlere hediye edeceğim saç bandı da dahil. Bunun hesabını sormalıyım.","Kabul","Şu lanet göz morluğu nasıl geçecek?","Bir centilmeni soymanın bedeli işte bu.","Saç Bandı"],"en":["A Gentleman's Revenge","Can you imagine? Those wandering soldier thugs extorted me, a gentleman! Look at my left eye; you don't think I got this bruise by bumping into something, do you? They took everything I had, including the hair band I meant to give the Orc siblings. I must have my revenge.","Accept","How do I get rid of this blasted black eye?","That is the price of robbing a gentleman.","Hair Band"]},{"id":80055,"giver":"幸运的卡卡","to":"兽人兄","type":"talk","count":1,"req":80054,"rw":{"gold":76,"items":[["30024",1]]},"lv0":17,"tr":["Kardeş Sevgisi","Şu Ork kardeşleri gördün mü? Aralarındaki bağ insanı gerçekten duygulandırıyor. Peki, saç bandını ağabeye ver; sanırım kız kardeşine vereceği hediye buydu.","Kabul","Benimle konuşarak çok şey öğrenirsin, delikanlı.","Saç bandım! Teşekkürler.","Uğurlu Saç Bandı"],"en":["Sibling Love","Have you seen those Orc siblings? The bond between them is truly touching. Well, give the hair band to the brother; I believe this is the gift he wanted to give his sister.","Accept","Talk to me and you'll learn a lot, young one.","My hair band, thank you.","Lucky Hair Band"],"lv":20},{"id":80056,"giver":"战争铁匠","to":"战争铁匠","type":"collect","target":"☆走私者军官","count":5,"sc":"奔马海港","chance":0.6,"rw":{"gold":73,"items":[["30024",1]]},"lv":25,"tr":["Örnek Lazım","Yüksek rütbeli subaylar hep farklı olduklarını göstermek ister; kılıçları gırtlağını kolayca keser. Bunlardan birkaç örnek elde etmek istiyorum; ancak o zaman beylerin acelesine yetişip kaliteli bir parti mal çıkarabilirim.","Kabul","Şu an dövdüğüm şeylerde hep bir eksik var gibi.","Bu kılıçların farkını sen de fark etmişsindir.","Subay Kılıcı"],"en":["I Need Samples","High-ranking officers always like to show they are different; their swords can slit your throat with ease. I would love a few samples, so I can finish a batch of fine goods while those lords keep rushing me.","Accept","Something always seems to be missing from what I forge.","You must have noticed what makes these swords different."]},{"id":80057,"giver":"皇家骑士特使","to":"皇家骑士特使","type":"kill","target":"逃兵队长","count":5,"sc":"阳光草原","req":80020,"rw":{"gold":116,"items":[["30024",1]]},"lv":20,"tr":["Önce Başı Ez","Bu firariler sadece birer kiralık kabadayı. Elebaşlarını öldürürsek beyinsiz kalan kabadayıların icabına bakmak kolay olur.","Kabul","Bir kez karar verdin mi kararlılıkla uygulamalısın.","Gerisini temizlemek artık an meselesi."],"en":["Strike the Head","These deserters are just hired muscle. Kill their leaders, and muscle without a brain is easy to deal with.","Accept","Once you make a decision, carry it out without hesitation.","Mopping up the rest is only a matter of time."]},{"id":80058,"giver":"侏儒商队首领","to":"奔马城城主","type":"talk","rw":{"gold":117,"items":[["30024",1]]},"lv0":17,"tr":["İlginç Ufak Şey","Şehir Beyi son zamanlarda her türlü ilginç ufak şeyi topluyor. Bunu bulmak için çok uğraştım ama yolda bir kaçakçı subayı elimden kaptı. Sanırım bunu Şehir Beyi'ne sen söylemelisin.","Kabul","Eşyayı zorla geri almaya cesaretim yok.","Ne! Benim malıma göz dikmeye nasıl cüret ederler!"],"en":["A Curious Trinket","The Lord has lately been collecting all sorts of curious trinkets. I worked hard to find this one, but a smuggler officer snatched it on the road. I think you should tell the Lord.","Accept","I wouldn't dare take it back by force.","What! They dare lay hands on my things!"],"lv":23},{"id":80060,"giver":"皇家骑士特使","to":"皇家骑士特使","type":"pickup","node":"叛军的粮草","count":5,"sc":"银鹰城南","req":81734,"rw":{"gold":75,"items":[]},"lv":31,"tr":["Düşmanın Erzağı","Burası düşmanın gerisi, yiyecek hiç yeterli olmuyor… Yakına Gümüşkartal Şehri'nin yeni bir ikmal kolu gelmiş diye duydum. Git, oradan biraz erzak araklayıver!","Kabul","Erzak çalamazsan aç kalırsın.","Güzel! Bakıyorum da… karnın epey doymuş.","Erzak"],"en":["Eat the Enemy's Grain","We are behind enemy lines here, and food is never enough… I hear a new Silver Eagle supply train has arrived nearby. Go and steal some provisions!","Accept","If you can't steal any food, you'll go hungry.","Nice! You look… rather well fed.","Provisions"]},{"id":80064,"giver":"皇家骑士特使","to":"易燃的货物","type":"talk","req":80060,"rw":{"gold":91,"items":[]},"lv0":17,"tr":["Ordugâhı Yak","Bak, bu kükürt, bu da gaz yağı… Ne yapmanı istediğimi anladın mı? Git, bu tutuşturucuları düşman çadırlarının etrafına yerleştir… Sonra bir ok yağmuruyla bu gece onları açık havada yatırırız.","Kabul","Yükü düşman çadırlarının yanına bırak.","(Yanıcı yükü çadırların dibine yerleştirdin.)"],"en":["Burn the Camp","Look, this is sulfur, this is lamp oil… Understand what I want? Go and place these around the enemy tents… then a volley of fire arrows will have them sleeping under the moon tonight.","Accept","Place the cargo next to the enemy tents.","(You set the flammable cargo at the foot of the tents.)"],"lv":20},{"id":80066,"giver":"皇家骑士特使","to":"骑士护卫","type":"talk","count":1,"req":80068,"rw":{"gold":79,"items":[["30024",1],["10130",1],["10137",1]]},"lv0":17,"tr":["Bilmemen Gereken Şeyler","Lütfen bu mektubu okumadığını söyle; bazen fazla bilmemek iyidir. Şimdi onu muhafızıma ver, gerisini dert etme. Yine de sana teşekkür borçluyum; en azından onu çöp diye atmadın.","Kabul","Hep beklenmedik şeyler olur.","(Muhafız sana soğukça bakıyor ve tek kelime etmeden mektubu koynuna koyuyor.)","Diga'nın Mektubu"],"en":["Things You Needn't Know","Please tell me you haven't read this letter; sometimes it's better not to know too much. Now hand it to my guard and don't worry about the rest. Still, thank you; at least you didn't throw it away as scrap paper.","Accept","There is always something unexpected.","(The guard looks at you coldly and tucks the letter into his coat without a word.)","Diga's Letter"],"lv":20},{"id":80067,"giver":"城镇公告牌","to":"奔马城城主","type":"collect","target":"☆☆【欺诈者】迪加","count":1,"sc":"奔马海港","chance":1,"rw":{"gold":117,"items":[["30024",1],["30033",10],["30030",10]]},"lv":25,"tr":["Ödül: Kaçakçı Kral","Kaçakçıların asıl lideri \"Dolandırıcı\" Diga tehlikeli bir deli; açgözlü ve kana susamış. Kasabanın güvenliğini ciddi biçimde tehdit ediyor. Kellesini getiren yiğit cömertçe ödüllendirilecek.","Kabul","İstediğimi getirdin mi?","Gözlerine bakılırsa ölümü hiç hazmedememiş.","Diga'nın Kellesi"],"en":["Bounty: The Smuggling Baron","The true leader of the smugglers, \"the Swindler\" Diga, is a dangerous madman, greedy and bloodthirsty. He seriously threatens the town's safety. The hero who brings back his head will be richly rewarded.","Accept","Did you bring what I asked for?","Judging by his eyes, he didn't go willingly.","Diga's Head"]},{"id":80068,"giver":"皇家骑士特使","to":"皇家骑士特使","type":"talk","rw":{"gold":27,"items":[["30024",1]]},"req":80067,"lv0":17,"tr":["Gizli Mektup","(Diga'nın üstünden çıkan mektup. Gizli bir yazışmaya benziyor. Onu Kraliyet Şövalye Elçisi'ne götür.)","Kabul","Mektubu elçiye ver.","Bu mektubu nereden buldun?"],"en":["A Secret Letter","(A letter found on Diga. It looks like a private correspondence. Take it to the Royal Knight Envoy.)","Accept","Give the letter to the envoy.","Where did you find this letter?"],"lv":20},{"id":80091,"giver":"皇家骑士特使","to":"皇家炮队技师","type":"talk","req":80064,"rw":{"gold":57,"items":[["30484",5]]},"lv0":17,"tr":["Karşı Hamle","Düşmanın kanadına bir mancınık hattı kurdum ama geçen günkü çarpışmada bozuldular. Ele geçirdiğin bu parçaları al, oradaki subayın onları onarmasına yardım et!","Kabul","Parçaları topçu ustasına götür.","Tamam!"],"en":["Countermeasure","I set up a line of catapults on the enemy's flank, but they were damaged in battle the other day. Take these parts you captured and help the officer there repair them!","Accept","Take the parts to the artillery engineer.","All right!"],"lv":20},{"id":80092,"giver":"皇家炮队技师","to":"皇家骑士特使","type":"kill","target":"☆战争巨魔","count":10,"sc":"银鹰城东北","req":80091,"rw":{"gold":188,"items":[["30419",5]]},"lv":32,"tr":["Savaş Makinesi","Gümüşkartal büyücüleri korkunç bir yaratık yarattı: ☆Savaş Trolü. Korku ve acı nedir bilmeyen bu zalim yaratık savaş alanına kan ve ölüm saçıyor. Askerlerimin onu görünce altlarına etmesine dayanamıyorum… Git, 10 ☆Savaş Trolü öldür! Acemiler bunların korkulacak bir şey olmadığını görsün!","Kabul","Trollere meydan okuma, fırsatını bulunca boynunu koparırlar.","Trol kafalarını ordugâhın en yüksek yerine astıracağım; moraller düzelsin."],"en":["War Machine","The Silver Eagle mages have created a terrible creature: the ☆War Troll. This merciless beast knows no fear or pain and spreads blood and death on the battlefield. I can't stand seeing my soldiers wet themselves at the sight of one… Go and kill 10 ☆War Trolls! Show the recruits there is nothing to fear!","Accept","Don't taunt the trolls; they'll bite your neck off at the first chance.","I'll have the troll heads hung atop the camp to lift everyone's spirits."]},{"id":80094,"giver":"皇家骑士特使","to":"皇家骑士特使","type":"kill","target":"☆战斗教官","count":10,"sc":"银鹰城西北","req":81739,"rw":{"gold":61,"items":[["30484",5]]},"lv":34,"tr":["İpleri Kes","Askerler kukladır, general kuklayı oynatan eldir; eli kuklaya bağlayan ise iplerdir. Alt ve orta rütbeli subaylar bu ipin en önemli düğümleri. Onları kes; düşman savaşmadan dağılsın.","Kabul","Düşmanın düzenini bozamazsan örgütlü bir orduyla baş etmek çok zordur.","Güzel, asilerin birbirine girdiğini şimdiden görür gibiyim. Karşı saldırı zamanı geldi."],"en":["Cut the Strings","Soldiers are puppets and the general is the hand that moves them; what links the hand to the puppets are the strings. Junior and mid-rank officers are the key knots in those strings. Cut them, and the enemy will fall apart without a fight.","Accept","If you can't disrupt the enemy's plans, an organized army is very hard to beat.","Good, I can already picture the rebels in chaos. Time to strike back."]},{"id":80096,"giver":"皇家骑士特使","to":"皇家骑士特使","type":"collect","target":"☆银鹰信使","count":1,"sc":"银鹰城西北","chance":1,"req":81760,"rw":{"gold":59,"items":[]},"lv":34,"tr":["Pusu","Çabalarımız sayesinde düşman geri çekiliyor. Yine de son günlerde sık sık görünen düşman ulakları aklımı kurcalıyor. Git, herhangi birini öldür; hangi gizli haberleri taşıdıklarını göreyim.","Kabul","Burada oturup boşa harcadığın zamanda bir savaşın kaderi değişirdi.","Hayır, bu mektubun içeriği korkunç… Büyük bir sırra rastladık galiba…","Asi Mektubu"],"en":["Ambush","Thanks to our efforts the enemy is retreating. Still, those enemy couriers that have been so active lately worry me. Go and kill one of them; let me see what secret intelligence they carry.","Accept","The time you waste sitting here could turn the tide of a battle.","No, this letter's contents are terrible… It seems we have uncovered a great secret…","Rebel Letter"]},{"id":80098,"giver":"皇家骑士特使","to":"国王","type":"talk","req":80096,"rw":{"gold":153,"items":[["10097",1],["10110",1],["10926",1]]},"lv0":17,"tr":["Nişan","Önceki savaşlarda çok iyi iş çıkardın. Senden fazla bir şey istemiyorum; krala ve orduya karşı görevini neredeyse eksiksiz yerine getirdin. Savaş sürse de bir ödülü hak ettiğini düşünüyorum: bizzat Kral'ın vereceği bir nişan. Bir de sana… silah arkadaşım demekten onur duyarım.","Kabul","Kral'ın huzuruna çık.","Teşekkür ederim, Majesteleri."],"en":["The Decoration","You did very well in the battles so far. I have little more to ask of you; your duty to the King and the army is all but fulfilled. Though the war goes on, I believe you deserve an honor, granted by the King himself. And allow me the honor of calling you… comrade.","Accept","Go before the King.","Thank you, Your Majesty."],"lv":20},{"id":80266,"giver":"皇家骑士特使","to":"前线斥候","type":"talk","rw":{"gold":149,"items":[["30024",1]]},"lv0":17,"tr":["Cepheden Haber","Çayır Cephesi Başkent'e giden tek yol; ama Gümüşkartal asileriyle savaşımız çok uzun sürdü ve bu yol çok tehlikeli hâle geldi. Cephe Gözcüsü'nü bul ve keşif görevini onunla birlikte tamamla.","Kabul","İmparatorluğun senin gibi yiğitlere ihtiyacı var.","Tam da adama ihtiyacım vardı."],"en":["Report from the Front","The Prairie Front is the only road to the Capital, but our war with the Silver Eagle rebels has dragged on and the road has become very dangerous. Find the Frontline Scout and complete the reconnaissance with him.","Accept","The Empire needs heroes like you.","I was just in need of help."],"lv":20},{"id":80269,"giver":"皇家骑士特使","to":"国王特使","type":"talk","req":80266,"rw":{"gold":90,"items":[["30024",1]]},"lv0":17,"tr":["İzin İste","Orduya nasıl saldıracağını söyleyebilirim ama genel düzeni ilgilendiren bu kararı ben vermem. Anlasan da anlamasan da bu iş için Kralın Elçisi'nden izin almalısın.","Kabul","Dikkat et, kılıksız insanlardan hiç hoşlanmaz.","Bu, bugün duyduğum en iyi haber."],"en":["Ask for Orders","I could command how the army attacks, but a decision that affects the whole campaign isn't mine to make. Whether you understand or not, you must ask the King's Envoy over there.","Accept","Careful, he doesn't like slovenly people.","That is the best news I've heard all day."],"lv":20},{"id":80270,"giver":"国王特使","to":"皇家骑士特使","type":"talk","req":80269,"rw":{"gold":104,"items":[["30024",1]]},"lv0":17,"tr":["Kaçırılmaz Fırsat","Bu kaçırılmaz bir fırsat. Normalde aceleci olan o adamın neden tereddüt ettiğini hiç anlamıyorum. Yaralılar sargılarını sarıp sıcak çorbalarını içip yatana kadar mı bekleyecek? Bu fırsatı kaçırmayın, diyeceğim bu.","Kabul","Bu, asilere ağır bir darbe vurur! En azından ben öyle düşünüyorum.","Bunu bu kadar kararlı söylemesine sevindim."],"en":["A Perfect Opportunity","This is a perfect opportunity. I don't understand why that usually rash fellow hesitates. Does he want to wait until the wounded are bandaged, have had their soup and gone to bed? Don't waste this chance; that's all I have to say.","Accept","This could cripple the rebels! At least, I think so.","I'm glad he said it so decisively."],"lv":20},{"id":80349,"giver":"兽人兄","to":"兽人警卫队长","type":"talk","count":1,"req":80055,"rw":{"gold":34,"items":[["30024",1],["30030",10]]},"lv0":17,"tr":["Orkların Ziyafeti","Ah, iyi kalpli yabancı, bana bir iyilik yapar mısın? Bu ziyafeti Muhafız Komutanı'na götür, şu an hiç ayrılamıyorum.","Kabul","Biz Orklar yemekten anlarız, buna hiç şüphe yok.","Mis gibi kokuyor! Harika!","Berbat Ziyafet"],"en":["An Orc Feast","Oh, kind stranger, could you do me a favor? Take this feast to the Guard Captain; I really can't leave right now.","Accept","We Orcs are connoisseurs of food, no doubt about it.","What a smell! Wonderful!","Awful Feast"],"lv":29},{"id":80350,"giver":"国王特使","to":"皇家骑士特使","type":"talk","rw":{"gold":82,"items":[["30024",1]]},"lv0":17,"tr":["Küstahlık","Savaş alanındaki bu korkaklar bir savaşçının onurunu hiçe sayıyor; Kral buna çok öfkeli. Git, Şövalye Elçisi'ne sor; bu iş ne âlemde?","Kabul","Buraya sadece onlar için gelmedim.","Firariler konusunda bazı ipuçlarım var."],"en":["Sheer Audacity","These battlefield cowards treat a warrior's honor so lightly; the King is furious. Go and ask the Knight Envoy how this matter is being handled.","Accept","I didn't come here just for them.","I already have some leads on the deserters."],"lv":20},{"id":80351,"giver":"皇家骑士特使","to":"兽人警卫队长","type":"talk","req":80350,"rw":{"gold":67,"items":[["30024",1]]},"lv0":17,"tr":["Muhafız Komutanının İpucu","Belli ki bu firarilerin her hareketi planlı. Muhafız Komutanı'nı bul; bu sinsi fareleri benden iyi tanır.","Kabul","Kral yiğit asker topluyor, gidip bakmalısın.","Hmm… Şövalye elçiniz akıllı bir adam."],"en":["The Guard Captain's Lead","Clearly every move these deserters make is planned. Find the Guard Captain; he knows these pesky rats better than I do.","Accept","The King is recruiting heroes; you should go and see.","Hmm… your Knight Envoy is a clever man."],"lv":20},{"id":80417,"giver":"皇家骑士特使","to":"前线斥候","type":"talk","req":80270,"rw":{"gold":55,"items":[["30033",5]]},"lv0":17,"tr":["Emre Uy","Saldırın! Yok edilebilecek her gücü yok edin! Bu asilere verilen cezadır; savaşın merkezinden uzak bu yere gelip rahatça yaralarını saracaklarını sanıyorlarsa çok yanılıyorlar.","Kabul","En küçük gecikme bile savaşın gidişatını değiştirir.","Henüz tehlikenin farkında değiller gibi."],"en":["Follow Orders","Attack! Destroy every force that can be destroyed! This is the rebels' punishment; if they think they can lick their wounds in peace far from the front, they are sorely mistaken.","Accept","Even the slightest delay can change the course of the war.","They don't seem to sense the danger yet."],"lv":20},{"id":80475,"giver":"兽人警卫队长","to":"警卫卡鲁","type":"talk","rw":{"gold":90,"items":[["30033",5]]},"lv0":17,"tr":["Kardeşin İzi","Benim kadar güçlü olan kardeşim, Şehir Beyi'nin tuhaf merakları yüzünden uzun zamandır Trol Ormanı'nda. Orası et kızartmak için hiç iyi bir yer değil. Onu bulmama yardım et, bak bakalım ne durumda.","Kabul","Trol Ormanı yakın değil dostum; yolda açlıktan ölmemek için yanına biraz yiyecek al.","İnsan, burada ne işin var?"],"en":["Brother's Whereabouts","My brother, as strong as I am, has been in the Troll Forest for a long time because of the Lord's strange hobbies. That's no place for a barbecue. Help me find him and see how he's doing.","Accept","The Troll Forest isn't close, friend; you may want to pack some food so you don't starve on the way.","Human, what are you doing here?"],"lv":29},{"id":80477,"giver":"奔马城城主","to":"奔马城城主","type":"kill","target":"受伤的军犬","count":10,"sc":"草原前线","rw":{"gold":65,"items":[["30033",5]]},"lv":29,"tr":["Hayvanları Temizle","Hayvanlardan nefret ederim! O lanet savaş köpekleri çayırıma kadar geldi. Bir gün hiç fark etmeden şehrin ortasında belirsinler istemem. Sahipleri kim olursa olsun, git temizle şunları.","Kabul","Dünyada neden bu kadar tuhaf yaratık var?","Bilmelisin ki ben temizliği seven bir cüceyim."],"en":["Clear Out Those Animals","I hate animals! Those blasted war dogs have reached my prairie. I don't want them showing up in town when I'm not looking. Whoever their masters are, go and clear them out.","Accept","Why are there so many strange creatures in the world?","You should know I am a gnome who likes things clean."]},{"id":80687,"giver":"兽人警卫队长","to":"兽人警卫队长","type":"kill","target":"☆银鹰斥候","count":10,"sc":"草原前线","rw":{"gold":143,"items":[]},"lv":29,"tr":["Tedbir","Bütün düşmanlar içinde en çok gözcülerden nefret ederim, biliyor musun? Seni uzaktan gözlerler; tam bir savaşçı gibi düello etmeye hazırlandığında yılan gibi kayıp giderler. Son günlerde kasabanın çevresinde sık görünüyorlar. Niyetleri ne bilmiyorum ama sana çorba ısmarlamak olmadığı kesin. Onlara bir ders vermenin zamanı geldi.","Kabul","Yüz yüze gelsek tek yumrukta yere sererdim.","Bu sonuç içimi ferahlattı."],"en":["Planning Ahead","Of all enemies I hate scouts the most, you know? They watch you from afar, and when you're ready to duel them like a warrior, they slip away like snakes. Lately they keep appearing around town. I don't know what they're after, but it's certainly not to buy you soup. Time to teach them a lesson.","Accept","Face to face, I'd knock them down with one punch.","That makes me feel much better."]},{"id":81617,"giver":"奔马城城主","to":"奔马城城主","type":"kill","target":"兽人强盗","count":5,"sc":"阳光草原","rw":{"gold":111,"items":[["30024",1]]},"lv":20,"tr":["Patron Cücelerdir","Dostum, şunu anlaman lazım: bu çayırda Orkların hükmü çoktan tarih oldu, artık sözü cüceler söyler. Ama onuru bu kadar önemseyen o herifler haydutluğa düşer, hiç aklıma gelmezdi. Biraz vakit ayırıp onlara patronun kim olduğunu göster!","Kabul","Ne o? Sakın onları yenemediğini söyleme!","Bilesin, ırkçılık yapmıyorum; bu sadece asayişi korumak için gereken bir iş."],"en":["Gnomes Are the Boss","Friend, understand this: Orc rule over this prairie is long gone; now the gnomes call the shots. Still, I never thought those honor-obsessed fellows would sink to banditry. Take some time to show them who's the boss!","Accept","What? Don't tell me you can't beat them!","Mind you, I'm not prejudiced; it's just what keeping the peace requires."]},{"id":81625,"giver":"奔马城城主","to":"皇家骑士特使","type":"talk","req":81617,"rw":{"gold":161,"items":[["30024",1]]},"lv0":17,"tr":["Bitmeyen Dertler","Dağınık haydutlara sert yöntemler işe yarayabilir ama asayişi asıl bozan, insanların firari askerleri. Örgütlü işleri başımı ağrıtıyor. Maymundan türemiş o herifler ne yapıyor umurumda değil, yeter ki burayı tehdit etmesinler. Vaktin varsa git, Şövalye Elçisi'nin ağzını ara. Fazla dolaysız olma, bilirsin onlar böyle şeylerden hoşlanır.","Kabul","Kendi ellerimle pişirdiğim kızartmadan ister misin?","Hmm… seni o ihtiyar mı gönderdi?"],"en":["Endless Troubles","Hard methods might work on scattered bandits, but what truly disturbs the peace are the human deserters. Their organized raids give me headaches. I don't care what those monkey-descended folk are up to, as long as they don't threaten this place. If you have time, go and sound out the Knight Envoy. Don't be too blunt; you know they like it that way.","Accept","Want some roast I cooked myself?","Hmm… that old fellow sent you, didn't he?"],"lv":25},{"id":81633,"giver":"皇家骑士特使","to":"皇家骑士特使","type":"kill","target":"懦弱的逃兵","count":10,"sc":"阳光草原","req":81625,"rw":{"gold":55,"items":[["30024",1]]},"lv":20,"tr":["Hepsini Temizle","Bu korkaklar buraya kaçınca canlarını kurtaracaklarını sanıyor; ne gülünç! Askeri disiplini bozan cezalandırılmalı! Unutma, bu sadece asayiş için değil.","Kabul","Askerin acıma lüksü yoktur.","İyi iş çıkardın; İmparatorluk muhafızlarına katılmaya ne dersin?"],"en":["Leave None Standing","These cowards think fleeing here will save their skins; how laughable! Those who break military discipline must be punished! Remember, this isn't just about keeping the peace.","Accept","A soldier has no room for pity.","Well done. Interested in joining the Imperial Guard?"]},{"id":81634,"giver":"城主秘书","to":"侏儒商队首领","type":"talk","rw":{"gold":46,"items":[["30024",1]]},"lv0":17,"tr":["Güzellik Meraklısı","On gün önce cüce tüccardan çok güzel bir kolye ısmarladım ama hâlâ ses yok. Benim için bir sorar mısın?","Kabul","Sence güzel miyim?","Kolye… gerçekten başımı ağrıtan bir mesele."],"en":["Lover of Beauty","Ten days ago I ordered a beautiful necklace from the gnome merchant, but there's still no word. Could you ask about it for me?","Accept","Do you think I'm pretty?","The necklace… a real headache, that one."],"lv":23},{"id":81652,"giver":"侏儒商队首领","to":"侏儒商队首领","type":"collect","target":"马贼斥候","count":1,"sc":"清风草原","chance":1,"req":81634,"rw":{"gold":79,"items":[["30024",1]]},"lv":23,"tr":["Haydutları Soy","Bu iş yüzünden uzun zamandır başım ağrıyor. Kervanım dönüş yolunda at hırsızlarının gözüne takıldı, iki adamımı kaybettim. Kolyenin şimdi onların elinde olduğunu sanıyorum. Geri alabilir misin? Emeğin boşa gitmez!","Kabul","Hepsi çok uyanık herifler.","Bu kadar becerikli olduğunu hiç tahmin etmemiştim.","Kristal Kolye"],"en":["Rob the Robbers","This has been giving me a headache for ages. My caravan was spotted by horse thieves on the way back and I lost two men. I believe the necklace is in their hands now. Can you get it back? You won't go unrewarded!","Accept","They are all very alert fellows.","I never guessed you had such skills.","Crystal Necklace"]},{"id":81653,"giver":"侏儒商队首领","to":"城主秘书","type":"talk","count":1,"req":81652,"rw":{"gold":48,"items":[]},"lv0":17,"tr":["Güvenilir Tüccar","Şu şeyi sekretere götür; bu yüzden epey zarar ettim. Başıma gelenlere bak; sence biraz ücret iadesi yapmayı düşünmez misin?","Kabul","Lanet at hırsızları!","Ah! Kolyem, ne kadar da güzel.","Kristal Kolye"],"en":["An Honest Merchant","Take this thing to the secretary; I lost a lot because of it. Look at my misfortune; wouldn't you consider giving me back some of the fee?","Accept","Those cursed horse thieves!","Oh! My necklace, it's so beautiful.","Crystal Necklace"],"lv":23},{"id":81654,"giver":"兽人警卫队长","to":"兽人警卫队长","type":"kill","target":"马贼斥候","count":5,"sc":"清风草原","rw":{"gold":84,"items":[]},"lv":23,"tr":["At Hırsızı Belası","Bu at hırsızları çok azıttı! Böyle giderse Koşanat Şehri'nin ticaretteki yeri sarsılır. Şu an yeterince adamım yok; benim için bir iş yapmak ister misin? Ücreti çok iyi.","Kabul","Bu hırsızlar çok tetikte.","Bu da onlara ancak bir uyarı olur."],"en":["Horse Thief Plague","These horse thieves are far too bold! If this goes on, Galloping Horse City's standing in trade will suffer. I'm short on men right now; want to do a job for me? The pay is very good.","Accept","These thieves are very alert.","That's only a warning to them."]},{"id":81655,"giver":"兽人警卫队长","to":"皇家骑士特使","type":"talk","req":81654,"rw":{"gold":95,"items":[]},"lv0":17,"tr":["Yine Firariler","Yine mi firariler?! Lanet alçaklar, neden tek bir yerde durmuyorlar ki hepsini bir ateşte yollayayım. Onlardan bıktım usandım; bu sizin elçinizin halletmesi gereken bir mesele.","Kabul","Şu an tek istediğim biraz et yemek.","Bugün benim için gerçekten berbat bir gün."],"en":["Deserters Again","Deserters again?! Damn scoundrels, why won't they stand in one place so I can send them all off with one fire. I'm sick of them; this is something your envoy should handle.","Accept","Right now all I want is some meat.","Today really is a terrible day for me."],"lv":29},{"id":81656,"giver":"皇家骑士特使","to":"皇家骑士特使","type":"collect","target":"☆逃兵弓箭手","count":10,"sc":"清风草原","chance":0.5,"req":81655,"rw":{"gold":113,"items":[["10047",1],["10065",1],["10906",1]]},"lv":23,"tr":["Silahları Topla","Bazen karanlıkta saklanan katiller daha zor durdurulur. Pekâlâ, sana vereceğim iş için bahane uydurmayacağım: bu çayır mutlak kontrolümüzde olmalı, ne demek istediğimi anlarsın. Görevin kanıtı olarak 10 uzun yay topla.","Kabul","Bazı şeyleri fazla bilmene gerek yok.","Bu silahlar Gümüşkartal hainlerine karşı savaşan yiğitlerin elinde olmalı.","Sağlam Uzun Yay"],"en":["Reclaim the Weapons","Sometimes killers hiding in the dark are harder to stop. Well, I won't make excuses for this job: this prairie must be under our absolute control, you know what I mean. Collect 10 longbows as proof of your work.","Accept","Some things you needn't know too much about.","These weapons belong in the hands of heroes fighting the Silver Eagle traitors.","Sturdy Longbow"]},{"id":81657,"giver":"城主秘书","to":"战争铁匠","type":"talk","rw":{"gold":99,"items":[]},"lv0":17,"tr":["Ağabeyimin İzi","Jack'i tanıyor musun? O benim ağabeyim, çok iyi bir insandır. Ama evden ayrılalı çok oldu; son söylediği, demirciden iyi bir silah alacağıydı. Usta bir kılıççıdır. Gidip benim için sorar mısın?","Kabul","Onu çok özledim.","Ha, Jack mi?"],"en":["My Brother's Whereabouts","Do you know Jack? He's my brother, a very good man. But he left home a long time ago; the last thing he said was that he'd buy a good weapon from the blacksmith. He's a fine swordsman. Could you ask around for me?","Accept","I miss him so much.","Oh, Jack?"],"lv":25},{"id":81658,"giver":"战争铁匠","to":"侏儒商队首领","type":"talk","req":81657,"rw":{"gold":128,"items":[]},"lv0":17,"tr":["İyi Kalpli Jack","Ha, o yardımsever delikanlıyı diyorsun; gerçekten de uzun zamandır görmedim. Belki askere yazılmıştır, kim bilir. Cüce kervanı Başkent'le Koşanat arasında sık gidip gelir; aradığını onlar söyler.","Kabul","Ne zaman savaş çıksa en meşgul adam benim.","\"Firari\" Jack mi? Umarım aynı kişiden bahsetmiyorsundur."],"en":["Good Old Jack","Ah, you mean that helpful lad; come to think of it, I haven't seen him in a long time. Maybe he joined the army, who knows. The gnome caravan often travels between the Capital and Galloping Horse City; they'll tell you what you want to know.","Accept","Whenever there's a war, I'm the busiest man around.","\"Deserter\" Jack? I hope we're not talking about the same man."],"lv":25},{"id":81659,"giver":"侏儒商队首领","to":"奔马城城主","type":"talk","req":81658,"rw":{"gold":200,"items":[["30024",1]]},"lv0":17,"tr":["Firari","Haberleriniz amma da geç geliyor. Jack, İmparatorluğun firarisi; Kral'ın bile bildiği biri. Asilerle karşı karşıya gelinen kritik anda bir okçu bölüğünü alıp kaçtı; ülkesine ihanet etti. Onu bir kez Esinti Çayırı'nda gördüm. Bu haberi Şehir Beyi'ne iletmelisin.","Kabul","Onu yakalamanın ödülü ne kadar biliyor musun?","Jack mi? Kim bu Jack?"],"en":["The Deserter","Your news travels slowly. Jack is a deserter of the Empire, a man even the King knows of. At the critical moment against the rebels, he took a company of archers and left; he betrayed his country. I saw him once on the Breeze Prairie. Perhaps you should tell the Lord.","Accept","Do you know how big the bounty on him is?","Jack? Who is Jack?"],"lv":23},{"id":81660,"giver":"奔马城城主","to":"皇家骑士特使","type":"talk","req":81659,"rw":{"gold":77,"items":[["30024",1]]},"lv0":17,"tr":["İnsanların Meselesi","Kim o? Bir insan mı? İnsanların sorunlarıyla ben ilgilenmem. Bana bakma, yapacak çok işim var; bir onur unvanı bile olmayan biri kimin umurunda? Madem insan meselesi, insanların elçisine git.","Kabul","Dünyada beni mutlu eden çok az şey var.","Firari! Pekâlâ!"],"en":["A Human Problem","Who? A human? I don't handle human problems. Don't look at me, I have plenty to do; who cares about someone without even a title of honor? Since it's a human matter, go to the human envoy.","Accept","Very few things in this world make me happy.","The deserter! Very well!"],"lv":25},{"id":81662,"giver":"皇家骑士特使","to":"城主秘书","type":"talk","req":81660,"rw":{"gold":80,"items":[["30024",1]]},"lv0":17,"tr":["Ardından Gelenler","İyi bir insan her zaman iyi bir asker olmaz; bunu anlaman lazım, delikanlı. Şimdi o üzgün kızın yüzüne bakmak istemiyorum. Nasıl yaparsan yap, bu işi kapat. Yalan da bazen işe yarar.","Kabul","Bu meseleyi bir an önce hallet.","Ah! Zavallı ağabeyim, lanet at hırsızları!"],"en":["Tying Up Loose Ends","A good man isn't always a good soldier; you must understand that, young one. Now, I don't want to face that grieving girl. Whatever way you choose, put an end to this. Sometimes a lie has its uses.","Accept","Deal with this as soon as possible.","Oh! My poor brother, those cursed horse thieves!"],"lv":20},{"id":81663,"giver":"奔马城城主","to":"奔马城城主","type":"collect","target":"草原鹰","count":5,"sc":"清风草原","chance":0.6,"rw":{"gold":129,"items":[["30024",1]]},"lv":23,"tr":["Rengârenk Tüyler","Esinti Çayırı'na gittiysen o çayır kartallarını da görmüşsündür. Aman Tanrım, o güzel tüyleri bir düşün; elbise yapılsa ne güzel olur! Dostum, biraz altın kazanmak istiyorsan fırsatın geldi.","Kabul","Merak etme, bu sefer kesinlikle borcumu ödeyeceğim.","Hey, acele etme; ben hep toptan ödemeye alışkınım.","Rengârenk Tüy"],"en":["Bright Feathers","If you've been to the Breeze Prairie, you've surely seen those prairie eagles. Oh my, think of their beautiful feathers; what a lovely dress they would make! Friend, if you want to earn some gold, here is your chance.","Accept","Don't worry, this time I'll definitely pay up.","Hey, don't rush; I always pay in one go.","Bright Feather"]},{"id":81664,"giver":"奔马城城主","to":"幸运的卡卡","type":"talk","count":1,"req":81663,"rw":{"gold":200,"items":[]},"lv0":17,"tr":["Gizli Hüner","O Kaka denen ihtiyarı neden sevdiğimi biliyor musun? Çünkü her işi bilir; o varken ne aşçıya ne terziye ne eczacıya ihtiyacım var… Biraz daha güçlü olsa şu Ork muhafızlara bile para vermem gerekmezdi; o yeşil derili şişkoların ne kadar çok yediğini bir bilsen! Neyse, bu tüyleri ona ver. Vaktin varsa bir mucizenin doğuşuna kendi gözlerinle tanık olursun.","Kabul","Ah, delikanlı, şimdi paradan bahsetme; görevin daha bitmedi.","Terzilik herkesin harcı değildir.","Bir Deste Tüy"],"en":["A Hidden Talent","Know why I like that old man called Kaka? Because he can do everything; with him I don't need a cook, a tailor or an apothecary… If he were a bit stronger I wouldn't even have to pay those Orc guards; heaven knows how much those green-skinned fatties eat! Anyway, give him these feathers. If you have time, you can witness a miracle being born.","Accept","Oh, young one, don't talk about money now; your task isn't done yet.","Not just anyone can be a tailor.","A Bundle of Feathers"],"lv":25},{"id":81665,"giver":"幸运的卡卡","to":"奔马城城主","type":"talk","count":1,"req":81664,"rw":{"gold":58,"items":[]},"lv0":17,"tr":["Parlak Fikir","Bu epey vaktimi aldı; insanın üstüne attığı bir parça bez elbise sayılmaz. Şehir Beyi bunu kime verecek bilmiyorum ama bunun bir erkeğin giyebileceği bir şey olmadığı ortada.","Kabul","Bir centilmen çok yönlü olmalı.","Aha, bu ihtiyarın beni hayal kırıklığına uğratmayacağını biliyordum.","Tüylü Uzun Etek"],"en":["A Brilliant Idea","This took me quite some time; a rag thrown over one's shoulders isn't a garment. I don't know who the Lord means it for, but it's clearly not something a man could wear.","Accept","A gentleman must be versatile.","Aha, I knew the old man wouldn't let me down.","Feather Gown"],"lv":20},{"id":81666,"giver":"奔马城城主","to":"城主秘书","type":"talk","count":1,"req":81665,"rw":{"gold":89,"items":[["30024",1]]},"lv0":17,"tr":["Cücenin Aşkı","Kabul etmeliyim ki sekreterim çok güzel bir kız; bu elbiseyi giymeye en layık olan o. Nasıl söyleyeceğimi bilmiyorum; ben bir şehir beyiyim, bu konuda acemi görünmek istemem. Benim adıma çalıştığına göre bu işi güzelce bitirmelisin.","Kabul","Yanı başımda bu kadar güzel bir kız varken nasıl fark etmedim? Affedilmez.","Ah… ne güzel bir elbise.","Tüylü Uzun Etek"],"en":["A Gnome in Love","I must admit my secretary is a beautiful girl; she's the one most fit to wear this dress. I don't know how to say it; I'm a lord, and I don't want to look clumsy about this. Since you work for me, you'd better do this job gracefully.","Accept","Such a beautiful girl right beside me and I never noticed. Unforgivable.","Ah… what a beautiful dress.","Feather Gown"],"lv":25},{"id":81667,"giver":"城主秘书","to":"奔马城城主","type":"talk","req":81666,"rw":{"gold":60,"items":[["30024",1]]},"lv0":17,"tr":["Kibar Bir Ret","Şu anki sevincimi kelimelerle anlatamam. Vaktin varsa teşekkürlerimi ona iletir misin? Gerçekten de insanı her an mutlu eden iyi bir ağabey.","Kabul","Bunu giyince eminim çok güzel olacağım.","Ağabey mi? Delikanlı, duymak istediğim cevap bu değildi. İşimi böyle mi görüyorsun… Koca bir öğleden sonramı, beş deste kartal tüyünü harcadın ve bana bu haberi mi getirdin? Pekâlâ, söyleyeyim: benden tek kuruş alamazsın."],"en":["A Gentle Rejection","I can't put my joy into words. If you have time, could you pass on my thanks? He really is a kind big brother who always makes people happy.","Accept","I'm sure I'll look beautiful in it.","Big brother? Young one, that is not the answer I wanted to hear. Is this how you do my work… You wasted my whole afternoon and five bundles of eagle feathers to bring me this news? Well, let me tell you: you won't get a single coin from me."],"lv":25},{"id":81668,"giver":"国王特使","to":"皇家骑士特使","type":"talk","rw":{"gold":132,"items":[]},"lv0":17,"tr":["Kral'ın Niyeti","Buraya çayır manzarasını seyretmeye geldiğimi mi sanıyorsun? Seni siyasetten anlamaz budala! Koşanat Şehri şu an çok önemli; bir ittifak kurmak zorundayız. Şövalye Elçisi'ne söyle, o deli cücenin isteklerini elinden geldiğince karşılasın.","Kabul","Keşke kullanabileceğim birkaç akıllı adam olsaydı.","Majestelerinin niyetini anlıyorum."],"en":["The King's Intent","You think I came here to admire the prairie? You political fool! Galloping Horse City holds a key position right now; we must form an alliance. Tell the Knight Envoy to satisfy that mad gnome's demands as far as possible.","Accept","I wish I had some clever people to work with.","I understand His Majesty's intent."],"lv":20},{"id":81670,"giver":"皇家骑士特使","to":"奔马城城主","type":"talk","req":81668,"rw":{"gold":61,"items":[["30024",1]]},"lv0":17,"tr":["İstekleri Karşıla","Bu \"elinden geldiğince\"nin sınırı ne bilmiyorum ama şunu söyleyeyim: kendini hazırla; o şehir beyinin sana ne yaptıracağını kimse bilemez. Hazırsan git, onunla görüş.","Kabul","Ne karışık zamanlar.","Siz de ilginç bir ırka benziyorsunuz."],"en":["Meet the Demands","I don't know where \"as far as possible\" ends, but I'll tell you this: brace yourself; nobody knows what that lord will make you do. When you're ready, go and see him.","Accept","Such troubled times.","You seem to be an interesting race too."],"lv":20},{"id":81671,"giver":"奔马城城主","to":"奔马城城主","type":"collect","target":"马贼斥候","count":5,"sc":"清风草原","chance":0.6,"rw":{"gold":114,"items":[["30024",1]]},"lv":23,"tr":["At Hırsızlarının Hazinesi","O at hırsızları Esinti Çayırı'nda uzun zamandır terör estiriyor; eminim çok güzel şeyler yağmalamışlardır. Çalıntı mal sahipsiz maldır; fazla düşünme, bana biraz getir.","Kabul","İnsanlar kendi işlerini bile beceremiyor, başka ne yapabilirler bilmem.","Şu göz alıcı mücevherlere bak.","Çalıntı Mal"],"en":["The Horse Thieves' Loot","Those horse thieves have been running wild on the Breeze Prairie for ages; I'm sure they've plundered plenty of good things. Stolen goods have no owner, so don't think too much and get me some.","Accept","Humans can't even handle their own affairs; I wonder what else they can do.","Look at these dazzling gems.","Stolen Goods"]},{"id":81672,"giver":"奔马城城主","to":"奔马城城主","type":"kill","target":"☆逃兵弓箭手","count":10,"sc":"清风草原","rw":{"gold":102,"items":[]},"lv":23,"tr":["Büyük Firari Temizliği","Bu firariler için aslında bir planım yoktu ama iyiliğimden anlamıyorlar gibi; gördüğün gibi kervanıma el uzatmaya cüret ettiler. Onlara biraz gücümü göstermeliyim; cücelere kolay kolay kafa tutulmaz.","Kabul","İnsanlar kendi işlerini bile beceremiyor, başka ne yapabilirler bilmem.","Sanırım bir süre benzer şikâyetler gelmez."],"en":["The Great Deserter Sweep","I had no plans for these deserters, but they don't seem to appreciate my goodwill; as you saw, they dared to attack my caravan. I must show them some force; gnomes are not easily bullied.","Accept","Humans can't even handle their own affairs; I wonder what else they can do.","I don't think there'll be similar complaints for a while."]},{"id":81673,"giver":"奔马城城主","to":"奔马城城主","type":"collect","target":"☆草原漫游者","count":10,"sc":"野马草原","chance":0.5,"rw":{"gold":138,"items":[["30024",1]]},"lv":24,"tr":["Yılan Eti Ziyafeti","Her yerin canlıları kendine özgüdür; sen hiç şunu yedin mi? Ah, saçmaladığım için kusura bakma; demek istediğim, Yabanat Çayırı'ndaki o lezzetli yılan eti. Tatmak istemez misin? Elbette cevabın ne olursa olsun bana biraz getireceksin.","Kabul","İnsanlar kendi işlerini bile beceremiyor, başka ne yapabilirler bilmem.","Bu gerçekten lezzetli yılan eti mi? Beni kandırmıyorsun, değil mi?","Lezzetli Yılan Eti"],"en":["A Snake Meat Feast","Creatures everywhere have their own special traits; have you ever eaten that? Ah, forgive my rambling; I mean the delicious snake meat on the Wild Horse Prairie. Don't you want a taste? Of course, whatever your answer, you'll fetch me some.","Accept","Humans can't even handle their own affairs; I wonder what else they can do.","Is this really the delicious snake meat? You're not fooling me, are you?","Delicious Snake Meat"]},{"id":81674,"giver":"奔马城城主","to":"皇家骑士特使","type":"talk","rw":{"gold":100,"items":[["30024",1]]},"lv0":17,"tr":["Gönlü Hoş","Sen iyi bir insansın; belki de bugün insanların samimiyetini nihayet gördüm. Beni aptal mı sanıyorsun? Elçinizin ne düşündüğünü ayak parmağımla bile bilirim. Ama bunun iyi bir seçim olacağını düşünüyorum; ona fikrimi ilet, senin görevin de bitmiş olur.","Kabul","Karlı dağları görmeyi çok isterim.","Görmek istediğim en iyi sonuç buydu; iyi iş çıkardın, delikanlı."],"en":["Well Satisfied","You're a decent human; maybe today I've finally seen human sincerity. Do you take me for a fool? I could guess what your envoy is thinking with my toes. Still, I think this will be a good choice; pass on my answer to him and your task should be done.","Accept","I'd love to see the snowy mountains.","This is the best outcome I could hope for; well done, young one."],"lv":25},{"id":81675,"giver":"皇家骑士特使","to":"国王特使","type":"talk","req":81674,"rw":{"gold":93,"items":[]},"lv0":17,"tr":["Elçiye Bildir","Siyasi meseleleri fazla sorma. Şehir Beyi tavrını belli ettiğine göre bu haberi doğrudan Kralın Elçisi'ne ilet; belki sana yeni talimatları vardır.","Kabul","Yapacak daha çok iş var.","Harika iş çıkardın."],"en":["Report to the Envoy","Don't ask too much about politics. Since the Lord has made his position clear, take this news straight to the King's Envoy; he may have further orders for you.","Accept","There's still much to do.","You did splendidly."],"lv":20},{"id":81676,"giver":"国王特使","to":"国王","type":"talk","req":81675,"rw":{"gold":64,"items":[["10132",1],["10061",1],["10905",1]]},"lv0":17,"tr":["Dostluk İttifakı","Bu düzenle Gümüşkartal asileri fazla dayanamaz; yaşam alanları daha da daralacak. Teslim olmaları an meselesi. Bu haberi Majestelerine ilet.","Kabul","Burada halletmem gereken başka işler var.","Gümüşkartal asilerinin sonu yaklaştı."],"en":["A Friendly Alliance","With this arrangement the Silver Eagle rebels won't last long; their room to live will shrink further. Their surrender is only a matter of time. Take this news to His Majesty.","Accept","I must stay to handle other matters.","The end of the Silver Eagle rebels is near."],"lv":10},{"id":81677,"giver":"城主秘书","to":"【斥候】布莱恩","type":"talk","rw":{"gold":109,"items":[["30024",1]]},"lv0":17,"tr":["Âşığın Özlemi","Zaman kalbimi kemiriyor; bir süredir aklımdan hep aynı düşünce geçiyor: her şeyi bırakıp Yabanat Çayırı'na, en sevdiğim insanın yanına gitmek. Kabalığımı bağışla ama mümkünse, iyi kalpli yabancı, özlemimi ona iletir misin?","Kabul","Bu işten artık bıktım.","Öhö öhö…"],"en":["A Lover's Longing","Time gnaws at my heart; for a while now one thought keeps coming back: leave everything and go to the Wild Horse Prairie to be with the one I love. Forgive my rudeness, but if you can, kind stranger, would you carry my longing to him?","Accept","I'm tired of this job.","Ahem…"],"lv":10},{"id":81679,"giver":"幸运的卡卡","to":"幸运的卡卡","type":"pickup","node":"蝴蝶草","count":5,"sc":"阳光草原","req":81677,"rw":{"gold":124,"items":[["30024",1]]},"lv":20,"tr":["Doktor Kaka","Tamam tamam, acele ettirme. Güneşli Çayır'da gördüğün o grimsi beyaz otları hatırlarsın. İşte o, kelebek otu; zehre karşı harikadır. Ölmesini istemiyorsan git, biraz topla.","Kabul","Zaman hayattır, delikanlı.","İşte bu, iyi ki yanlış getirmedin.","Kelebek Otu"],"en":["Doctor Kaka","All right, all right, don't rush me. You must remember those grayish-white plants on the Sunny Prairie. That's it, butterfly grass, superb against poison. Go and gather some, unless you want him to die.","Accept","Time is life, young one.","That's the one; good thing you didn't get it wrong.","Butterfly Grass"]},{"id":81680,"giver":"幸运的卡卡","to":"侏儒商队首领","type":"talk","req":81679,"rw":{"gold":127,"items":[["30024",1]]},"lv0":17,"tr":["Tüccar Ruhu","Bir düşüneyim; bir de kristal ayıraç lazım olabilir. Adına aldanma, değerli bir büyü eşyası değil; birçok şeyin yapımında kullanılan basit bir katalizör. Tüccarlarda olmalı; cüce kervanına bak. Ama onlara biraz altın vermen gerekebilir.","Kabul","Benim sana verecek param yok.","Önce altınlarını göster, delikanlı."],"en":["Merchant's Nature","Let me think; I may also need a crystal reagent. Don't be fooled by the name, it's no precious magic item, just a simple catalyst used for many things. Merchants should have it; check the gnome caravan. You may need to give them some gold though.","Accept","I have no money to give you.","Show me your gold first, young one."],"lv":20},{"id":81681,"giver":"侏儒商队首领","to":"幸运的卡卡","type":"talk","count":1,"req":81680,"rw":{"gold":61,"items":[]},"lv0":17,"tr":["Önemli Ayıraç","Bunu bu yıl ilk kez satıyorum. Dostum, nitrik patlayıcı gibi bir şey yapmıyorsun, değil mi? Öyleyse ağzımı sıkı tutmam için biraz daha altın vermelisin.","Kabul","Daha ister misin? Bende çok var.","Acele etmeliyim; umarım o delikanlı dayanabiliyordur.","Kristal Ayıraç"],"en":["An Important Reagent","This is the first one I've sold this year. Friend, you're not making nitrate explosives or something, are you? If so, you'd better pay a bit more gold for me to keep my mouth shut.","Accept","Need more? I have plenty.","I must hurry; I hope that lad can hold on.","Crystal Reagent"],"lv":23},{"id":81685,"giver":"战争铁匠","to":"战争铁匠","type":"collect","target":"☆草原追猎者","count":5,"sc":"野马草原","chance":0.6,"rw":{"gold":92,"items":[["30024",1]]},"lv":24,"tr":["Güçlü Yay","Orklar kadim bir ırktır; pek çok becerileri insanı imrendirir. O iz sürücüleri öldürebiliyorsan, ellerinden birkaç yay al; belki bir şeyler öğrenirim.","Kabul","Bu kolay iş değil.","Dışarıdan bakınca hiç de özel görünmüyor.","Ork Sert Yayı"],"en":["A Strong Bow","Orcs are an ancient race; many of their crafts are enviable. If you can kill those stalkers, take some of their bows; maybe I can learn something from them.","Accept","That won't be easy.","It doesn't look special from the outside.","Orc Longbow"]},{"id":81686,"giver":"战争铁匠","to":"皇家骑士特使","type":"talk","count":1,"req":81685,"rw":{"gold":130,"items":[["30024",1]]},"lv0":17,"tr":["Malı Denet","Kimse yarım günde Ork yayları kadar güçlü bir silah yapamaz; ama Kral'ın çok silaha ihtiyacı var, dikkatle inceleyecek zamanım yok. Bu örneği oradaki Şövalye Elçisi'ne götür, sonuca baksın.","Kabul","Ben şahsen hiç memnun değilim.","Hayal ettiğimden biraz uzak ama yine de çok iyi. Çok sayıda üretebilirsek asilere güçlü bir darbe olur.","Yay Örneği"],"en":["Inspection","Nobody can make a weapon as strong as Orc bows in half a day; but the King needs weapons in great numbers, and I have no time for careful study. Take this sample to the Knight Envoy over there and let him see the result.","Accept","Personally, I'm not satisfied.","It's a bit short of what I imagined, but still very good. If we can mass-produce it, it will be a powerful blow to the rebels.","Bow Sample"],"lv":25},{"id":81687,"giver":"战争铁匠","to":"战争铁匠","type":"kill","target":"港口走私者","count":10,"sc":"奔马海港","rw":{"gold":145,"items":[["30024",1]]},"lv":25,"tr":["İntikam!","O liman artık kaçakçıların mekânı. Lanet olsun, bir zamanlar orada yaşıyordum! Yüzümdeki bu yarayı görüyor musun? Hepsi o kaçakçıların işi! Haydutlar! Karım da onların kılıcıyla can verdi. İntikam almak istiyorum; yardım edersen ödülün cömert olur.","Kabul","Keşke onları kendi ellerimle öldürebilsem.","Bu sonu çoktan beklemeleri gerekirdi."],"en":["Revenge!","That harbor is smuggler territory now. Damn it, I used to live there! See this scar on my face? All the smugglers' doing! Bandits! My wife also died by their swords. I want revenge; help me and you'll be well paid.","Accept","I wish I could kill them myself.","They should have seen this end coming."]},{"id":81688,"giver":"战争铁匠","to":"战争铁匠","type":"collect","target":"☆走私者军官","count":1,"sc":"奔马海港","chance":1,"req":81687,"rw":{"gold":123,"items":[]},"lv":25,"tr":["İntikam!","Ak Güvercin Yüreği… Bir zamanlar aramızdaki aşkın simgesi olan bir kolyeydi; hep takardı. (Yüzünü kapatıp ağlıyor) Onu anabileceğim tek şey o. Haydutlar peşimizdeyken kaybettim; bu kadar güzel bir şey mutlaka başlarına sunulmuştur. Ne olur onu geri getir.","Kabul","O haydutların elinde kalmasına asla izin vermemeliyim.","Güzel gülüşünü yeniden görür gibiyim.","Ak Güvercin Yüreği"],"en":["Revenge!","The Heart of the White Dove… a necklace that once symbolized our love; she always wore it. (He covers his face and weeps.) It's the only thing I have to remember her by. I lost it while the bandits were chasing us; something so beautiful must have been offered to their leaders. Please bring it back.","Accept","I must never let it stay in those bandits' hands.","It's as if I can see her lovely smile again.","Heart of the White Dove"]},{"id":81690,"giver":"奔马城城主","to":"兽人警卫队长","type":"talk","rw":{"gold":112,"items":[["30024",1]]},"lv0":17,"tr":["Korkunç Haydutlar","Ogreler! Bunlar sıradan haydut değil; canını alırlar, geriye cesedin bile kalmaz. Yabanat Çayırı'nda dolaştıklarını duydum. Lanet olsun, burası kasabaya hiç de uzak değil; muhafızlar nerede, bu herifler hiçbir şey yapmıyor mu? Git, onları bul!","Kabul","Adlarını anmak bile insanı titretiyor.","Bu gerçekten kafa yoran bir mesele."],"en":["Terrible Bandits","Ogres! These are no ordinary bandits; they take your life and not even your corpse remains. I hear they roam the Wild Horse Prairie. Damn, that's not far from town; where are the guards, don't those fellows do anything? Go and find them!","Accept","Even hearing their name makes one tremble.","That's truly a troublesome matter."],"lv":25},{"id":81691,"giver":"兽人警卫队长","to":"兽人警卫队长","type":"kill","target":"☆食人魔强盗","count":10,"sc":"野马草原","req":81690,"rw":{"gold":89,"items":[["30024",1]]},"lv":24,"tr":["Ogreleri Temizle","Genç yiğit, bu zorlu bir görev; reddetmekte tamamen haklısın, çünkü sonuçlardan biri onlara yem olmak. Ama belki de iyi bir seçimdir: bu canavarları bile öldürebilirsen seni korkutabilecek ne kalır ki?","Kabul","Doğuştan çok güçlüdürler.","Sonunda rahat bir nefes alabilirim."],"en":["Purge the Ogres","Young hero, this is a hard task; you'd be fully right to refuse, since one possible outcome is ending up as their meal. But perhaps it's a fine choice: if you can kill even these monsters, what could ever frighten you?","Accept","They are born with tremendous strength.","At last I can breathe easy."]},{"id":81692,"giver":"兽人警卫队长","to":"奔马城城主","type":"talk","req":81691,"rw":{"gold":45,"items":[]},"lv0":17,"tr":["Huzur Bozmayın","Daha ne bekliyorsun? Bu müjdeli haberi hemen Şehir Beyi'ne ilet; keyfi yerine gelir, belki bir de ödül alırsın.","Kabul","Bu çayır hep böyle karmakarışık.","Aha, çayırımda böyle canavarlara asla izin vermem."],"en":["Keep the Peace","What are you waiting for? Take this heartening news to the Lord right away; it'll put him in a fine mood, and you may even get a reward.","Accept","This prairie is always such a mess.","Aha, I'll never allow such monsters on my prairie."],"lv":29},{"id":81693,"giver":"皇家骑士特使","to":"皇家骑士特使","type":"kill","target":"港口走私者","count":5,"sc":"奔马海港","rw":{"gold":103,"items":[["30024",1]]},"lv":25,"tr":["Savunmaya Destek","Görünüşe bakılırsa kasabanın savunması pek güçlü değil. Daha çok kâr için kaçakçılar haydutluğa da başlayabilir; aslında şimdiden haydutlar. İnisiyatifi onlara bırakmamalıyız; içlerine korku salmalıyız.","Kabul","Bu kaçakçılar acımasız herifler.","Sapasağlam döneceğini hiç düşünmemiştim."],"en":["Help the Defense","It seems the town's defenses aren't very strong. For greater profit, the smugglers may turn to banditry; in fact, they already are bandits. We mustn't let them take the initiative; we must put fear into them.","Accept","These smugglers are ruthless fellows.","I didn't expect you to come back in one piece."]},{"id":81694,"giver":"皇家骑士特使","to":"皇家骑士特使","type":"kill","target":"☆走私者军官","count":5,"sc":"奔马海港","req":81693,"rw":{"gold":147,"items":[["10054",1],["10070",1],["10908",1]]},"lv":25,"tr":["Kilit Adamlar","Sen de görüyorsundur, hep emir veren birkaç kilit adam var. Tahmin ettiğin gibi, o subaylar onların liderleri; farklı işlere baksalar da sıradan kabadayılardan çok daha üstteler. Bu subayları öldür; geride kalan kabadayılar darmadağın olur.","Kabul","Dikkatli ol, bu subayların kılıç ustalığı fena değil.","Kalıp o şaşkın hâllerini izlemeliydin."],"en":["Key Figures","Surely you can see there are always a few key figures giving orders. As you guessed, those officers are their leaders; though they handle different jobs, they rank far above the common thugs. Kill these officers, and the thugs left behind will scatter like sand.","Accept","Careful, these officers are skilled swordsmen.","You should have stayed to watch their panicked faces."]},{"id":81695,"giver":"侏儒商队首领","to":"侏儒商队首领","type":"collect","target":"☆食人魔强盗","count":10,"sc":"野马草原","chance":0.5,"rw":{"gold":61,"items":[["10659",1]]},"lv":24,"tr":["Kusturun Onları!","Ah! Lanet ogreler! Bütün mallarım gitti; kervanıma saldırmaya cüret ettiler. Zavallı altınlarım, küçük hazinelerimin hepsini yağmaladılar; hepsini kusmaları gerek!","Kabul","Şimdi tam bir fukarayım.","Çok şükür, mallar neredeyse eksiksiz.","Cüce Malı"],"en":["Spit It Out!","Oh! Damned ogres! All my goods are gone; they dared to raid my caravan. My poor gold, all my little treasures plundered; they must spit it all out!","Accept","I'm a pauper now.","Thank goodness, the goods are nearly all here.","Gnome Goods"]},{"id":81696,"giver":"侏儒商队首领","to":"幸运的卡卡","type":"talk","count":1,"req":81695,"rw":{"gold":153,"items":[]},"lv0":17,"tr":["Sahte mi Gerçek mi?","Bak dostum, şu yakuta bak! Bu kadar büyüğünü hiç görmemiştim; ama içimden bir ses sahte diyor, bu kadar şanslı olduğumu hatırlamıyorum. Git, Kaka'ya bunun gerçek olup olmadığını sor.","Kabul","O şanslı ihtiyar bundan fazlasını da bilir.","Farklı bir yakut mu?","Kocaman Yakut"],"en":["Real or Fake?","Look, friend, look at this ruby! I've never seen one so big; but something tells me it's fake, I don't recall being this lucky. Go and ask Kaka whether it's genuine.","Accept","That lucky old man knows more than that.","A different kind of ruby?","Huge Ruby"],"lv":23},{"id":81697,"giver":"幸运的卡卡","to":"侏儒商队首领","type":"talk","count":1,"req":81696,"rw":{"gold":74,"items":[]},"lv0":17,"tr":["Eşsiz Mücevher","Gerçekten nadir bir taş; daha önce bu boyutta olanını hiç görmedim. Şu rengine bak (konuşurken taşı dikkatle evirip çeviriyor); bu gerçek, eminim! Git ona söyle, zengin oldu.","Kabul","Bunu yontan ustaya nereden bulduğunu bizzat sormak isterdim.","Aha! Gerçekmiş; bir hırsız bunu Kral'ın tacından sökmüş olabilir diye bile düşünüyorum.","Kocaman Yakut"],"en":["A Superb Gem","Truly a rare stone; I've never seen one this size before. Look at its color (he turns the gem carefully as he speaks); it's genuine, I'm sure! Go and tell him he's rich.","Accept","I'd love to ask the jeweler who cut it where he got it.","Aha! Genuine; I even suspect some thief pried it off the King's crown.","Huge Ruby"],"lv":20},{"id":81698,"giver":"侏儒商队首领","to":"皇家骑士特使","type":"talk","count":1,"req":81697,"rw":{"gold":70,"items":[["30024",1]]},"lv0":17,"tr":["Sıradan Bir Hediye","Ama bunu satın aldığımı hiç hatırlamıyorum; belki de gerçekten çalıntıdır. Pekâlâ, çok yazık ama başımı belaya sokmak istemem. Hey dostum, bunu sizin elçiye götürüp göstersen iyi olur.","Kabul","Umarım bu sadece benim kuruntumdur.","Bu bana tanıdık geliyor.","Kocaman Yakut"],"en":["An Ordinary Gift","But I don't recall buying this at all; maybe it really is stolen goods. Well, it's a pity, but I don't want trouble. Hey friend, you'd better show this to your envoy.","Accept","I hope it's just my imagination.","This looks familiar."],"lv":23},{"id":81699,"giver":"皇家骑士特使","to":"破烂的包裹","type":"talk","req":81698,"rw":{"gold":41,"items":[["30024",1]]},"lv0":17,"tr":["Şüphe","Bu şey gerçekten çok tanıdık geliyor. Onu bulduğun yere git, iyice bak; belki başka ipuçları bulursun.","Kabul","Bu nadir bir yakut.","(Yırtık bohçanın üstünde altın renkli küçük bir yazı var gibi: Onurlu Kont Andfell)"],"en":["Suspicion","This thing really looks familiar. Go back to where you found it and look carefully; maybe you'll find other clues.","Accept","This is a rare ruby.","(There seems to be a line of small golden letters on the tattered bundle: Honorable Count Andfell)"],"lv":20},{"id":81701,"giver":"皇家骑士特使","to":"皇家骑士特使","type":"pickup","node":"散落的物资包","count":5,"sc":"野马草原","req":81699,"rw":{"gold":115,"items":[]},"lv":24,"tr":["Erzakı Topla","Sanırım bu, Kont Andfell'in ailesinin arma taşı. Ticarete ve altına düşkün o zavallı kont, sonunun bir ogrenin midesi olacağını hiç düşünmemiştir; bu sefer parayla çözememiş. Ne acı bir ironi. Pekâlâ, kontun eşyaları bundan ibaret değildir; çayırda iyice dolaş ve dağılmış ne varsa geri getir.","Kabul","Bence çayırda dağılmış daha çok şey var.","Bunların hepsi değerli şeyler.","Erzak Çantası"],"en":["Recover the Supplies","I believe this is the family crest stone of Count Andfell. That poor count, so fond of trade and gold, never imagined he'd end up in an ogre's belly; this time money couldn't solve his problem. What irony. Well, the count's belongings surely don't end here; roam the prairie and bring back everything scattered about.","Accept","I think there's much more scattered across the prairie.","These are all valuable things.","Supply Pack"]},{"id":81702,"giver":"皇家骑士特使","to":"宰相","type":"talk","req":81701,"rw":{"gold":127,"items":[["10658",1]]},"lv0":17,"tr":["Vekâlet","Böyle karışık bir dönemde ordusu olmayan bir kontun ölümünün bir etkisi olmaz; ama en azından bunu sadece sen ve ben bilmemeliyiz. Benim yerime Başkent'e git ve haberi Vezir'e ilet.","Kabul","Bu iş için kendim gitmek istemem.","Ruhu huzur bulsun."],"en":["Acting on My Behalf","In such turbulent times, the death of a count without an army won't change much; but at least this shouldn't stay between you and me. Go to the Capital on my behalf and tell the Chancellor.","Accept","I'd rather not make this trip myself.","May his soul rest in peace."],"lv":20},{"id":81713,"giver":"兽人医师","to":"兽人医师","type":"talk","rw":{"gold":130,"items":[["30024",1]]},"lv0":17,"tr":["Elimden Geleni Yapacağım","Bir yıl önce Güneşli Orman'da yaban domuzlarının saldırısına uğradım; muhtar öne atılıp beni kurtardı. O benim velinimetim; şimdi hasta, elimden gelen her şeyi yapacağım! Anlattıklarına göre bir düşüneyim, planı nasıl yürüteceğiz.","Kabul","Bir dakika, daha karar vermedim…","Buldum!"],"en":["All Out","A year ago I was attacked by wild boars in the Sunny Forest, and the mayor stepped in and saved me. He's my benefactor; now he's ill, and I'll do everything I can! Based on what you've told me, let me think about how we'll proceed.","Accept","Wait, I haven't decided yet…","I've got it!"],"lv":20},{"id":81714,"giver":"兽人医师","to":"兽人医师","type":"pickup","node":"阳光果","count":3,"sc":"阳光草原","req":81713,"rw":{"gold":192,"items":[["10586",1]]},"lv":20,"tr":["Güneş İksiri","Güneşli Çayır'a git ve biz Orkların en sevdiği güneş meyvesinden topla; bu meyve insana yeni hayat ve cesaret verir. Biraz getir; belki muhtarın tuhaf hastalığını iyileştirir! Ork kahramanları onu korusun!","Kabul","Güneş meyvesinin etkisi seni şaşırtacak!","İşte bu altın sarısı meyveler, tam ihtiyacımız olan.","Güneş Meyvesi"],"en":["Sunshine Potion","Go to the Sunny Prairie and gather sun fruit, the favorite of us Orcs; it brings new life and courage. Bring some; maybe it will cure the mayor's strange illness! May the Orc heroes protect him!","Accept","The sun fruit's power will amaze you!","These golden fruits are exactly what we need.","Sun Fruit"]},{"id":81715,"giver":"兽人医师","to":"兽人医师","type":"collect","target":"兽人强盗","count":1,"sc":"阳光草原","chance":1,"req":81714,"rw":{"gold":118,"items":[["10656",1]]},"lv":20,"tr":["Gümüş Kupa","Az önce bir grup Ork haydut büyülü iksir yaptığım kabı kaptı. Kendi soydaşlarını bile soyuyorlar! Affedilmez; kabım mutlaka birinin üstündedir, hemen geri getir.","Kabul","Bu haydutlar çok alçak! Orkların onurunu ayaklar altına aldılar!","Artık güneş iksirini yapabiliriz!","Gümüş Kupa"],"en":["The Silver Cup","Just now a band of Orc bandits stole the vessel I use for magic potions. They even rob their own kin! Unforgivable. My vessel must be on one of them; hurry and get it back.","Accept","These bandits are despicable! They've lost all Orc dignity!","Now we can make the sunshine potion!","Silver Cup"]},{"id":81716,"giver":"兽人医师","to":"兽人医师","type":"talk","count":1,"req":81715,"rw":{"gold":86,"items":[["30024",1]]},"lv0":17,"tr":["Muhtara Dene","Hazırladığım güneş iksirini al ve Guanlin Kasabası muhtarına kullan; bakalım tuhaf hastalığını iyileştirecek mi.","Kabul","Güneş iksiri güneş meyvesinin özünü emdi, kesin işe yarar!","Etkisi olmadı mı? Bunu hiç beklemiyordum.","Güneş İksiri"],"en":["Try It on the Mayor","Take the sunshine potion I made and use it on the mayor of Guanlin Town; let's see if it cures his strange illness.","Accept","The sunshine potion has absorbed the essence of the sun fruit; it's sure to work!","No effect? I didn't expect that.","Sunshine Potion"],"lv":20},{"id":81717,"giver":"兽人医师","to":"兽人医师","type":"talk","req":81716,"rw":{"gold":53,"items":[]},"lv0":17,"tr":["İşe Yaramadı mı?","Ne? Hiç mi etkisi olmadı? Üstelik muhtar sana bağırdı mı? Demek hastalığı artık hiç beklemeye gelmez! Başka bir tarif düşüneyim, biraz bekle.","Kabul","Bir düşüneyim…","Tamam, artık halkımızın gizli tarifine başvurma zamanı."],"en":["No Effect?","What? No effect at all? And the mayor yelled at you? Then his illness can't wait any longer! Let me think of another recipe; wait a moment.","Accept","Let me think…","Right, now it's time to use our people's secret recipe."],"lv":20},{"id":81718,"giver":"兽人医师","to":"兽人医师","type":"collect","target":"草原鹰","count":4,"sc":"清风草原","chance":0.6,"req":81717,"rw":{"gold":119,"items":[["10657",1]]},"lv":23,"tr":["Yeni Tarif","Eski kitaptaki tarife göre gidebiliriz: önce 4 damla çayır kartalı gözyaşı topla; kartal cesaret ve gücü simgeler. Eski kayıtlara göre Ork cesaret iksiri hastanın ruhunu tedavi ederek onu iyileştirir.","Kabul","Cesaret iksiri ruhun yaralarını iyileştirir; bu sefer kesin işe yarar!","Güzel, tam istediğim bu!","Çayır Kartalı Gözyaşı"],"en":["A New Recipe","We can follow the recipe from the old book: first collect 4 drops of prairie eagle tears; the eagle stands for courage and vigor. According to the old records, the Orc courage potion cures the sick by healing the soul.","Accept","The courage potion heals the wounds of the soul; this time it can't fail!","Good, that's exactly what I need!","Prairie Eagle Tear"]},{"id":81719,"giver":"兽人医师","to":"兽人医师","type":"collect","target":"☆草原漫游者","count":3,"sc":"野马草原","chance":0.6,"req":81718,"rw":{"gold":151,"items":[]},"lv":24,"tr":["Yardımcı Malzeme","Bu kartal gözyaşları çok sert görünüyor; birinin üstüne dökülse sonu düşünülemez… Velinimetime zarar vermek istemem. Şimdi Yabanat Çayırı'na git ve biraz yılan safrası getir; bu sert gözyaşlarını yumuşatmamız gerek.","Kabul","Tarifin işe yarayacağına inanıyorum!","Artık her şey hazır.","Yılan Safrası"],"en":["Extra Ingredients","These eagle tears look very potent; if they were splashed on someone, it would be unthinkable… I don't want to hurt my benefactor. Now go to the Wild Horse Prairie and bring some snake bile; we need to temper these fierce tears.","Accept","I firmly believe the recipe will work!","Now everything is ready.","Snake Bile"]},{"id":81720,"giver":"兽人医师","to":"兽人医师","type":"talk","count":1,"req":81719,"rw":{"gold":110,"items":[["30024",1]]},"lv0":17,"tr":["Cesaret Aşıla","Yaptığım bu ruh arındırıcı iksire halkımızın biraz cesareti de lazım. Koşanat Şehri'ndeki en yiğit Orka git, iksire cesaretini katsın; bence Muhafız Komutanı en iyi seçim.","Kabul","Cesaret iksiri gerçekten mucizevi.","Sonunda bitti.","Cesaret İksiri"],"en":["Infuse Courage","This soul-cleansing potion I made still needs some of our people's courage. Go to the bravest Orc in Galloping Horse City to infuse it with courage; I think the Guard Captain is the best choice.","Accept","The courage potion is truly miraculous.","Finally, it's done.","Courage Potion"],"lv":20},{"id":81721,"giver":"兽人医师","to":"兽人医师","type":"talk","req":81720,"rw":{"gold":137,"items":[["30024",1]]},"lv0":17,"tr":["Muhtara Yeniden Dene","Ork cesaret iksiri muhtarı mutlaka kendine getirir! Hemen Guanlin Kasabası'na git; muhtarın hastalığını iyileştirebilirsen ilk iş bana haber ver. Ork kahramanları onu korusun.","Kabul","Hı hı.","……"],"en":["Try the Mayor Again","The Orc courage potion will surely bring the mayor back to his senses! Go to Guanlin Town at once; if it cures the mayor's illness, let me know first thing. May the Orc heroes protect him.","Accept","Mm-hm.","……"],"lv":20},{"id":81722,"giver":"兽人医师","to":"炼金师","type":"talk","req":81721,"rw":{"gold":145,"items":[["30024",1]]},"lv0":17,"tr":["Hastalık Değil mi?","Yine mi işe yaramadı? Bu iş çok tuhaf… Ork cesaret iksiri her hastalığı iyileştirir; yoksa muhtar hasta değil mi? Yoksa büyüye mi uğradı? Git, Guanlin Kasabası'ndaki simyacıya sor; çok şey görmüş geçirmiştir.","Kabul","Gerçekten tuhaf.","Sen de muhtar için mi geldin? Ben de bu işi araştırıyorum."],"en":["Not an Illness?","Still no use? This is very strange… The Orc courage potion cures any illness; could it be the mayor isn't sick? Could he be under a spell? Go and ask the alchemist in Guanlin Town; he has seen a great deal.","Accept","Strange indeed.","You've come about the mayor too? I'm looking into this as well."],"lv":20},{"id":81734,"giver":"皇家骑士特使","to":"皇家骑士特使","type":"talk","rw":{"gold":35,"items":[]},"lv0":17,"tr":["Kral ve Dük","Kraliyet Şövalye Elçisi'ni dinle.","Kabul","Kral ile Gümüşkartal Dükü aslında üvey kardeşlerdir. Şimdiki Kral tahta çıkınca aralarındaki çekişme büyüdü… sonra bir de prenses meselesi yüzünden…","İşte böyle."],"en":["The King and the Duke","Listen to the Royal Knight Envoy.","Accept","The King and the Silver Eagle Duke are half-brothers. When the current King took the throne, their rivalry deepened… and then, because of the princess…","And that is how it is."],"lv":20},{"id":81735,"giver":"皇家骑士特使","to":"皇家骑士特使","type":"kill","target":"☆☆【族长】迪莫","count":1,"sc":"银鹰城东北","req":80092,"rw":{"gold":109,"items":[["30024",1]]},"lv":32,"tr":["Korucu Lideri","Gümüşkartal Şehri'nin bir başka korucu reisi Gümüşkartal Şehri Kuzeydoğu'da. Çevik korucularıyla ordumuza sık sık baskın yapıyor! Önce başı ez; git, işini bitir!","Kabul","Korucu birlikleri… düşündükçe başım ağrıyor…","Harika! Çok teşekkür ederim!"],"en":["The Ranger Leader","Another ranger chieftain of Silver Eagle City is in Silver Eagle City Northeast. He often raids our army with his nimble rangers! Strike the head first; go and end his life!","Accept","The ranger troops… thinking about them gives me a headache…","Excellent! Thank you so much!"]},{"id":81739,"giver":"皇家骑士特使","to":"皇家骑士特使","type":"collect","target":"银鹰城剑斗士","count":5,"sc":"银鹰城西北","chance":0.6,"req":81735,"rw":{"gold":118,"items":[]},"lv":34,"tr":["Keskin Kılıç","Başkent ordusu mükemmelliği hedefler; zırhlarımızı delebilecek bir silahın var olmasına asla izin veremeyiz! Gümüşkartal kılıç dövüşçüleri bu silahları taşıyor; cesetlerinden bu kılıçları getir, bizim olsun…","Kabul","Her güzel şey bizim olmalı!","Evet, işte bu kılıç! Gerçekten jilet gibi keskin!","Keskin Kılıç"],"en":["Keen Blade","The Capital's army strives for perfection; we can't allow a weapon that can pierce our armor to exist! The Silver Eagle swordfighters carry such weapons; bring these swords back from their corpses for our use…","Accept","All good things should be ours!","Yes, this is the sword! It's incredibly sharp!","Keen Blade"]},{"id":81740,"giver":"奔马城城主","to":"警卫卡鲁","type":"talk","rw":{"gold":96,"items":[["30024",1]]},"lv0":17,"tr":["Başka Bir Renk","Bunlar ilginç şeyler ama tek renkle bir işe yaramaz. Yoksa bütün trollerin boynuzları aynı renk mi? Bildiğim böyle değil. Dön ve ona söyle, bana başka renklerden de getirsin.","Kabul","Belki de o şanslı ihtiyarı çağırmalıyım.","Peki, bunu zaten tahmin etmiştim."],"en":["Another Color","These are interesting things, but one color alone won't do. Are all troll horns the same color? That's not what I know. Go back and tell him to get me some of other colors.","Accept","Maybe I should call that lucky old man.","Fine, I saw this coming."],"lv":25},{"id":81745,"giver":"皇家骑士特使","to":"皇家骑士特使","type":"kill","target":"☆☆【伯爵】克拉克","count":1,"sc":"银鹰城西北","req":80094,"rw":{"gold":136,"items":[]},"lv":34,"tr":["Çayırdaki Kont","☆☆【Kont】Clark kılıç ustasıdır ve Gümüşkartal ailesinin en güçlü reisidir. Yanında hep usta kılıççı muhafızlar dolaştırdığını duydum. Dostlarını da al, onu öldür; Gümüşkartal Dükü buna çok şaşıracak, belki korkudan altına bile eder, ha ha!","Kabul","Gümüşkartal Dükü'ne büyük bir hediye göndereceğiz!","Bu his gerçekten harika!"],"en":["The Count of the Prairie","☆☆【Count】Clark is a master swordsman and the strongest chieftain of the Silver Eagle family. I hear he always has skilled sword guards with him. Bring your friends and kill him; the Silver Eagle Duke will be stunned, maybe even wet himself in fear, ha ha!","Accept","We'll send the Silver Eagle Duke a big present!","That feels great!"]},{"id":81746,"giver":"皇家骑士特使","to":"战争铁匠","type":"talk","req":81745,"rw":{"gold":102,"items":[["30024",1]]},"lv0":17,"tr":["Keskin Kılıç Malzemesi","Koşanat Şehri'nin çevresi uçsuz bucaksız çayırlar; savaş silahı yapacak malzeme yok denecek kadar az. Cepheye ikmal de azaldı; git, Savaş Demircisi'ne ne yapacağımızı sor.","Kabul","Savaş Demircisi zor zamanlarımızda hep kilit rol oynar.","Hm, Kraliyet Şövalye Elçisi o \"keskin kılıç\"tan seri üretim istemiyor muydu? Bir yolu var!"],"en":["Material for the Keen Blade","Galloping Horse City is surrounded by endless prairie; materials for war weapons are scarce. Supplies from the rear are running low too; go and ask the War Blacksmith what we should do.","Accept","The War Blacksmith always plays a key role when we're in trouble.","Hm, didn't the Royal Knight Envoy want to mass-produce that \"keen blade\"? I have a way!"],"lv":20},{"id":81747,"giver":"战争铁匠","to":"侏儒商队首领","type":"talk","req":81746,"rw":{"gold":72,"items":[]},"lv0":17,"tr":["İyi Kılıç Var","Cüce Kervan Başı iyi dostumdur; seni benim gönderdiğimi söylersen belki yardım eder. Ama cimriliğiyle meşhurdur!","Kabul","Cüce Kervan Başı her yere gidip gelir, mutlaka bir yolunu bulur.","Madem Savaş Demircisi gönderdi, sana yardım edeceğim!"],"en":["A Good Sword","The Gnome Caravan Leader is a good friend of mine; if you say I sent you, he might help. But he's famously stingy!","Accept","The Gnome Caravan Leader travels everywhere; he'll surely find a way.","Since the War Blacksmith sent you, I'll help you!"],"lv":25},{"id":81748,"giver":"侏儒商队首领","to":"战争铁匠","type":"collect","target":"☆觅血妖刀","count":5,"sc":"罪恶庭院","chance":0.6,"req":81747,"rw":{"gold":155,"items":[]},"lv":10,"tr":["Hm, Stokta Var","Oo! Demek seni elçi gönderdi! Ne? Cüceler cimri diyen kim! Bu ırkımıza hakaret! O keskin kılıç malzemesi bende stokta var! Hepsini sana hediye ediyorum! Yalnız… kısa süre önce bir grup ☆tarikatçı onları kaptı; o herifler çok korkunç! Peki, geri alabilirsen senin olsun!","Kabul","O tarikatçılar çok çirkin; onlara yol verdim de uğraşmadım.","O cimri cücenin bunları sana bedava vereceği hiç aklıma gelmezdi; gerçek bir mucize.","Kırık Demir Parçası"],"en":["Hm, I Have Stock","Oh! So the envoy sent you! What? Who says gnomes are stingy! That's an insult to our race! I have those keen blade materials in stock! I'll give them all to you! Only… not long ago a band of ☆cultists stole them; those fellows are terrifying! Well, if you can get them back, they're yours!","Accept","Those cultists are really ugly; I just let them be.","I never thought that stingy gnome would really give them to you for free; a true miracle.","Broken Iron Chunk"]},{"id":81757,"giver":"皇家骑士特使","to":"皇家骑士特使","type":"collect","target":"☆银鹰碎颅者","count":10,"sc":"草原前线","chance":0.5,"rw":{"gold":120,"items":[["30024",1]]},"lv":29,"tr":["Üstün İşçilik","Bazen o asilerin hazinedarlarını çok kıskanıyorum; ellerinde harcayacak bol altın var. Bu yüzden savaşçıları hep en iyi miğferleri takar. Paramız buna yetmiyorsa en azından yağmalayabiliriz. Ama önce o kafa kırıcıları susturman gerek.","Kabul","Onları konuşarak miğferlerini sana uslu uslu vermeye ikna edersen ona da itirazım yok.","Şu parlak zırhlara bak; giyen bir daha çıkarmak ister mi?","Gümüşkartal Savaş Miğferi"],"en":["Fine Craftsmanship","Sometimes I really envy those rebel treasurers; they always have plenty of gold to spend. That's why their warriors always wear the best helmets. If money holds us back, at least we can plunder. But first you must silence those skullcrushers.","Accept","I don't mind if you talk them into handing over their armor nicely.","Look at this shiny armor; who would ever take it off once it's on?","Silver Eagle War Helm"]},{"id":81758,"giver":"奔马城城主","to":"奔马城城主","type":"collect","target":"☆巨魔摧毁者","count":10,"sc":"巨魔森林","chance":0.5,"rw":{"gold":133,"items":[]},"lv":28,"tr":["Sıcak Giysiler","Hava gittikçe soğuyor, lanet olsun; cüceler kışı seven yaratıklar değildir. Hey, cebimden biraz altın almak ister misin? Ondan önce Trol Ormanı'na gidip o yok edicilerden biraz yele toplamalısın; ondan bir palto yaptırmak istiyorum.","Kabul","O şey soğuğa karşı çok dayanıklıdır.","Sadece elimde tutarken bile soğuğu hissetmiyorum.","Trol Yelesi"],"en":["Warm Clothes","It's getting colder and colder, damn it; gnomes are not creatures who love winter. Hey, want to take some gold from my pocket? Before that, go to the Troll Forest and collect some mane from those destroyers; I want a coat made of it.","Accept","That stuff is very resistant to cold.","Just holding it, I don't feel the cold at all.","Troll Mane"]},{"id":81759,"giver":"奔马城城主","to":"观林镇镇长","type":"talk","count":1,"req":81758,"rw":{"gold":173,"items":[["30024",1]]},"lv0":17,"tr":["Şehir Beyinin Hediyesi","Geçenlerde Guanlin Kasabası muhtarından bir mektup aldım; bana gençliğimde Guanlin'de geçen günleri hatırlattı. O zaman ben de sizin muhtarınız da gençtik, tıpkı şimdi senin gibi. Güzel ve mutlu zamanlardı… Bak yine gevezelik ediyorum; demek istediğim, o yelelerden fazladan bir giysi çıktı. Onu muhtara götür; o yaşta soğuktan çok korkar.","Kabul","Gençlik bir servettir.","İlginç bir adam, değil mi?","Sıcak Kışlık Giysi"],"en":["The Lord's Gift","Recently I received a letter from the mayor of Guanlin Town; it reminded me of my youth in Guanlin. Back then your mayor and I were young, just like you are now. Those were good and happy times… There I go rambling again; what I mean is, those manes made one coat too many. Take it to the mayor; at his age he must fear the cold.","Accept","Youth is a treasure.","He's an interesting fellow, isn't he?","Warm Winter Coat"],"lv":25},{"id":81760,"giver":"战争铁匠","to":"皇家骑士特使","type":"talk","req":81748,"rw":{"gold":58,"items":[["30024",1]]},"lv0":17,"tr":["Tam Kapasite Üretim","Dön ve Kraliyet Şövalye Elçisi'ne bildir: arka cephe hazır, hemen tam kapasite üretime geçiyoruz!","Kabul","İçi rahat olsun, elimizden geleni yapacağız!","Güzel! Cepheden saldırıya hazırlanın!"],"en":["Full Production","Go back and report to the Royal Knight Envoy: the rear is ready, and we're moving to full production at once!","Accept","Tell him to rest easy; we'll give it our all!","Good! Prepare for a frontal assault!"],"lv":25}];
  for (const q of Q) {
    const s = E ? q.en : q.tr, to = trName(q.to), sc = q.sc ? trName(q.sc) : '', mon = q.target ? trName(q.target) : '';
    q.title = s[0]; q.text = s[1]; q.ok = s[2]; q.wait = s[3]; q.done = s[4]; if (s[5]) q.item = s[5];
    q.goal = q.type === 'kill' ? (E ? `Kill ${q.count} ${mon} in ${sc}, then talk to ${to}.` : `${sc}: ${q.count} ${mon} öldür, sonra ${to} ile konuş.`)
      : q.type === 'collect' ? (E ? `Collect ${q.count} ${q.item} from ${mon} in ${sc}, then talk to ${to}.` : `${sc}: ${mon} canavarlarından ${q.count} ${q.item} topla, sonra ${to} ile konuş.`)
      : q.type === 'pickup' ? (E ? `Gather ${q.count} ${q.item} in ${sc}, then talk to ${to}.` : `${sc}: ${q.count} ${q.item} topla, sonra ${to} ile konuş.`)
      : q.item ? (E ? `Take the ${q.item} to ${to}.` : `${q.item} eşyasını ${to} kişisine götür.`)
      : (E ? `Talk to ${to}.` : `${to} ile konuş.`);
    delete q.tr; delete q.en; QUESTS.push(q);
  }
})();
